    def _factor_universe_symbols(self, universe: Any) -> list[str]:
        normalized = str(universe or "SP500").strip().upper()
        if normalized in DEFAULT_UNIVERSE_SYMBOLS:
            return list(DEFAULT_UNIVERSE_SYMBOLS[normalized])
        symbols = [
            str(item).strip().upper()
            for item in re.split(r"[,;\s]+", str(universe or ""))
            if str(item).strip()
        ]
        return symbols or list(DEFAULT_UNIVERSE_SYMBOLS["SP500"])

    @staticmethod
    def _factor_finite_float(value: Any) -> float | None:
        try:
            parsed = float(value)
        except (TypeError, ValueError):
            return None
        return parsed if math.isfinite(parsed) else None

    @staticmethod
    def _factor_score_direction(direction: Any) -> str:
        normalized = str(direction or "").strip().upper()
        if normalized in {"LOW_IS_BETTER", "LOW_IS_GOOD", "LOWER_IS_BETTER"}:
            return "LOWER_IS_BETTER"
        return "HIGHER_IS_BETTER"

    @staticmethod
    def _factor_latest_snapshot_date(snapshots: Sequence[Mapping[str, Any]], snapshot_id: str) -> str | None:
        for snapshot in snapshots:
            if str(snapshot.get("id") or "") == snapshot_id:
                return str(snapshot.get("as_of") or snapshot.get("end_date") or "").strip() or None
        return None

    def _factor_preview_as_of(self, payload: Mapping[str, Any]) -> str:
        requested = str(payload.get("as_of_date") or "").strip()
        if requested:
            return requested
        try:
            snapshots = self.market_data_repository.list_dataset_snapshots()
        except Exception:
            snapshots = []
        return (
            self._factor_latest_snapshot_date(snapshots, DATASET_PRICE_SNAPSHOT_ID)
            or self._factor_latest_snapshot_date(snapshots, DATASET_FUNDAMENTALS_SNAPSHOT_ID)
            or date.today().isoformat()
        )

    def _factor_preview_price_rows(self, symbols: Sequence[str], as_of_date: str) -> dict[str, list[dict[str, Any]]]:
        try:
            as_of = _parse_iso_date(as_of_date)
            start_date = (as_of - timedelta(days=620)).isoformat()
        except ValueError:
            start_date = None
        try:
            return self.market_data_repository.load_dataset_price_bars(
                DATASET_PRICE_SNAPSHOT_ID,
                symbols,
                start_date=start_date,
                end_date=as_of_date,
                include_metadata=False,
            )
        except Exception:
            return {}

    def _factor_mining_market_data(
        self,
        symbols: Sequence[str],
        *,
        start_date: str,
        end_date: str,
    ) -> dict[str, dict[str, list[float]]]:
        try:
            start = _parse_iso_date(start_date)
            warmup_start = (start - timedelta(days=420)).isoformat()
        except ValueError:
            warmup_start = None
        try:
            rows_by_symbol = self.market_data_repository.load_dataset_price_bars(
                DATASET_PRICE_SNAPSHOT_ID,
                symbols,
                start_date=warmup_start,
                end_date=end_date or None,
                include_metadata=False,
            )
        except Exception as exc:
            raise ValueError("因子挖掘需要可读取的价格快照，当前无法读取 ds-price。") from exc

        market_data: dict[str, dict[str, list[float]]] = {}
        for symbol in symbols:
            closes: list[float] = []
            volumes: list[float] = []
            for row in rows_by_symbol.get(str(symbol).strip().upper(), []):
                if not isinstance(row, Mapping):
                    continue
                close = self._factor_finite_float(row.get("adj_close", row.get("close")))
                if close is not None:
                    closes.append(close)
                    volume = self._factor_finite_float(row.get("volume"))
                    volumes.append(volume if volume is not None else 0.0)
            if len(closes) >= 6:
                entry = {"Close": closes}
                if len(volumes) == len(closes):
                    entry["Volume"] = volumes
                market_data[str(symbol).strip().upper()] = entry

        if len(market_data) < 2:
            raise ValueError("因子挖掘需要至少两个标的具备运行时价格快照，不能使用 synthetic 或静态样例数据补齐。")
        return market_data

    def _factor_preview_fundamentals(self, symbols: Sequence[str], as_of_date: str) -> dict[str, dict[str, Any]]:
        try:
            grouped = self.market_data_repository.load_dataset_fundamental_points(
                DATASET_FUNDAMENTALS_SNAPSHOT_ID,
                symbols,
                as_of_date=as_of_date,
            )
        except Exception:
            return {}
        latest: dict[str, dict[str, Any]] = {}
        for symbol, rows in grouped.items():
            ordered = [dict(row) for row in rows if isinstance(row, Mapping)]
            if ordered:
                latest[str(symbol).strip().upper()] = ordered[-1]
        return latest

    def _factor_expression_input(
        self,
        price_rows: Sequence[Mapping[str, Any]],
        fundamental: Mapping[str, Any] | None,
    ) -> dict[str, list[float | None]]:
        closes = [
            self._factor_finite_float(row.get("adj_close", row.get("close")))
            for row in price_rows
            if isinstance(row, Mapping)
        ]
        length = len(closes) if closes else 1
        data: dict[str, list[float | None]] = {}
        if closes:
            data["Close"] = closes
        fundamental = fundamental or {}
        for canonical_name, aliases in FIELD_ALIASES.items():
            if canonical_name == "Close":
                continue
            value = None
            for alias in aliases:
                value = self._factor_finite_float(fundamental.get(alias))
                if value is not None:
                    break
            if value is not None:
                data[canonical_name] = [value] * length
        return data

    def _factor_expression_latest_value(
        self,
        expression: str,
        price_rows: Sequence[Mapping[str, Any]],
        fundamental: Mapping[str, Any] | None,
    ) -> float | None:
        series = self._factor_expression_series(
            expression,
            price_rows,
            [fundamental] if isinstance(fundamental, Mapping) else None,
        )
        for value in reversed(series):
            if value is not None:
                return value
        return None

    def _factor_ffblend_series(
        self,
        data: Mapping[str, Sequence[float | int | None]],
    ) -> list[float | None]:
        closes = list(data.get("Close") or [])
        length = len(closes)
        market_caps = list(data.get("MarketCap") or [])
        ltm_earnings = list(data.get("LtmEarnings") or [])
        book_values = list(data.get("BookValueEquity") or [])

        def value_at(series: Sequence[float | int | None], index: int) -> float | None:
            if index >= len(series):
                return None
            return self._factor_finite_float(series[index])

        scores: list[float | None] = []
        for index, value in enumerate(closes):
            current = self._factor_finite_float(value)
            prior = self._factor_finite_float(closes[index - 252]) if index >= 252 else None
            market_cap = value_at(market_caps, index)
            if current is None or prior is None or prior <= 0 or market_cap is None or market_cap <= 0:
                scores.append(None)
                continue
            earnings = value_at(ltm_earnings, index) or 0.0
            book_value = value_at(book_values, index) or 0.0
            momentum = current / prior - 1.0
            earnings_yield = earnings / market_cap
            roe = earnings / book_value if book_value > 0 else 0.0
            size_penalty = math.log(market_cap)
            score = 0.45 * momentum + 1.5 * earnings_yield + 0.5 * roe - 0.02 * size_penalty
            scores.append(score if math.isfinite(score) else None)
        if len(scores) < length:
            scores.extend([None] * (length - len(scores)))
        return scores[:length]

    def _factor_expression_series(
        self,
        expression: str,
        price_rows: Sequence[Mapping[str, Any]],
        fundamental_rows: Sequence[Mapping[str, Any]] | None,
    ) -> list[float | None]:
        normalized_price_rows = [dict(row) for row in price_rows if isinstance(row, Mapping)]
        if not normalized_price_rows:
            return []
        closes = [
            self._factor_finite_float(row.get("adj_close", row.get("close")))
            for row in normalized_price_rows
        ]
        if not any(value is not None for value in closes):
            return []
        data: dict[str, list[float | None]] = {"Close": closes}
        ordered_fundamentals = [
            dict(row)
            for row in (fundamental_rows or [])
            if isinstance(row, Mapping)
        ]
        ordered_fundamentals.sort(
            key=lambda item: (
                str(item.get("available_at") or item.get("date") or ""),
                str(item.get("date") or ""),
            )
        )
        if ordered_fundamentals:
            price_dates = [str(row.get("date") or "") for row in normalized_price_rows]
            for canonical_name, aliases in FIELD_ALIASES.items():
                if canonical_name == "Close":
                    continue
                latest_value = None
                values: list[float | None] = []
                point_index = 0
                for price_date in price_dates:
                    while point_index < len(ordered_fundamentals):
                        point = ordered_fundamentals[point_index]
                        point_date = str(point.get("available_at") or point.get("date") or "")
                        if point_date > price_date:
                            break
                        for alias in aliases:
                            candidate = self._factor_finite_float(point.get(alias))
                            if candidate is not None:
                                latest_value = candidate
                                break
                        point_index += 1
                    values.append(latest_value)
                if any(value is not None for value in values):
                    data[canonical_name] = values
        if re.search(r"\bFFBlend\s*\(", str(expression or ""), flags=re.IGNORECASE):
            return self._factor_ffblend_series(data)
        try:
            series = evaluate_expression(expression, data)
        except (FactorExpressionError, ValueError, TypeError, ZeroDivisionError):
            return [None] * len(normalized_price_rows)
        normalized_series = [self._factor_finite_float(value) for value in series[: len(normalized_price_rows)]]
        if len(normalized_series) < len(normalized_price_rows):
            normalized_series.extend([None] * (len(normalized_price_rows) - len(normalized_series)))
        return normalized_series

    def _factor_industry_snapshot(
        self,
        symbols: Sequence[str],
        universe: Any,
        as_of_date: str,
    ) -> dict[str, Any]:
        normalized_symbols = sorted({str(symbol).strip().upper() for symbol in symbols if str(symbol).strip()})
        if not normalized_symbols:
            return {
                "mapping": {},
                "taxonomy": "GICS",
                "industry_field": "universe_membership_snapshots.metadata.gics_sector",
                "covered_symbol_count": 0,
                "missing_symbol_count": 0,
                "missing_symbols": [],
                "source_names": [],
            }
        symbol_set = set(normalized_symbols)
        try:
            histories = self._factor_industry_histories(normalized_symbols, universe, as_of_date)
        except Exception:
            return {
                "mapping": {},
                "taxonomy": "GICS",
                "industry_field": "universe_membership_snapshots.metadata.gics_sector",
                "covered_symbol_count": 0,
                "missing_symbol_count": len(symbol_set),
                "missing_symbols": sorted(symbol_set),
                "source_names": [],
            }
        return self._factor_industry_snapshot_from_histories(normalized_symbols, as_of_date, histories)

    def _factor_industry_membership_selector(self, universe: Any) -> tuple[str | None, str | None]:
        normalized_universe = str(universe or "SP500").strip().upper()
        snapshot_id = SP500_UNIVERSE_SNAPSHOT_ID if normalized_universe == "SP500" else None
        if normalized_universe == "NASDAQ100":
            snapshot_id = NASDAQ100_UNIVERSE_SNAPSHOT_ID
        return snapshot_id, None if snapshot_id else normalized_universe

    def _factor_industry_histories(
        self,
        symbols: Sequence[str],
        universe: Any,
        effective_date_lte: str,
    ) -> dict[str, list[tuple[str, str, str]]]:
        normalized_symbols = sorted({str(symbol).strip().upper() for symbol in symbols if str(symbol).strip()})
        if not normalized_symbols:
            return {}
        snapshot_id, universe_key = self._factor_industry_membership_selector(universe)
        memberships = self.market_data_repository.load_universe_memberships(
            universe_snapshot_id=snapshot_id,
            universe_key=universe_key,
            effective_date_lte=effective_date_lte,
            symbols=normalized_symbols,
            active_only=True,
        )
        histories: dict[str, list[tuple[str, str, str]]] = {}
        industry_keys = (
            "gics_sector",
            "GICS Sector",
            "sector",
            "sector_name",
            "gics_industry",
            "gics_industry_group",
            "industry",
            "industry_name",
        )
        for row in memberships:
            symbol = str(row.get("symbol") or "").strip().upper()
            effective_date = str(row.get("effective_date") or "").strip()
            membership_status = str(row.get("membership_status") or "ACTIVE").strip().upper()
            if (
                symbol not in normalized_symbols
                or not effective_date
                or effective_date > effective_date_lte
                or membership_status in {"REMOVED", "DELETED", "INACTIVE", "OUT", "EXCLUDED"}
            ):
                continue
            metadata = row.get("metadata") if isinstance(row.get("metadata"), Mapping) else {}
            industry = ""
            for key in industry_keys:
                industry = str(row.get(key) or metadata.get(key) or "").strip()
                if industry:
                    break
            if not industry:
                continue
            source_name = str(
                metadata.get("industry_classification_source")
                or row.get("source")
                or metadata.get("source")
                or ""
            ).strip()
            history = histories.setdefault(symbol, [])
            entry = (effective_date, industry, source_name)
            if history and history[-1][0] == effective_date:
                history[-1] = entry
            else:
                history.append(entry)
        return histories

    def _factor_industry_snapshot_from_histories(
        self,
        symbols: Sequence[str],
        as_of_date: str,
        histories: Mapping[str, Sequence[tuple[str, str, str]]],
    ) -> dict[str, Any]:
        normalized_symbols = sorted({str(symbol).strip().upper() for symbol in symbols if str(symbol).strip()})
        mapping: dict[str, str] = {}
        missing_symbols: list[str] = []
        source_names: set[str] = set()
        for symbol in normalized_symbols:
            history = list(histories.get(symbol) or [])
            if not history:
                missing_symbols.append(symbol)
                continue
            history_dates = [entry[0] for entry in history]
            history_index = bisect_right(history_dates, as_of_date) - 1
            if history_index < 0:
                missing_symbols.append(symbol)
                continue
            _effective_date, industry, source_name = history[history_index]
            if not industry:
                missing_symbols.append(symbol)
                continue
            mapping[symbol] = industry
            if source_name:
                source_names.add(source_name)
        return {
            "mapping": mapping,
            "taxonomy": "GICS",
            "industry_field": "universe_membership_snapshots.metadata.gics_sector",
            "covered_symbol_count": len(mapping),
            "missing_symbol_count": len(missing_symbols),
            "missing_symbols": missing_symbols,
            "source_names": sorted(source_names),
        }

    def _precompute_factor_industry_mappings(
        self,
        symbols: Sequence[str],
        universe: Any,
        as_of_dates: Sequence[str],
    ) -> dict[str, dict[str, str]]:
        normalized_symbols = sorted({str(symbol).strip().upper() for symbol in symbols if str(symbol).strip()})
        normalized_dates = sorted({str(value).strip() for value in as_of_dates if str(value).strip()})
        if not normalized_symbols or not normalized_dates:
            return {}
        try:
            histories = self._factor_industry_histories(normalized_symbols, universe, normalized_dates[-1])
        except Exception:
            return {}
        cursors = {symbol: 0 for symbol in normalized_symbols}
        active_entries: dict[str, tuple[str, str]] = {}
        mappings: dict[str, dict[str, str]] = {}
        for as_of_date in normalized_dates:
            mapping: dict[str, str] = {}
            for symbol in normalized_symbols:
                history = histories.get(symbol) or []
                cursor = cursors.get(symbol, 0)
                while cursor < len(history) and history[cursor][0] <= as_of_date:
                    _effective_date, industry, source_name = history[cursor]
                    active_entries[symbol] = (industry, source_name)
                    cursor += 1
                cursors[symbol] = cursor
                active_entry = active_entries.get(symbol)
                if active_entry and active_entry[0]:
                    mapping[symbol] = active_entry[0]
            mappings[as_of_date] = mapping
        return mappings

    def _factor_industry_mapping(
        self,
        symbols: Sequence[str],
        universe: Any,
        as_of_date: str,
    ) -> dict[str, str]:
        snapshot = self._factor_industry_snapshot(symbols, universe, as_of_date)
        mapping = snapshot.get("mapping") if isinstance(snapshot, Mapping) else {}
        return dict(mapping) if isinstance(mapping, Mapping) else {}

    def _factor_model_score_projection(
        self,
        normalized_weights: Sequence[Mapping[str, Any]],
        factor_by_id: Mapping[str, Mapping[str, Any]],
        symbols: Sequence[str],
        *,
        as_of_date: str,
        neutralization: Mapping[str, Any],
        universe: Any,
    ) -> dict[str, Any]:
        price_rows = self._factor_preview_price_rows(symbols, as_of_date)
        fundamentals = self._factor_preview_fundamentals(symbols, as_of_date)
        factor_scores: dict[str, dict[str, float | None]] = {}
        for component in normalized_weights:
            factor_id = str(component.get("factor_id") or "")
            factor = factor_by_id.get(factor_id) or {}
            expression = str(factor.get("expression") or "").strip()
            raw_values = {
                symbol: self._factor_expression_latest_value(
                    expression,
                    price_rows.get(symbol, []),
                    fundamentals.get(symbol),
                )
                for symbol in symbols
            }
            normalized = normalize_cross_section(
                raw_values,
                direction=self._factor_score_direction(component.get("direction") or factor.get("direction")),
            )
            factor_scores[factor_id] = normalized.scores

        combined_scores: dict[str, float | None] = {}
        symbol_coverages: dict[str, float] = {}
        available_score_count = 0
        for symbol in symbols:
            combined = 0.0
            available = 0
            for component in normalized_weights:
                factor_id = str(component.get("factor_id") or "")
                score = factor_scores.get(factor_id, {}).get(symbol)
                if score is None:
                    continue
                combined += _coerce_float(component.get("normalized_weight"), 0.0) * score
                available += 1
            available_score_count += available
            symbol_coverages[symbol] = round(available / max(len(normalized_weights), 1), 4)
            combined_scores[symbol] = round(combined, 6) if available else None

        industry_snapshot = self._factor_industry_snapshot(symbols, universe, as_of_date)
        industry_by_symbol = dict(industry_snapshot.get("mapping") or {})
        neutralization_result = neutralize_by_industry(
            combined_scores,
            enabled=bool(neutralization.get("enabled")),
            industry_by_symbol=industry_by_symbol or None,
        )
        final_scores = neutralization_result.values
        scored_rows = [
            {
                "symbol": symbol,
                "score": round(float(score), 4),
                "coverage": symbol_coverages.get(symbol, 0.0),
            }
            for symbol, score in final_scores.items()
            if score is not None and math.isfinite(float(score))
        ]
        scored_rows.sort(key=lambda item: item["score"], reverse=True)
        score_values = [row["score"] for row in scored_rows]
        score_spread = (max(score_values) - min(score_values)) if score_values else 0.0
        coverage_ratio = available_score_count / max(len(symbols) * len(normalized_weights), 1)
        estimated_turnover = min(0.95, max(0.02, 0.04 + min(score_spread, 6.0) * 0.025 + len(normalized_weights) * 0.006))
        return {
            "score_preview": scored_rows[:8],
            "scored_rows": scored_rows,
            "coverage_ratio": round(coverage_ratio, 4),
            "estimated_turnover": round(estimated_turnover, 4),
            "neutralization_result": neutralization_result,
            "industry_by_symbol": industry_by_symbol,
            "industry_field": industry_snapshot.get("industry_field"),
            "industry_coverage": {
                key: value for key, value in industry_snapshot.items() if key != "mapping"
            },
        }

    def _decode_factor_mining_job_row(self, row: Mapping[str, Any]) -> dict[str, Any]:
        request = loads(row.get("request_json"), {})
        progress = loads(row.get("progress_json"), {})
        top_candidates = loads(row.get("top_candidates_json"), [])
        failed_samples = loads(row.get("failed_samples_json"), [])
        top_candidate_items = top_candidates if isinstance(top_candidates, list) else []
        return {
            "id": row.get("id"),
            "status": row.get("status"),
            "request": request,
            "progress": progress,
            "top_candidates": self._dedupe_factor_mining_candidates(top_candidate_items),
            "failed_samples": failed_samples if isinstance(failed_samples, list) else [],
            "summary": loads(row.get("summary_json"), {}),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
            "completed_at": row.get("completed_at"),
            "error_message": row.get("error_message"),
        }

    def _factor_mining_request_signature(self, request: Mapping[str, Any]) -> tuple[Any, ...]:
        symbols_value = request.get("symbols")
        symbols = symbols_value if isinstance(symbols_value, Sequence) and not isinstance(symbols_value, (str, bytes)) else ()
        universe = str(request.get("universe") or ",".join(str(symbol) for symbol in symbols) or "").strip().upper()
        operators_value = request.get("operators")
        operators = (
            operators_value
            if isinstance(operators_value, Sequence) and not isinstance(operators_value, (str, bytes))
            else ()
        )
        operator_key = tuple(sorted(str(operator).strip().lower() for operator in operators if str(operator).strip()))
        try:
            candidate_count = int(request.get("candidate_count") or 0)
        except (TypeError, ValueError):
            candidate_count = 0
        try:
            max_depth = int(request.get("max_depth") or 0)
        except (TypeError, ValueError):
            max_depth = 0
        source_factor_ids = request.get("source_factor_ids")
        if not isinstance(source_factor_ids, Sequence) or isinstance(source_factor_ids, (str, bytes)):
            source_factor_ids = ()
        recipe_families = request.get("recipe_families")
        if not isinstance(recipe_families, Sequence) or isinstance(recipe_families, (str, bytes)):
            recipe_families = ()
        try:
            exploration_budget = int(request.get("exploration_budget") or 0)
        except (TypeError, ValueError):
            exploration_budget = 0
        policy = request.get("composition_policy")
        policy_key = dumps(dict(sorted(policy.items()))) if isinstance(policy, Mapping) else "{}"
        min_rank_ic = round(_coerce_float(request.get("min_rank_ic")), 6)
        return (
            universe,
            str(request.get("start_date") or "").strip(),
            str(request.get("end_date") or "").strip(),
            operator_key,
            candidate_count,
            min_rank_ic,
            max_depth,
            str(request.get("generation_mode") or "PRICE_OPERATOR").strip().upper(),
            tuple(sorted(str(item).strip().lower() for item in source_factor_ids if str(item).strip())),
            tuple(sorted(str(item).strip().lower() for item in recipe_families if str(item).strip())),
            max(0, exploration_budget),
            policy_key,
        )

    def _factor_mining_row_signature(self, row: Mapping[str, Any]) -> tuple[Any, ...]:
        request = loads(row.get("request_json"), {})
        return self._factor_mining_request_signature(request if isinstance(request, Mapping) else {})

    def _dedupe_factor_mining_job_rows(self, rows: Sequence[Mapping[str, Any]]) -> list[Mapping[str, Any]]:
        seen: set[tuple[Any, ...]] = set()
        deduped_rows: list[Mapping[str, Any]] = []
        for row in rows:
            signature = self._factor_mining_row_signature(row)
            if signature in seen:
                continue
            seen.add(signature)
            deduped_rows.append(row)
        return deduped_rows

    def _find_factor_mining_duplicate_job_row(
        self,
        signature: tuple[Any, ...],
    ) -> Mapping[str, Any] | None:
        rows = self.storage.fetch_all(
            """
            SELECT *
            FROM factor_mining_jobs
            ORDER BY created_at DESC, id DESC
            LIMIT 50
            """
        )
        for row in rows:
            if self._factor_mining_row_signature(row) == signature:
                return row
        return None

    def _dedupe_factor_mining_candidates(self, candidates: Sequence[Any]) -> list[Any]:
        seen: set[str] = set()
        deduped_candidates: list[Any] = []
        for candidate in candidates:
            if not isinstance(candidate, Mapping):
                continue
            expression = " ".join(str(candidate.get("expression") or "").split()).lower()
            signature = expression or str(candidate.get("id") or candidate.get("candidate_id") or "").strip().lower()
            if not signature or signature in seen:
                continue
            seen.add(signature)
            deduped_candidates.append(candidate)
        return deduped_candidates

    def _factor_factory_today(self) -> str:
        return datetime.now(timezone(timedelta(hours=8))).date().isoformat()

    def _factor_factory_default_request(self) -> dict[str, Any]:
        return {
            "universe": "SP500",
            "start_date": "2018-01-01",
            "end_date": "2024-12-31",
            "operators": ["return", "rank", "zscore", "winsorize"],
            "candidate_count": 40,
            "random_seed": 42,
            "min_rank_ic": 0.03,
            "max_depth": 4,
            "generation_mode": "HYBRID_COMPOSITION",
            "source_factor_ids": [
                "s_mom_6m_rank",
                "s_qlty_roe_ltm_raw",
                "s_vol_252d_rank",
                "s_val_cfp_ltm_raw",
                "s_size_cur_log",
                "s_vol_downside_252d_rank",
                "s_liq_amihud_20d_rank",
            ],
            "recipe_families": [
                "style_blend",
                "risk_adjusted",
                "value_anchor",
                "rank_pooling",
                "ffblend_style",
                "divergence",
                "residual_neutralized",
                "ts_denoise",
            ],
            "exploration_budget": 24,
            "composition_policy": {
                "mode": "template_plus_exploration",
                "publish_boundary": "manual_after_quarantine",
                "prefer_cross_family": True,
                "auto_intake_to_quarantine": True,
            },
        }

    def _factor_factory_default_gate_policy(self) -> dict[str, Any]:
        return {
            "pit_gate_mode": "DIAGNOSTIC_ONLY",
            "max_style_correlation": 0.3,
            "residual_enabled": True,
            "max_drawdown_relative_to_benchmark": 1.5,
            "min_oos_to_is_ratio": 0.6,
            "p_value_max": 0.05,
            "max_s_grade_correlation": 0.70,
            "capacity_floor": 0.0,
            "crowding_max": 1.0,
        }

    def _factor_factory_request_payload(self, request: Any | None) -> dict[str, Any]:
        payload = dict(_as_mapping(request or {}))
        nested_request = payload.get("request")
        if isinstance(nested_request, Mapping):
            request_payload = dict(nested_request)
        else:
            request_payload = {
                key: payload[key]
                for key in (
                    "universe",
                    "start_date",
                    "end_date",
                    "operators",
                    "candidate_count",
                    "random_seed",
                    "min_rank_ic",
                    "max_depth",
                    "generation_mode",
                    "source_factor_ids",
                    "recipe_families",
                    "exploration_budget",
                    "composition_policy",
                    "composition_methods",
                )
                if key in payload
            }
        defaults = self._factor_factory_default_request()
        merged = {**defaults, **request_payload}
        merged["operators"] = list(merged.get("operators") or defaults["operators"])
        merged["source_factor_ids"] = list(merged.get("source_factor_ids") or defaults["source_factor_ids"])
        merged["recipe_families"] = list(merged.get("recipe_families") or defaults["recipe_families"])
        merged["composition_policy"] = {
            **dict(defaults.get("composition_policy") or {}),
            **dict(merged.get("composition_policy") or {}),
        }
        return merged

    def _factor_factory_gate_policy_payload(self, request: Any | None) -> dict[str, Any]:
        payload = dict(_as_mapping(request or {}))
        policy = payload.get("gate_policy")
        if not isinstance(policy, Mapping):
            policy = {}
        return {**self._factor_factory_default_gate_policy(), **dict(policy)}

    def _factor_factory_operator_config_payload(self, request: Any | None) -> dict[str, Any]:
        payload = dict(_as_mapping(request or {}))
        direct = {
            key: payload[key]
            for key in (
                "enabled_operators",
                "window_space",
                "default_depth",
                "daily_formula_budget",
                "compute_backend",
                "min_periods_policy",
                "blocked_field_policy",
                "governance_protocol",
                "composition_methods",
                "notes",
            )
            if key in payload
        }
        nested = payload.get("operator_config")
        if isinstance(nested, Mapping):
            direct.update(dict(nested))
        return normalize_operator_config(direct or default_operator_config())

    def _latest_f1_catalog_snapshot_row(self) -> Mapping[str, Any] | None:
        return self.storage.fetch_one(
            """
            SELECT *
            FROM f1_raw_factor_catalog_snapshots
            ORDER BY generated_at DESC, snapshot_id DESC
            LIMIT 1
            """
        )

    def _latest_operator_config_snapshot_row(self) -> Mapping[str, Any] | None:
        return self.storage.fetch_one(
            """
            SELECT *
            FROM operator_registry_snapshots
            ORDER BY generated_at DESC, snapshot_id DESC
            LIMIT 1
            """
        )

    def _decode_operator_config_snapshot_row(self, row: Mapping[str, Any] | None, *, include_items: bool = True) -> dict[str, Any] | None:
        if not row:
            return None
        snapshot_id = str(row.get("snapshot_id") or row.get("id") or "")
        items: list[dict[str, Any]] = []
        if include_items and snapshot_id:
            item_rows = self.storage.fetch_all(
                """
                SELECT *
                FROM operator_registry_items
                WHERE snapshot_id = ?
                ORDER BY operator_group, operator_id
                """,
                (snapshot_id,),
            )
            for item in item_rows:
                items.append({
                    "operator_id": item.get("operator_id"),
                    "operator_group": item.get("operator_group"),
                    "enabled": bool(item.get("enabled")),
                    "display_name": item.get("display_name"),
                    "definition": item.get("definition"),
                    "economic_meaning": item.get("economic_meaning"),
                    "input_types": loads(item.get("input_types_json"), []),
                    "output_dimension": item.get("output_dimension"),
                    "default_params": loads(item.get("default_params_json"), {}),
                    "allowed_window_space": loads(item.get("allowed_window_space_json"), []),
                    "min_periods_rule": item.get("min_periods_rule"),
                    "domain_rules": loads(item.get("domain_rules_json"), {}),
                    "metadata": loads(item.get("metadata_json"), {}),
                })
        return {
            "id": snapshot_id,
            "snapshot_id": snapshot_id,
            "generated_at": row.get("generated_at"),
            "status": row.get("status"),
            "default_depth": int(row.get("default_depth") or 2),
            "daily_formula_budget": int(row.get("daily_formula_budget") or DEFAULT_DAILY_FORMULA_BUDGET),
            "compute_backend": row.get("compute_backend") or DEFAULT_COMPUTE_BACKEND,
            "window_space": loads(row.get("window_space_json"), []),
            "enabled_operators": loads(row.get("enabled_operators_json"), []),
            "operator_count": int(row.get("operator_count") or 0),
            "min_periods_policy": row.get("min_periods_policy"),
            "blocked_field_policy": row.get("blocked_field_policy"),
            "governance_protocol": loads(row.get("governance_protocol_json"), {}),
            "composition_methods": normalize_operator_config({
                "composition_methods": loads(row.get("composition_methods_json"), []),
            }).get("composition_methods", default_operator_config().get("composition_methods", [])),
            "created_by": row.get("created_by"),
            "notes": row.get("notes"),
            "created_at": row.get("created_at"),
            "items": items,
        }

    def _ensure_f1_catalog_snapshot(self, snapshot_id: str | None = None) -> dict[str, Any]:
        if snapshot_id:
            row = self.storage.fetch_one(
                "SELECT * FROM f1_raw_factor_catalog_snapshots WHERE snapshot_id = ?",
                (snapshot_id,),
            )
            decoded = decode_f1_snapshot_row(row)
            if not decoded:
                raise KeyError(f"F1 catalog snapshot not found: {snapshot_id}")
            return decoded
        row = self._latest_f1_catalog_snapshot_row()
        decoded = decode_f1_snapshot_row(row)
        if decoded:
            return decoded
        run = self.create_pit_preprocessing_run({"mode": "MANUAL"})
        snapshot = run.get("f1_catalog_snapshot")
        if not isinstance(snapshot, Mapping):
            raise RuntimeError("F1 catalog snapshot could not be created")
        return dict(snapshot)

    def _ensure_operator_config_snapshot(
        self,
        snapshot_id: str | None = None,
        *,
        f1_catalog_snapshot_id: str | None = None,
    ) -> dict[str, Any]:
        if snapshot_id:
            row = self.storage.fetch_one(
                "SELECT * FROM operator_registry_snapshots WHERE snapshot_id = ?",
                (snapshot_id,),
            )
            decoded = self._decode_operator_config_snapshot_row(row)
            if not decoded:
                raise KeyError(f"Operator config snapshot not found: {snapshot_id}")
            return decoded
        row = self._latest_operator_config_snapshot_row()
        decoded = self._decode_operator_config_snapshot_row(row)
        if decoded:
            return decoded
        return self.create_factor_factory_operator_config_snapshot({
            **default_operator_config(),
            "f1_catalog_snapshot_id": f1_catalog_snapshot_id,
        })

    def _factor_factory_config_signature(
        self,
        request_payload: Mapping[str, Any],
        gate_policy: Mapping[str, Any],
        config_snapshot: Mapping[str, Any] | None = None,
    ) -> str:
        request_signature = "|".join(str(part) for part in self._factor_mining_request_signature(request_payload))
        policy_signature = dumps(dict(sorted(gate_policy.items())))
        snapshot_signature = dumps({
            "operator_config_snapshot_id": (config_snapshot or {}).get("operator_config_snapshot_id"),
            "f1_catalog_snapshot_id": (config_snapshot or {}).get("f1_catalog_snapshot_id"),
            "enabled_operators": (config_snapshot or {}).get("enabled_operators"),
            "window_space": (config_snapshot or {}).get("window_space"),
            "default_depth": (config_snapshot or {}).get("default_depth"),
            "daily_formula_budget": (config_snapshot or {}).get("daily_formula_budget"),
            "compute_backend": (config_snapshot or {}).get("compute_backend"),
            "blocked_field_policy": (config_snapshot or {}).get("blocked_field_policy"),
            "composition_methods": (config_snapshot or {}).get("composition_methods"),
        })
        return hashlib.sha1(f"{request_signature}|{policy_signature}|{snapshot_signature}".encode("utf-8")).hexdigest()[:16]

    def _factor_factory_next_run_at(self, schedule_time: str, *, run_date: str | None = None) -> str:
        day = run_date or self._factor_factory_today()
        return f"{day}T{schedule_time}:00+08:00"

    def _decode_factor_factory_profile_row(self, row: Mapping[str, Any] | None) -> dict[str, Any]:
        if not row:
            return {
                "id": "default",
                "status": "PAUSED",
                "timezone": "Asia/Hong_Kong",
                "schedule_time": "14:00",
                "request": self._factor_factory_default_request(),
                "gate_policy": self._factor_factory_default_gate_policy(),
                "created_at": None,
                "updated_at": None,
                "last_run_date": None,
                "next_run_at": self._factor_factory_next_run_at("14:00"),
            }
        schedule_time = str(row.get("schedule_time") or "14:00")
        if schedule_time == "23:30":
            schedule_time = "14:00"
        next_run_at = row.get("next_run_at")
        if not next_run_at or str(next_run_at).endswith("T23:30:00+08:00"):
            next_run_at = self._factor_factory_next_run_at(schedule_time)
        return {
            "id": row.get("id"),
            "status": row.get("status"),
            "timezone": row.get("timezone"),
            "schedule_time": schedule_time,
            "request": loads(row.get("request_json"), self._factor_factory_default_request()),
            "gate_policy": loads(row.get("gate_policy_json"), self._factor_factory_default_gate_policy()),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
            "last_run_date": row.get("last_run_date"),
            "next_run_at": next_run_at,
        }

    def _decode_factor_factory_run_row(
        self,
        row: Mapping[str, Any],
        *,
        mining_job: Mapping[str, Any] | None = None,
        mining_jobs_by_id: Mapping[str, Mapping[str, Any]] | None = None,
    ) -> dict[str, Any]:
        decoded_mining_job = None
        mining_job_id = str(row.get("mining_job_id") or "")
        if mining_job_id and mining_jobs_by_id and mining_job_id in mining_jobs_by_id:
            decoded_mining_job = mining_jobs_by_id[mining_job_id]
        elif mining_job is not None:
            decoded_mining_job = mining_job
        elif mining_job_id:
            try:
                decoded_mining_job = self.get_factor_mining_job(mining_job_id)
            except Exception:
                decoded_mining_job = None
        request_payload = loads(row.get("request_json"), {})
        return {
            "id": row.get("id"),
            "profile_id": row.get("profile_id"),
            "run_date": row.get("run_date"),
            "trigger": row.get("trigger"),
            "status": row.get("status"),
            "request": request_payload,
            "gate_policy": loads(row.get("gate_policy_json"), {}),
            "config_snapshot": request_payload.get("config_snapshot") if isinstance(request_payload, Mapping) else None,
            "config_signature": row.get("config_signature"),
            "mining_job_id": row.get("mining_job_id"),
            "mining_job": decoded_mining_job,
            "summary": loads(row.get("summary_json"), {}),
            "started_at": row.get("started_at"),
            "completed_at": row.get("completed_at"),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
            "error_message": row.get("error_message"),
        }

    @staticmethod
    def _factor_factory_resolve_artifact_ref(value: Any) -> tuple[Path | None, str | None]:
        ref = str(value or "").strip()
        if not ref:
            return None, None
        path = Path(ref)
        if not path.is_absolute():
            path = Path.cwd() / path
        return path, ref

    @classmethod
    def _factor_factory_artifact_payload(cls, value: Any) -> tuple[dict[str, Any], str | None, str | None]:
        path, ref = cls._factor_factory_resolve_artifact_ref(value)
        if path is None or not path.exists():
            return {}, None, ref
        data = path.read_bytes()
        digest = hashlib.sha256(data).hexdigest()
        try:
            payload = json.loads(data.decode("utf-8"))
        except Exception:
            payload = {}
        return payload if isinstance(payload, dict) else {}, digest, ref

    def _factor_factory_latest_run_row(self, run_id: str | None = None) -> Mapping[str, Any] | None:
        requested_run_id = str(run_id or "").strip()
        if requested_run_id:
            row = self.storage.fetch_one("SELECT * FROM factor_factory_runs WHERE id = ?", (requested_run_id,))
        else:
            row = self.storage.fetch_one(
                """
                SELECT *
                FROM factor_factory_runs
                ORDER BY created_at DESC, id DESC
                LIMIT 1
                """
            )
        if not row:
            return None
        if self._factor_factory_overview_should_refresh_run_row(row, is_latest=not requested_run_id):
            return self._refresh_factor_factory_run_row(row)
        return row

    def _factor_factory_batch_lineage(
        self,
        run: Mapping[str, Any] | None,
        *,
        publishable_factors: Sequence[Mapping[str, Any]] | None = None,
        source_reason: str = "latest_factor_factory_run",
    ) -> dict[str, Any]:
        if not isinstance(run, Mapping):
            return build_factor_factory_batch_lineage(
                current_batch_id=None,
                source_job_id=None,
                artifact_ref={},
                manifest_payload={},
                ledger_payload={},
                source_reason="factor_factory_run_not_found",
                db_path=str(getattr(self.storage, "path", "")),
            )
        current_batch_id = str(run.get("id") or "").strip()
        summary = run.get("summary") if isinstance(run.get("summary"), Mapping) else loads(run.get("summary_json"), {})
        if not isinstance(summary, Mapping):
            summary = {}
        operator_engine = summary.get("operator_engine") if isinstance(summary.get("operator_engine"), Mapping) else {}
        source_job_id = str(run.get("mining_job_id") or summary.get("mining_job_id") or "").strip()
        artifact_refs = operator_engine.get("artifact_refs") if isinstance(operator_engine.get("artifact_refs"), Mapping) else {}
        manifest_payload, manifest_hash, manifest_ref = self._factor_factory_artifact_payload(artifact_refs.get("formula_manifest"))
        ledger_payload, ledger_hash, ledger_ref = self._factor_factory_artifact_payload(artifact_refs.get("refined_f2_candidate_ledger"))
        quarantine_rows: Sequence[Mapping[str, Any]] = []
        if source_job_id:
            quarantine_rows = self.storage.fetch_all(
                """
                SELECT id, source_mining_job_id, status, publish_status, candidate_metrics_json
                FROM factor_quarantine_candidates
                WHERE source_mining_job_id = ?
                """,
                (source_job_id,),
            )
        if publishable_factors is not None:
            publishable_total = len(publishable_factors)
        elif source_job_id:
            auto_quarantine_status = str(summary.get("auto_quarantine_status") or "").upper()
            auto_quarantine_pending_count = int(_coerce_float(summary.get("auto_quarantine_pending_count"), 0.0))
            if auto_quarantine_status == "PARTIAL" and auto_quarantine_pending_count > 0:
                publishable_total = 0
            else:
                publishable_total = len(self._factor_factory_publishable_factors(
                    source_mining_job_id=source_job_id,
                    fallback_items=[],
                ))
        else:
            publishable_total = 0
        return build_factor_factory_batch_lineage(
            current_batch_id=current_batch_id,
            source_job_id=source_job_id,
            artifact_ref={
                "formula_manifest": manifest_ref or artifact_refs.get("formula_manifest"),
                "refined_f2_candidate_ledger": ledger_ref or artifact_refs.get("refined_f2_candidate_ledger"),
            },
            manifest_payload=manifest_payload,
            ledger_payload=ledger_payload,
            manifest_hash=manifest_hash,
            ledger_hash=ledger_hash,
            raw_f2_total=int(
                operator_engine.get("raw_f2_batch_delivered_count")
                or operator_engine.get("deduped_formula_count")
                or 0
            ),
            refined_f2_total=int(operator_engine.get("refined_f2_batch_delivered_count") or 0),
            preview_count=int(operator_engine.get("top_preview_count") or 0),
            quarantine_rows=quarantine_rows,
            publishable_total=publishable_total,
            source_reason=source_reason,
            db_path=str(getattr(self.storage, "path", "")),
        )

    def get_factor_factory_batch_lineage(self, run_id: str | None = None) -> dict[str, Any]:
        requested_run_id = str(run_id or "").strip()
        row = self._factor_factory_latest_run_row(requested_run_id or None)
        return self._factor_factory_batch_lineage(
            row,
            source_reason="explicit_run_id" if requested_run_id else "latest_factor_factory_run",
        )

    def _factor_factory_run_status_from_mining_job(self, mining_status: str) -> str:
        if mining_status in {"QUEUED", "RUNNING"}:
            return "RUNNING"
        if mining_status in {"CANCEL_REQUESTED", "CANCELLED"}:
            return "CANCELLED"
        if mining_status in {"COMPLETED", "PARTIALLY_FAILED"}:
            return "COMPLETED"
        return "FAILED"

    def _record_factor_factory_run_item(
        self,
        *,
        run_id: str,
        stage: str,
        source_id: str | None,
        target_id: str | None,
        status: str,
        summary: Mapping[str, Any] | None = None,
    ) -> None:
        now = iso_now()
        self.storage.insert_json_row(
            "factor_factory_run_items",
            {
                "id": f"ffi_{uuid4().hex[:12]}",
                "run_id": run_id,
                "stage": stage,
                "source_id": source_id,
                "target_id": target_id,
                "status": status,
                "summary_json": dumps(dict(summary or {})),
                "created_at": now,
                "updated_at": now,
            },
        )

    def _run_factor_factory_quarantine_pipeline(
        self,
        *,
        run_id: str,
        mining_job_id: str,
        summary: Mapping[str, Any],
    ) -> dict[str, Any]:
        current_summary = dict(summary)
        def quarantine_counts() -> dict[str, int]:
            row = self.storage.fetch_one(
                """
                SELECT
                    COUNT(*) AS total,
                    SUM(CASE WHEN status = 'PENDING' THEN 1 ELSE 0 END) AS pending,
                    SUM(CASE WHEN status = 'PASSED' THEN 1 ELSE 0 END) AS passed,
                    SUM(CASE WHEN status = 'NEEDS_REVIEW' THEN 1 ELSE 0 END) AS needs_review,
                    SUM(CASE WHEN status = 'REJECTED' THEN 1 ELSE 0 END) AS rejected,
                    SUM(CASE WHEN publish_status = 'ELIGIBLE' THEN 1 ELSE 0 END) AS eligible,
                    SUM(CASE WHEN status <> 'PENDING' THEN 1 ELSE 0 END) AS processed
                FROM factor_quarantine_candidates
                WHERE source_mining_job_id = ?
                """,
                (mining_job_id,),
            ) or {}
            return {
                "total": int(row.get("total") or 0),
                "pending": int(row.get("pending") or 0),
                "passed": int(row.get("passed") or 0),
                "needs_review": int(row.get("needs_review") or 0),
                "rejected": int(row.get("rejected") or 0),
                "eligible": int(row.get("eligible") or 0),
                "processed": int(row.get("processed") or 0),
            }

        def apply_quarantine_counts(counts: Mapping[str, int], *, status: str) -> None:
            current_summary.update({
                "auto_intake_count": int(counts.get("total") or 0),
                "auto_quarantine_count": int(counts.get("processed") or 0),
                "auto_quarantine_pending_count": int(counts.get("pending") or 0),
                "auto_quarantine_sync_limit": FACTOR_FACTORY_SYNC_QUARANTINE_LIMIT,
                "auto_quarantine_status": status,
                "quarantine_status_counts": {
                    "passed": int(counts.get("passed") or 0),
                    "needs_review": int(counts.get("needs_review") or 0),
                    "rejected": int(counts.get("rejected") or 0),
                    "pending": int(counts.get("pending") or 0),
                    "eligible": int(counts.get("eligible") or 0),
                },
            })

        auto_status = str(current_summary.get("auto_quarantine_status") or "").upper()
        if auto_status in {"COMPLETED", "PARTIAL", "DEFERRED"}:
            return current_summary
        if not mining_job_id:
            return current_summary
        if auto_status == "FAILED":
            existing_counts = quarantine_counts()
            if existing_counts["total"] > 0:
                apply_quarantine_counts(
                    existing_counts,
                    status="COMPLETED" if existing_counts["pending"] <= 0 else "PARTIAL",
                )
                if current_summary.get("auto_quarantine_error"):
                    current_summary["auto_quarantine_last_error"] = current_summary.get("auto_quarantine_error")
                    current_summary.pop("auto_quarantine_error", None)
                current_summary.setdefault("redundancy_pruning", {
                    "status": "DEFERRED",
                    "reason": "partial_quarantine_recovery",
                })
                return current_summary

        existing_counts = quarantine_counts()
        if existing_counts["total"] > FACTOR_FACTORY_SYNC_QUARANTINE_LIMIT:
            apply_quarantine_counts(
                existing_counts,
                status="COMPLETED" if existing_counts["pending"] <= 0 else "PARTIAL",
            )
            current_summary.setdefault("redundancy_pruning", {
                "status": "DEFERRED",
                "reason": "existing_quarantine_exceeds_sync_limit",
                "source_mining_job_id": mining_job_id,
                "pending_count": existing_counts["pending"],
                "sync_limit": FACTOR_FACTORY_SYNC_QUARANTINE_LIMIT,
            })
            return current_summary

        intake = self.factor_quarantine_intake({
            "mining_job_id": mining_job_id,
            "source": "factor_factory",
            "factory_run_id": run_id,
        })
        intake_items = intake.get("items") if isinstance(intake.get("items"), list) else []
        intake_summary = intake.get("summary") if isinstance(intake.get("summary"), Mapping) else {}
        counts_before = quarantine_counts()
        sync_limit = max(1, int(current_summary.get("auto_quarantine_sync_limit") or FACTOR_FACTORY_SYNC_QUARANTINE_LIMIT))
        remaining_sync_budget = max(0, sync_limit - counts_before["processed"])
        self._record_factor_factory_run_item(
            run_id=run_id,
            stage="QUARANTINE_INTAKE",
            source_id=mining_job_id,
            target_id=None,
            status="COMPLETED",
            summary={
                "intake_count": len(intake_items),
                "skipped_raw_f2_needs_refinement_count": int(
                    _coerce_float(intake_summary.get("skipped_raw_f2_needs_refinement_count"), 0.0)
                ),
                "source_mining_job_id": mining_job_id,
            },
        )
        quarantine_results: list[dict[str, Any]] = []
        for item in intake_items:
            if remaining_sync_budget <= 0:
                break
            if not isinstance(item, Mapping):
                continue
            candidate_id = str(item.get("id") or "").strip()
            if not candidate_id:
                continue
            item_status = str(item.get("status") or "").upper()
            if item_status in {"PUBLISHED", "PASSED", "REJECTED"}:
                continue
            result = self.run_factor_quarantine_candidate(candidate_id, {
                "reason": "factor_factory_auto_quarantine",
                "factory_run_id": run_id,
                "source_mining_job_id": mining_job_id,
            })
            self.storage.execute(
                """
                UPDATE factor_quarantine_candidates
                SET source_mining_job_id = ?, updated_at = ?
                WHERE id = ?
                """,
                (mining_job_id, iso_now(), candidate_id),
            )
            quarantine_results.append(result)
            remaining_sync_budget -= 1
            self._record_factor_factory_run_item(
                run_id=run_id,
                stage="QUARANTINE_RUN",
                source_id=mining_job_id,
                target_id=candidate_id,
                status=str(result.get("status") or "COMPLETED"),
                summary={
                    "publish_status": result.get("publish_status"),
                    "review_reason": result.get("rejected_reason"),
                    "gate_summary": result.get("gate_summary"),
                },
            )
        counts_after = quarantine_counts()
        redundancy_pruning = self._apply_factor_factory_redundancy_pruning(
            source_mining_job_id=mining_job_id,
        )
        auto_quarantine_status = "COMPLETED" if counts_after["pending"] <= 0 else "PARTIAL"
        apply_quarantine_counts(counts_after, status=auto_quarantine_status)
        current_summary.update({
            "auto_intake_count": counts_after["total"] or len(intake_items),
            "auto_intake_skipped_raw_f2_needs_refinement_count": int(
                _coerce_float(intake_summary.get("skipped_raw_f2_needs_refinement_count"), 0.0)
            ),
            "auto_quarantine_sync_limit": sync_limit,
            "redundancy_pruning": redundancy_pruning,
            "quarantine_candidate_ids": [
                str(item.get("id"))
                for item in quarantine_results
                if isinstance(item, Mapping) and item.get("id")
            ],
            "funnel": self._factor_factory_funnel(),
        })
        return current_summary

    @staticmethod
    def _factor_factory_overview_should_refresh_run_row(row: Mapping[str, Any], *, is_latest: bool) -> bool:
        if is_latest:
            return True
        status = str(row.get("status") or "").upper()
        if status in {"QUEUED", "RUNNING", "CANCEL_REQUESTED"}:
            return True
        summary = loads(row.get("summary_json"), {})
        if not isinstance(summary, Mapping):
            return True
        if not summary.get("mining_status"):
            return True
        if "top_candidate_count" not in summary or "failed_sample_count" not in summary:
            return True
        if status == "COMPLETED":
            auto_status = str(summary.get("auto_quarantine_status") or "").upper()
            return auto_status not in {"COMPLETED", "PARTIAL", "DEFERRED", "FAILED"}
        return False

    def _refresh_factor_factory_run_row(
        self,
        row: Mapping[str, Any],
        *,
        mining_job: Mapping[str, Any] | None = None,
        funnel_snapshot: Mapping[str, int] | None = None,
    ) -> Mapping[str, Any]:
        mining_job_id = str(row.get("mining_job_id") or "")
        if not mining_job_id:
            return row
        if mining_job is None:
            try:
                mining_job = self.get_factor_mining_job(mining_job_id)
            except Exception:
                return row
        next_status = self._factor_factory_run_status_from_mining_job(str(mining_job.get("status") or ""))
        completed_at = row.get("completed_at")
        if next_status in {"COMPLETED", "FAILED", "CANCELLED"}:
            completed_at = completed_at or mining_job.get("completed_at") or iso_now()
        summary = loads(row.get("summary_json"), {})
        if not isinstance(summary, Mapping):
            summary = {}
        funnel = dict(funnel_snapshot) if isinstance(funnel_snapshot, Mapping) else self._factor_factory_funnel()
        updated_summary = {
            **dict(summary),
            "mining_status": mining_job.get("status"),
            "top_candidate_count": len(mining_job.get("top_candidates") or []),
            "failed_sample_count": len(mining_job.get("failed_samples") or []),
            "funnel": funnel,
        }
        mining_summary = mining_job.get("summary") if isinstance(mining_job.get("summary"), Mapping) else {}
        if mining_summary:
            updated_summary.update({
                "generation_mode": mining_summary.get("generation_mode"),
                "composition_candidate_count": mining_summary.get("composition_candidate_count", 0),
                "composition_policy": mining_summary.get("composition_policy", {}),
                "operator_engine": mining_summary.get("operator_engine", updated_summary.get("operator_engine", {})),
            })
        auto_quarantine_status = str(summary.get("auto_quarantine_status") or "").upper()
        if next_status == "COMPLETED" and auto_quarantine_status not in {"COMPLETED", "PARTIAL", "FAILED"}:
            try:
                updated_summary = self._run_factor_factory_quarantine_pipeline(
                    run_id=str(row.get("id") or ""),
                    mining_job_id=mining_job_id,
                    summary=updated_summary,
                )
            except Exception as exc:
                next_status = "FAILED"
                completed_at = completed_at or iso_now()
                updated_summary = {
                    **updated_summary,
                    "auto_quarantine_status": "FAILED",
                    "auto_quarantine_error": str(exc),
                }
        if next_status != row.get("status") or updated_summary != summary:
            self.storage.execute(
                """
                UPDATE factor_factory_runs
                SET status = ?, summary_json = ?, completed_at = ?, updated_at = ?
                WHERE id = ?
                """,
                (next_status, dumps(updated_summary), completed_at, iso_now(), row.get("id")),
            )
            refreshed = self.storage.fetch_one("SELECT * FROM factor_factory_runs WHERE id = ?", (row.get("id"),))
            return refreshed or row
        return row

    def _factor_factory_funnel(self, *, mining_jobs: Mapping[str, Any] | None = None) -> dict[str, int]:
        if mining_jobs is None:
            mining_jobs = self.list_factor_mining_jobs()
        mining_items = mining_jobs.get("items") if isinstance(mining_jobs.get("items"), list) else []
        mined = 0
        for item in mining_items:
            if not isinstance(item, Mapping):
                continue
            summary = item.get("summary") if isinstance(item.get("summary"), Mapping) else {}
            operator_engine = summary.get("operator_engine") if isinstance(summary.get("operator_engine"), Mapping) else {}
            mined += int(
                operator_engine.get("raw_f2_batch_delivered_count")
                or operator_engine.get("deduped_formula_count")
                or len(item.get("top_candidates") or [])
            )
        quarantine_counts = self.storage.fetch_one(
            """
            SELECT
                COUNT(*) AS total,
                SUM(CASE WHEN status = 'PASSED' THEN 1 ELSE 0 END) AS passed,
                SUM(CASE WHEN status = 'PUBLISHED' THEN 1 ELSE 0 END) AS published,
                SUM(CASE WHEN status = 'REJECTED' THEN 1 ELSE 0 END) AS rejected,
                SUM(CASE WHEN status NOT IN ('PASSED', 'PUBLISHED', 'REJECTED') THEN 1 ELSE 0 END) AS review_or_observation
            FROM factor_quarantine_candidates
            """
        ) or {}
        return {
            "mined_candidates": mined,
            "quarantine_candidates": int(quarantine_counts.get("total") or 0),
            "passed": int(quarantine_counts.get("passed") or 0),
            "review_or_observation": int(quarantine_counts.get("review_or_observation") or 0),
            "rejected": int(quarantine_counts.get("rejected") or 0),
            "published": int(quarantine_counts.get("published") or 0),
        }

    @staticmethod
    def _factor_factory_operator_status_key(factor_service: Any, factor: Mapping[str, Any]) -> str:
        if not factor or not hasattr(factor_service, "_factor_operator_status_light_key"):
            return ""
        try:
            return str(factor_service._factor_operator_status_light_key(factor) or "")  # noqa: SLF001
        except Exception:
            return ""

    @staticmethod
    def _factor_factory_redundancy_keys(
        *,
        factor_id: Any,
        name_collision_key: Any,
        base_display_name_cn: Any,
        expression: Any,
        op_status_key: Any = None,
    ) -> set[str]:
        keys: set[str] = set()
        op_prefix = f"op:{str(op_status_key).strip().upper()}|" if str(op_status_key or "").strip() else ""
        factor_key = re.sub(r"\s+", "", str(factor_id or "").strip().lower())
        if factor_key:
            keys.add(f"{op_prefix}factor:{factor_key}")
        name_key = str(name_collision_key or base_display_name_cn or "").strip().lower()
        name_key = re.sub(r"\s+", "", name_key)
        if name_key:
            keys.add(f"{op_prefix}name:{name_key}")
        expression_key = re.sub(r"\s+", "", str(expression or "").strip().lower())
        if not keys and expression_key:
            keys.add(f"{op_prefix}expr:{expression_key}")
        return keys

    @staticmethod
    def _factor_factory_redundancy_semantic_key(value: Any) -> str:
        text_value = str(value or "").strip()
        if not text_value:
            return ""
        text_value = text_value.replace("（", "(").replace("）", ")")
        text_value = re.sub(r"^\[[^\]]+\]\s*-\s*", "", text_value)
        text_value = re.sub(r"\[[^\]]+\]\s*$", "", text_value)
        text_value = re.sub(r"\s+", "", text_value).lower()
        return f"semantic:{text_value}" if text_value else ""

    @classmethod
    def _factor_factory_redundancy_semantic_keys(cls, *values: Any) -> set[str]:
        keys = {cls._factor_factory_redundancy_semantic_key(value) for value in values}
        return {key for key in keys if key}

    @classmethod
    def _factor_factory_publishable_block_keys(
        cls,
        *,
        factor_id: Any = None,
        name_collision_key: Any = None,
        base_display_name_cn: Any = None,
        display_name_cn: Any = None,
        factor_name: Any = None,
        op_status_key: Any = None,
    ) -> set[str]:
        keys: set[str] = set()
        op_prefix = f"op:{str(op_status_key).strip().upper()}|" if str(op_status_key or "").strip() else ""
        factor_key = re.sub(r"\s+", "", str(factor_id or "").strip().lower())
        if factor_key:
            keys.add(f"{op_prefix}factor:{factor_key}")
        semantic_keys = cls._factor_factory_redundancy_semantic_keys(
            name_collision_key,
            base_display_name_cn,
            display_name_cn,
            factor_name,
        )
        keys.update(f"{op_prefix}{key}" for key in semantic_keys)
        return keys

    @staticmethod
    def _factor_factory_correlation_projection(
        factor_service: Any,
        *,
        factor_id: str,
        expression: str,
        display_name: Any,
        target_layer: str,
    ) -> Mapping[str, Any] | None:
        if not factor_id or not expression or not hasattr(factor_service, "_factor_correlation_projection"):
            return None
        try:
            return factor_service._factor_correlation_projection(  # noqa: SLF001
                {
                    "id": factor_id,
                    "name": display_name or factor_id,
                    "source": "AUTO_MINED",
                    "expression": expression,
                    "tags_json": dumps(["auto_mined", str(target_layer or "").lower()]),
                    "data_requirements_json": dumps([]),
                }
            )
        except Exception:
            return None

    def _factor_factory_library_publish_blockers(self) -> dict[str, dict[str, Any]]:
        blockers: dict[str, dict[str, Any]] = {}

        def add_blockers(keys: set[str], *, reason: str, source: Mapping[str, Any]) -> None:
            for key in keys:
                blockers.setdefault(key, {"reason": reason, "source": dict(source)})

        factor_service = self._factor_research_service()
        published_factor_ids = {
            str(row.get("factor_id") or "").strip()
            for row in self.storage.fetch_all(
                """
                SELECT DISTINCT factor_id
                FROM factor_publish_events
                WHERE COALESCE(factor_id, '') <> ''
                  AND UPPER(COALESCE(event_type, '')) LIKE '%PUBLISH%'
                """
            )
            if str(row.get("factor_id") or "").strip()
        }
        try:
            online_factors = factor_service.list_factors(
                lifecycle="online",
                include_governance_queue=False,
            ).get("items", [])
        except Exception:
            online_factors = []
        seen_factor_ids: set[str] = set()
        for factor in online_factors:
            factor_id = str(factor.get("id") or "").strip()
            if not factor_id:
                continue
            seen_factor_ids.add(factor_id)
            op_status_key = self._factor_factory_operator_status_key(factor_service, factor)
            add_blockers(
                self._factor_factory_publishable_block_keys(
                    factor_id=factor_id,
                    name_collision_key=factor.get("name_collision_key"),
                    base_display_name_cn=factor.get("base_display_name_cn"),
                    display_name_cn=factor.get("display_name_cn"),
                    factor_name=factor.get("name"),
                    op_status_key=op_status_key,
                ),
                reason="ONLINE_PUBLISHED_FACTOR" if factor_id in published_factor_ids else "ONLINE_FACTOR_DEFINITION",
                source={"factor_id": factor_id, "op_status_key": op_status_key},
            )
        direct_online_rows = self.storage.fetch_all(
            """
            SELECT id, name, source, expression, lifecycle_status
            FROM factor_definitions
            WHERE deleted_at IS NULL
              AND UPPER(COALESCE(lifecycle_status, '')) IN ('VERIFIED', 'ACTIVE', 'APPROVED', 'PUBLISHED')
            """
        )
        for row in direct_online_rows:
            factor_id = str(row.get("id") or "").strip()
            if not factor_id or factor_id in seen_factor_ids:
                continue
            expression = str(row.get("expression") or "").strip()
            source = str(row.get("source") or "").strip() or "AUTO_MINED"
            target_layer = "F2" if "_f2_" in factor_id.lower() or "F2" in source.upper() else "F3"
            projection: Mapping[str, Any] = {}
            if expression:
                try:
                    projection = factor_display_name_projection_v4(
                        factor_id=factor_id,
                        source=source,
                        expression=expression,
                        tier_level=target_layer,
                    )
                except Exception:
                    projection = {}
            op_status_key = self._factor_factory_operator_status_key(factor_service, row)
            add_blockers(
                self._factor_factory_publishable_block_keys(
                    factor_id=factor_id,
                    name_collision_key=projection.get("name_collision_key"),
                    base_display_name_cn=projection.get("base_display_name_cn") or row.get("name"),
                    display_name_cn=projection.get("display_name_cn") or row.get("name"),
                    factor_name=row.get("name"),
                    op_status_key=op_status_key,
                ),
                reason="ONLINE_PUBLISHED_FACTOR" if factor_id in published_factor_ids else "ONLINE_FACTOR_DEFINITION",
                source={"factor_id": factor_id, "op_status_key": op_status_key},
            )

        try:
            governance_overview = factor_service.get_factor_governance_overview()
        except Exception:
            governance_overview = {}
        for action in governance_overview.get("actions") or []:
            if not isinstance(action, Mapping):
                continue
            command = str(action.get("command") or action.get("kind") or "").upper()
            if command != "PRUNE":
                continue
            criteria = action.get("criteria") if isinstance(action.get("criteria"), Mapping) else {}
            offline_detail = action.get("offline_detail") if isinstance(action.get("offline_detail"), Mapping) else {}
            correlation = abs(_coerce_float(criteria.get("correlation"), _coerce_float(offline_detail.get("correlation"), 0.0)))
            threshold = _coerce_float(criteria.get("threshold"), FACTOR_PRUNE_CORRELATION_THRESHOLD)
            evidence_source = str(criteria.get("evidence_source") or offline_detail.get("evidence_source") or "").upper()
            if correlation <= threshold or evidence_source not in FACTOR_FACTORY_PRUNE_EVIDENCE_SOURCES:
                continue
            operator_status_light = (
                criteria.get("operator_status_light")
                if isinstance(criteria.get("operator_status_light"), Mapping)
                else offline_detail.get("operator_status_light")
                if isinstance(offline_detail.get("operator_status_light"), Mapping)
                else {}
            )
            if isinstance(operator_status_light, Mapping) and operator_status_light.get("same") is False:
                continue
            reason_prefix = "MEASURED_PRUNE"
            comparison = offline_detail.get("comparison") if isinstance(offline_detail.get("comparison"), Mapping) else {}
            candidate = comparison.get("candidate") if isinstance(comparison.get("candidate"), Mapping) else {}
            mvp = comparison.get("mvp") if isinstance(comparison.get("mvp"), Mapping) else {}
            candidate_status = operator_status_light.get("candidate") if isinstance(operator_status_light.get("candidate"), Mapping) else {}
            mvp_status = operator_status_light.get("mvp") if isinstance(operator_status_light.get("mvp"), Mapping) else {}
            candidate_op_status_key = str(candidate_status.get("key") or "").strip()
            mvp_op_status_key = str(mvp_status.get("key") or candidate_op_status_key or "").strip()
            action_factor_ids = [str(item).strip() for item in action.get("factor_ids") or [] if str(item).strip()]
            action_factor_ids.extend(
                str(value).strip()
                for value in (offline_detail.get("factor_id"), candidate.get("factor_id"))
                if str(value or "").strip()
            )
            for factor_id in dict.fromkeys(action_factor_ids):
                add_blockers(
                    self._factor_factory_publishable_block_keys(
                        factor_id=factor_id,
                        op_status_key=candidate_op_status_key,
                    ),
                    reason=f"{reason_prefix}_FACTOR",
                    source={"action_id": action.get("id"), "factor_id": factor_id, "correlation": correlation, "op_status_key": candidate_op_status_key},
                )
            add_blockers(
                self._factor_factory_publishable_block_keys(
                    factor_id=candidate.get("factor_id"),
                    name_collision_key=candidate.get("name_collision_key"),
                    base_display_name_cn=candidate.get("base_display_name_cn"),
                    display_name_cn=candidate.get("display_name_cn"),
                    factor_name=candidate.get("factor_name") or candidate.get("name"),
                    op_status_key=candidate_op_status_key,
                ),
                reason=f"{reason_prefix}_SEMANTIC",
                source={"action_id": action.get("id"), "correlation": correlation, "threshold": threshold, "op_status_key": candidate_op_status_key},
            )
            add_blockers(
                self._factor_factory_publishable_block_keys(
                    factor_id=mvp.get("factor_id"),
                    name_collision_key=mvp.get("name_collision_key"),
                    base_display_name_cn=mvp.get("base_display_name_cn"),
                    display_name_cn=mvp.get("display_name_cn"),
                    factor_name=mvp.get("factor_name") or mvp.get("name"),
                    op_status_key=mvp_op_status_key,
                ),
                reason=f"{reason_prefix}_MVP",
                source={"action_id": action.get("id"), "correlation": correlation, "threshold": threshold, "op_status_key": mvp_op_status_key},
            )
        return blockers

    def _append_factor_factory_redundancy_group(
        self,
        groups: list[dict[str, Any]],
        *,
        keys: set[str],
        item: Any,
        correlation_projection: Mapping[str, Any] | None = None,
    ) -> None:
        matches = [
            index
            for index, group in enumerate(groups)
            if keys.intersection(group.get("keys") or set())
        ]
        if not keys and not matches:
            groups.append(
                {
                    "keys": set(),
                    "items": [item],
                    "correlation_projections": [dict(correlation_projection)] if correlation_projection else [],
                }
            )
            return
        if not matches:
            groups.append(
                {
                    "keys": set(keys),
                    "items": [item],
                    "correlation_projections": [dict(correlation_projection)] if correlation_projection else [],
                }
            )
            return
        primary = groups[matches[0]]
        primary.setdefault("keys", set()).update(keys)
        primary.setdefault("items", []).append(item)
        if correlation_projection:
            primary.setdefault("correlation_projections", []).append(dict(correlation_projection))
        for index in reversed(matches[1:]):
            primary["keys"].update(groups[index].get("keys") or set())
            primary["items"].extend(groups[index].get("items") or [])
            primary.setdefault("correlation_projections", []).extend(groups[index].get("correlation_projections") or [])
            del groups[index]

    def _apply_factor_factory_redundancy_pruning(self, *, source_mining_job_id: str) -> dict[str, Any]:
        source_mining_job_id = str(source_mining_job_id or "").strip()
        if not source_mining_job_id:
            return {"status": "SKIPPED", "kept": 0, "pruned": 0, "groups": 0}
        rows = self.storage.fetch_all(
            """
            SELECT id, target_factor_id, expression, candidate_metrics_json, gate_summary_json
            FROM factor_quarantine_candidates
            WHERE source_mining_job_id = ?
              AND status = 'PASSED'
              AND publish_status = 'ELIGIBLE'
            """,
            (source_mining_job_id,),
        )
        factor_service = self._factor_research_service()
        library_blockers = self._factor_factory_library_publish_blockers()
        groups: list[dict[str, Any]] = []
        library_pruned = 0
        for row in rows:
            metrics = loads(row.get("candidate_metrics_json"), {})
            if not isinstance(metrics, Mapping):
                metrics = {}
            if str(metrics.get("pipeline_version") or "") != "raw_refined_f2_v2":
                continue
            if bool(metrics.get("raw_f2")) and not (bool(metrics.get("refined_f2")) and bool(metrics.get("wnzt_complete"))):
                continue
            expression = str(row.get("expression") or "").strip()
            target_layer = str(metrics.get("target_layer") or "L2").upper()
            target_factor_id = _published_factor_identity(
                expression,
                target_layer=target_layer,
                metrics=metrics,
            ).factor_id
            projection = factor_display_name_projection_v4(
                factor_id=target_factor_id or str(row.get("id") or ""),
                source="AUTO_MINED",
                expression=expression,
                tier_level=target_layer.replace("L", "F"),
                neutralization_scope=metrics.get("neutralization_scope") or metrics.get("orthogonality_intent"),
                residual_control=metrics.get("residual_control") or ("market_beta" if "beta" in expression.lower() else None),
            )
            op_status_key = self._factor_factory_operator_status_key(
                factor_service,
                {
                    "id": target_factor_id,
                    "source": "AUTO_MINED",
                    "expression": expression,
                    "latest_diagnostic_summary": {
                        "wnzt_complete": metrics.get("wnzt_complete"),
                        "wnzt_evidence": metrics.get("wnzt_evidence"),
                        "operator_chain": metrics.get("operator_chain"),
                    },
                },
            )
            block_keys = self._factor_factory_publishable_block_keys(
                factor_id=target_factor_id,
                name_collision_key=projection.get("name_collision_key"),
                base_display_name_cn=projection.get("base_display_name_cn"),
                display_name_cn=projection.get("display_name_cn"),
                factor_name=projection.get("display_name_cn") or projection.get("base_display_name_cn"),
                op_status_key=op_status_key,
            )
            blocked_by = next(
                (
                    library_blockers[key]
                    for key in sorted(block_keys.intersection(library_blockers))
                    if isinstance(library_blockers.get(key), Mapping)
                ),
                None,
            )
            if blocked_by:
                gate_summary = loads(row.get("gate_summary_json"), {})
                if not isinstance(gate_summary, Mapping):
                    gate_summary = {}
                blocker_source = blocked_by.get("source") if isinstance(blocked_by.get("source"), Mapping) else {}
                blocker_reason = str(blocked_by.get("reason") or "MEASURED_PRUNE_SEMANTIC")
                metrics.update({
                    "redundancy_pruned": True,
                    "redundancy_pruning_source": blocker_reason,
                    "redundancy_group_key": "|".join(sorted(block_keys.intersection(library_blockers))),
                    "redundancy_blocker": dict(blocker_source),
                })
                next_gate = {
                    **dict(gate_summary),
                    "redundancy_pruning": "FAILED",
                    "redundancy_pruning_source": blocker_reason,
                    "redundancy_blocker": dict(blocker_source),
                }
                self.storage.execute(
                    """
                    UPDATE factor_quarantine_candidates
                    SET status = 'REJECTED',
                        publish_status = 'BLOCKED',
                        candidate_metrics_json = ?,
                        gate_summary_json = ?,
                        publish_eligibility_json = ?,
                        updated_at = ?,
                        rejected_reason = ?
                    WHERE id = ?
                    """,
                    (
                        dumps(metrics),
                        dumps(next_gate),
                        dumps({
                            "status": "BLOCKED",
                            "reason": "冗余裁剪：与线上因子库或实测 PRUNE 证据重复，禁止再次发布。",
                            "rule_version": "factor_quarantine_v2_0",
                            "source": blocker_reason,
                        }),
                        iso_now(),
                        "冗余裁剪：与线上因子库或实测 PRUNE 证据重复，禁止再次发布。",
                        row.get("id"),
                    ),
                )
                library_pruned += 1
                continue
            keys = self._factor_factory_redundancy_keys(
                factor_id=target_factor_id,
                name_collision_key=projection.get("name_collision_key"),
                base_display_name_cn=projection.get("base_display_name_cn"),
                expression=expression,
                op_status_key=op_status_key,
            )
            correlation_projection = self._factor_factory_correlation_projection(
                factor_service,
                factor_id=target_factor_id,
                expression=expression,
                display_name=projection.get("display_name_cn") or projection.get("base_display_name_cn"),
                target_layer=target_layer,
            )
            score = _coerce_float(
                metrics.get("fitness_score") if metrics.get("fitness_score") is not None else metrics.get("score"),
                0.0,
            )
            self._append_factor_factory_redundancy_group(
                groups,
                keys=keys,
                item=(row, dict(metrics), score),
                correlation_projection=correlation_projection,
            )
        kept = 0
        pruned = 0
        reason = "冗余裁剪：同一发布因子仅保留当前批次最高分候选。"
        now = iso_now()
        for group in groups:
            items = group.get("items") or []
            if not items:
                continue
            group_key = "|".join(sorted(group.get("keys") or set()))
            items.sort(key=lambda item: (item[2], str(item[0].get("id") or "")), reverse=True)
            winner_id = str(items[0][0].get("id") or "")
            kept += 1
            for row, metrics, _score in items[1:]:
                gate_summary = loads(row.get("gate_summary_json"), {})
                if not isinstance(gate_summary, Mapping):
                    gate_summary = {}
                metrics.update({
                    "redundancy_pruned": True,
                    "redundancy_group_key": group_key,
                    "redundancy_kept_candidate_id": winner_id,
                })
                next_gate = {
                    **dict(gate_summary),
                    "redundancy_pruning": "FAILED",
                    "redundancy_kept_candidate_id": winner_id,
                }
                self.storage.execute(
                    """
                    UPDATE factor_quarantine_candidates
                    SET status = 'REJECTED',
                        publish_status = 'BLOCKED',
                        candidate_metrics_json = ?,
                        gate_summary_json = ?,
                        publish_eligibility_json = ?,
                        updated_at = ?,
                        rejected_reason = ?
                    WHERE id = ?
                    """,
                    (
                        dumps(metrics),
                        dumps(next_gate),
                        dumps({"status": "BLOCKED", "reason": reason, "rule_version": "factor_quarantine_v2_0"}),
                        now,
                        reason,
                        row.get("id"),
                    ),
                )
                pruned += 1
        return {
            "status": "COMPLETED",
            "kept": kept,
            "pruned": pruned,
            "library_pruned": library_pruned,
            "groups": len(groups),
        }

    @staticmethod
    def _factor_factory_task_status(run: Mapping[str, Any] | None) -> str:
        status = str((run or {}).get("status") or "").upper()
        if status in {"QUEUED", "PENDING"}:
            return "待开始"
        if status in {"RUNNING", "CANCEL_REQUESTED"}:
            return "运行中"
        return "已完成" if status else "待开始"
        if status in {"QUEUED", "PENDING"}:
            return "待开始"
        if status in {"RUNNING", "CANCEL_REQUESTED"}:
            return "进行中"
        return "已完成" if status else "待开始"

    @staticmethod
    def _factor_factory_quarantine_result(candidate: Mapping[str, Any]) -> str:
        result = str(candidate.get("quarantine_result") or "").upper()
        if result in {"PASS", "WARN", "FAIL"}:
            return result
        status = str(candidate.get("status") or "").upper()
        if status in {"PASSED", "PUBLISHED"}:
            return "PASS"
        if status == "REJECTED":
            return "FAIL"
        return "WARN"

    @staticmethod
    def _factor_factory_candidate_event_time(candidate: Mapping[str, Any]) -> Any:
        latest_run = candidate.get("latest_run") if isinstance(candidate.get("latest_run"), Mapping) else {}
        return (
            latest_run.get("completed_at")
            or latest_run.get("created_at")
            or candidate.get("last_quarantine_at")
            or candidate.get("updated_at")
            or candidate.get("created_at")
        )

    @staticmethod
    def _factor_factory_text_is_unreadable(value: Any) -> bool:
        text_value = str(value or "").strip()
        if not text_value:
            return True
        if set(text_value) <= {"?"}:
            return True
        question_count = text_value.count("?")
        surrogate_count = sum(1 for char in text_value if 0xDC80 <= ord(char) <= 0xDCFF)
        return question_count >= 3 or surrogate_count >= max(2, len(text_value) // 8)

    def _factor_factory_quarantine_reason_summary(self, item: Mapping[str, Any]) -> str:
        publish_eligibility = item.get("publish_eligibility") if isinstance(item.get("publish_eligibility"), Mapping) else {}
        latest_run = item.get("latest_run") if isinstance(item.get("latest_run"), Mapping) else {}
        latest_summary = latest_run.get("summary") if isinstance(latest_run.get("summary"), Mapping) else {}
        result = self._factor_factory_quarantine_result(item)
        candidates = [
            item.get("reason_summary"),
            item.get("rejected_reason"),
            publish_eligibility.get("reason"),
            latest_summary.get("publish_reason"),
        ]
        for candidate in candidates:
            if not self._factor_factory_text_is_unreadable(candidate):
                reason = str(candidate).strip()
                if result != "PASS" and ("检疫通过" in reason or "可上线发布" in reason or "允许" in reason):
                    continue
                return reason
        publish_status = str(item.get("publish_status") or publish_eligibility.get("status") or "").upper()
        if result == "PASS" and publish_status == "ELIGIBLE":
            return "D2 检疫通过，已进入可上线发布队列。"
        if result == "PASS":
            return "D2 检疫通过，等待发布状态复核。"
        if result == "FAIL":
            return "未通过检疫硬闸门，需在详情中复核 OOS、P-value、拥挤度、回撤或容量。"
        return "检疫观察中，需人工复核后再发布。"

    def _factor_factory_quarantine_signatures_for_job(self, source_job_id: str) -> set[str]:
        source_job_id = str(source_job_id or "").strip()
        if not source_job_id:
            return set()
        factor_service = self._factor_research_service()
        rows = self.storage.fetch_all(
            """
            SELECT expression
            FROM factor_quarantine_candidates
            WHERE source_mining_job_id = ?
            """,
            (source_job_id,),
        )
        return {
            factor_service._expression_signature(str(row.get("expression") or ""))
            for row in rows
            if str(row.get("expression") or "").strip()
        }

    def _factor_factory_publishable_factors(
        self,
        *,
        source_mining_job_id: str,
        fallback_items: Sequence[Mapping[str, Any]],
        defer_non_external: bool = False,
        include_external_imports: bool = False,
    ) -> list[dict[str, Any]]:
        rows: list[Mapping[str, Any]] = []
        source_mining_job_id = str(source_mining_job_id or "").strip()
        factor_service = self._factor_research_service()
        library_blockers: dict[str, dict[str, Any]] | None = None
        if source_mining_job_id:
            rows = self.storage.fetch_all(
                """
                SELECT *
                FROM factor_quarantine_candidates
                WHERE source_mining_job_id = ?
                  AND status = 'PASSED'
                  AND publish_status = 'ELIGIBLE'
                """,
                (source_mining_job_id,),
            )
            if include_external_imports:
                external_rows = self.storage.fetch_all(
                    """
                    SELECT *
                    FROM factor_quarantine_candidates
                    WHERE source_mining_job_id GLOB 'extimp_*'
                      AND status = 'PASSED'
                      AND publish_status = 'ELIGIBLE'
                    """,
                )
                seen_row_ids = {str(row.get("id") or "") for row in rows}
                rows.extend(
                    row
                    for row in external_rows
                    if str(row.get("id") or "") and str(row.get("id") or "") not in seen_row_ids
                )
        else:
            rows = list(fallback_items)
        existing_factor_ids: set[str] = set()
        groups: list[dict[str, Any]] = []
        for row in rows:
            if source_mining_job_id:
                candidate = factor_service._decode_quarantine_candidate_row(row)
            else:
                candidate = dict(row)
                if not isinstance(candidate.get("candidate_metrics"), Mapping):
                    candidate["candidate_metrics"] = loads(candidate.get("candidate_metrics_json"), {})
                if not isinstance(candidate.get("gate_summary"), Mapping):
                    candidate["gate_summary"] = loads(candidate.get("gate_summary_json"), {})
                if not isinstance(candidate.get("pit_evidence"), Mapping):
                    candidate["pit_evidence"] = loads(candidate.get("pit_evidence_json"), {})
                if not isinstance(candidate.get("publish_eligibility"), Mapping):
                    candidate["publish_eligibility"] = loads(candidate.get("publish_eligibility_json"), {})
                candidate = factor_service._hydrate_factor_phase2_candidate(candidate)
            metrics = (
                candidate.get("candidate_metrics")
                if isinstance(candidate.get("candidate_metrics"), Mapping)
                else {}
            )
            if not isinstance(metrics, Mapping):
                metrics = {}
            pipeline_version = str(metrics.get("pipeline_version") or "")
            is_external_import = (
                pipeline_version == "external_factor_import_v1"
                or str(metrics.get("source") or "").upper() == "PUBLIC_FACTOR_IMPORT"
                or str(candidate.get("source_mining_job_id") or "").startswith("extimp_")
            )
            if is_external_import:
                manifest = metrics.get("manifest") if isinstance(metrics.get("manifest"), Mapping) else {}
                diagnostics = (
                    metrics.get("external_diagnostics")
                    if isinstance(metrics.get("external_diagnostics"), Mapping)
                    else {}
                )
                source_ready = (
                    int(_coerce_float(manifest.get("row_count"), 0.0)) > 0
                    and int(_coerce_float(diagnostics.get("date_count"), 0.0)) > 0
                    and int(_coerce_float(diagnostics.get("factor_count"), 0.0)) > 0
                )
                if not source_ready:
                    continue
                publish_eligibility = dict(candidate.get("publish_eligibility") or {})
                publish_eligibility.update({
                    "status": "ELIGIBLE",
                    "reason": (
                        str(candidate.get("reason_summary") or "").strip()
                        or "外部公开因子源文件已物化并完成 B3 源数据检疫；已进入可上线发布候选。"
                    ),
                    "rule_version": FACTOR_QUARANTINE_RULE_VERSION,
                })
                candidate["publish_status"] = "ELIGIBLE"
                candidate["publish_eligibility"] = publish_eligibility
            elif pipeline_version != "raw_refined_f2_v2":
                continue
            if defer_non_external and not is_external_import:
                continue
            if (
                not is_external_import
                and bool(metrics.get("raw_f2"))
                and not (bool(metrics.get("refined_f2")) and bool(metrics.get("wnzt_complete")))
            ):
                continue
            expression = str(candidate.get("expression") or "").strip()
            target_layer = str(candidate.get("target_layer") or metrics.get("target_layer") or "L2").upper()
            published_identity = _published_factor_identity(
                expression,
                target_layer=target_layer,
                metrics=metrics,
            )
            factor_id = (
                str(candidate.get("target_factor_id") or published_identity.factor_id)
                if is_external_import
                else published_identity.factor_id
            )
            if factor_id not in existing_factor_ids:
                existing = self.storage.fetch_one(
                    "SELECT id FROM factor_definitions WHERE id = ? AND deleted_at IS NULL",
                    (factor_id,),
                )
                if existing:
                    existing_factor_ids.add(factor_id)
            if factor_id in existing_factor_ids:
                continue
            if is_external_import:
                candidate_op_status = candidate.get("op_status") if isinstance(candidate.get("op_status"), Mapping) else None
                projection_op_status = candidate_op_status or (
                    factor_service._factor_processing_ops(  # noqa: SLF001
                        {
                            "id": factor_id,
                            "source": "PUBLIC_FACTOR_IMPORT",
                            "expression": expression,
                            "latest_diagnostic_summary": {
                                "operator_chain": metrics.get("operator_chain"),
                                "wnzt_complete": metrics.get("wnzt_complete"),
                                "wnzt_evidence": metrics.get("wnzt_evidence"),
                            },
                        }
                    )
                    if hasattr(factor_service, "_factor_processing_ops")
                    else None
                )
                projection = external_factor_import_display_projection_v1(
                    source_id=metrics.get("external_source_id"),
                    dataset_key=metrics.get("external_dataset_key"),
                    frequency=metrics.get("external_frequency"),
                    factor_id=metrics.get("external_factor_id"),
                    factor_name=metrics.get("external_factor_name"),
                    metrics=metrics,
                    previous_display_name=metrics.get("external_import_display_name")
                    or candidate.get("display_name_cn")
                    or candidate.get("factor_name")
                    or candidate.get("name"),
                    op_status=projection_op_status,
                )
                display_name = str(projection["display_name_cn"])
                metrics = dict(metrics)
                metrics["external_import_display_name"] = display_name
                metrics["external_import_name_audit"] = projection.get("name_audit")
                candidate["candidate_metrics"] = metrics
                projection = {
                    "base_display_name_cn": display_name,
                    "display_name_cn": display_name,
                    "compact_display_name_cn": display_name,
                    "name_collision_key": projection.get("name_collision_key"),
                    "name_dedupe_suffix": "",
                    "name_collision_group": [],
                    "governance_badges": projection.get("governance_badges") or candidate.get("governance_badges") or ["外部", "B3 检疫", "Raw"],
                    "name_schema_version": projection.get("name_schema_version") or candidate.get("name_schema_version"),
                    "naming_protocol_version": projection.get("naming_protocol_version") or candidate.get("naming_protocol_version"),
                    "name_audit": dict(projection.get("name_audit") or candidate.get("name_audit") or {}),
                }
            else:
                projection = factor_display_name_projection_v4(
                    factor_id=factor_id,
                    source="AUTO_MINED",
                    expression=expression,
                    tier_level=target_layer.replace("L", "F"),
                    neutralization_scope=metrics.get("neutralization_scope") or metrics.get("orthogonality_intent"),
                    residual_control=metrics.get("residual_control") or ("market_beta" if "beta" in expression.lower() else None),
                )
                display_name = str(
                    projection.get("base_display_name_cn")
                    or candidate.get("display_name_cn")
                    or candidate.get("factor_name")
                    or candidate.get("name")
                    or projection.get("display_name_cn")
                    or expression
                )
            op_status_key = self._factor_factory_operator_status_key(
                factor_service,
                {
                    "id": factor_id,
                    "source": "PUBLIC_FACTOR_IMPORT" if is_external_import else "AUTO_MINED",
                    "expression": expression,
                    "latest_diagnostic_summary": {
                        "wnzt_complete": metrics.get("wnzt_complete"),
                        "wnzt_evidence": metrics.get("wnzt_evidence"),
                        "operator_chain": metrics.get("operator_chain"),
                    },
                },
            )
            block_keys = self._factor_factory_publishable_block_keys(
                factor_id=factor_id,
                name_collision_key=projection.get("name_collision_key"),
                base_display_name_cn=projection.get("base_display_name_cn") or display_name,
                display_name_cn=display_name,
                factor_name=candidate.get("factor_name") or candidate.get("name"),
                op_status_key=op_status_key,
            )
            if not is_external_import and library_blockers is None:
                library_blockers = self._factor_factory_library_publish_blockers()
            if block_keys.intersection(library_blockers or {}):
                continue
            keys = self._factor_factory_redundancy_keys(
                factor_id=factor_id,
                name_collision_key=projection.get("name_collision_key"),
                base_display_name_cn=projection.get("base_display_name_cn") or display_name,
                expression=expression,
                op_status_key=op_status_key,
            )
            correlation_projection = self._factor_factory_correlation_projection(
                factor_service,
                factor_id=factor_id,
                expression=expression,
                display_name=display_name,
                target_layer=target_layer,
            )
            score = _coerce_float(
                metrics.get("fitness_score") if metrics.get("fitness_score") is not None else metrics.get("score"),
                0.0,
            )
            candidate_row = {
                "candidate_id": candidate.get("id"),
                "factor_id": factor_id or candidate.get("id"),
                "expression": expression,
                "raw_expression": candidate.get("raw_expression") or metrics.get("raw_expression"),
                "refined_expression": candidate.get("refined_expression") or metrics.get("refined_expression"),
                "factor_name": display_name,
                "display_name_cn": display_name,
                "base_display_name_cn": projection.get("base_display_name_cn"),
                "compact_display_name_cn": projection.get("display_name_cn") or candidate.get("compact_display_name_cn"),
                "name_collision_key": projection.get("name_collision_key"),
                "name_dedupe_suffix": projection.get("name_dedupe_suffix") or "",
                "name_collision_group": projection.get("name_collision_group") or [],
                "name_audit": projection.get("name_audit") or {},
                "governance_badges": projection.get("governance_badges") or candidate.get("governance_badges") or [],
                "name_schema_version": projection.get("name_schema_version") or candidate.get("name_schema_version"),
                "naming_protocol_version": projection.get("naming_protocol_version"),
                "target_layer": target_layer,
                "score": score,
                "quarantine_status": "PASS",
                "quarantine_result": candidate.get("quarantine_result") or "PASS",
                "reason_summary": candidate.get("reason_summary"),
                "parent_factor_ids": list(metrics.get("source_factor_ids") or []),
                "operator_chain": list(candidate.get("operator_chain") or metrics.get("operator_chain") or []),
                "composition_methods": list(candidate.get("composition_methods") or metrics.get("composition_methods") or []),
                "investment_logic": str(candidate.get("investment_logic") or metrics.get("investment_logic") or ""),
                "candidate_metrics": dict(metrics),
                "gate_summary": dict(candidate.get("gate_summary") or {}) if isinstance(candidate.get("gate_summary"), Mapping) else {},
                "pit_evidence": dict(candidate.get("pit_evidence") or {}) if isinstance(candidate.get("pit_evidence"), Mapping) else {},
                "publish_eligibility": dict(candidate.get("publish_eligibility") or {}) if isinstance(candidate.get("publish_eligibility"), Mapping) else {},
                "latest_run": dict(candidate.get("latest_run") or {}) if isinstance(candidate.get("latest_run"), Mapping) else {},
                "scoring_detail": dict(candidate.get("scoring_detail") or {}) if isinstance(candidate.get("scoring_detail"), Mapping) else {},
                "admission_report": list(candidate.get("admission_report") or []) if isinstance(candidate.get("admission_report"), list) else [],
                "wnzt_missing": list(candidate.get("wnzt_missing") or []) if isinstance(candidate.get("wnzt_missing"), list) else [],
                "wnzt_complete": bool(candidate.get("wnzt_complete")),
                "wnzt_evidence": dict(candidate.get("wnzt_evidence") or {}) if isinstance(candidate.get("wnzt_evidence"), Mapping) else {},
                "artifact_refs": dict(candidate.get("artifact_refs") or {}) if isinstance(candidate.get("artifact_refs"), Mapping) else {},
                "created_at": candidate.get("created_at"),
                "updated_at": candidate.get("updated_at"),
                "last_quarantine_at": candidate.get("last_quarantine_at"),
                "published_at": candidate.get("published_at"),
                "detail_modal_enabled": True,
                "redundancy_pruning": "PASSED",
                "operator_status_key": op_status_key,
            }
            candidate_row["redundancy_group_key"] = "|".join(sorted(keys))
            self._append_factor_factory_redundancy_group(
                groups,
                keys=keys,
                item=candidate_row,
                correlation_projection=correlation_projection,
            )
        winners = [
            max(
                group.get("items") or [],
                key=lambda item: (_coerce_float(item.get("score"), 0.0), str(item.get("candidate_id") or "")),
            )
            for group in groups
            if group.get("items")
        ]
        return sorted(
            winners,
            key=lambda item: (-_coerce_float(item.get("score"), 0.0), str(item.get("factor_id") or "")),
        )

    def _factor_factory_phase2_rows(
        self,
        *,
        profile: Mapping[str, Any],
        latest_run: Mapping[str, Any] | None,
        runs: Sequence[Mapping[str, Any]],
        mining: Mapping[str, Any],
        quarantine: Mapping[str, Any],
        batch_lineage: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        batch_lineage = batch_lineage if isinstance(batch_lineage, Mapping) else {}
        mining_items = mining.get("items") if isinstance(mining.get("items"), list) else []
        quarantine_items = quarantine.get("items") if isinstance(quarantine.get("items"), list) else []
        quarantine_summary = quarantine.get("summary") if isinstance(quarantine.get("summary"), Mapping) else {}
        run_date = str((latest_run or {}).get("run_date") or self._factor_factory_today())
        latest_summary = latest_run.get("summary") if isinstance((latest_run or {}).get("summary"), Mapping) else {}
        operator_engine_summary = (
            latest_summary.get("operator_engine")
            if isinstance(latest_summary.get("operator_engine"), Mapping)
            else {}
        )
        source_mining_job_id = str(
            batch_lineage.get("source_job_id")
            or (latest_run or {}).get("mining_job_id")
            or latest_summary.get("mining_job_id")
            or ""
        )
        f1_snapshot_id = str(
            latest_summary.get("f1_catalog_snapshot_id")
            or operator_engine_summary.get("f1_catalog_snapshot_id")
            or ""
        )
        f1_count = 0
        if f1_snapshot_id:
            count_row = self.storage.fetch_one(
                "SELECT COUNT(*) AS count FROM f1_raw_factor_fields WHERE snapshot_id = ?",
                (f1_snapshot_id,),
            )
            f1_count = int((count_row or {}).get("count") or 0)
        top_candidates = []
        if latest_run and isinstance(latest_run.get("mining_job"), Mapping):
            top_candidates = list(latest_run["mining_job"].get("top_candidates") or [])
        elif mining_items:
            top_candidates = list((mining_items[0] or {}).get("top_candidates") or [])
        raw_f2_count = int(
            batch_lineage.get("raw_f2_total")
            or operator_engine_summary.get("raw_f2_batch_delivered_count")
            or operator_engine_summary.get("deduped_formula_count")
            or len(top_candidates)
        )
        refined_f2_count = int(
            batch_lineage.get("refined_f2_total")
            or operator_engine_summary.get("refined_f2_batch_delivered_count")
            or 0
        )
        l3_count_known = "f3_composition_candidate_count" in operator_engine_summary
        l3_candidate_count = int(operator_engine_summary.get("f3_composition_candidate_count") or 0)
        source_candidate_metric_rows: list[Mapping[str, Any]] = []
        if source_mining_job_id and (refined_f2_count <= 0 or not l3_count_known):
            source_candidate_metric_rows = self.storage.fetch_all(
                """
                SELECT candidate_metrics_json
                FROM factor_quarantine_candidates
                WHERE source_mining_job_id = ?
                """,
                (source_mining_job_id,),
            )
        if source_candidate_metric_rows and refined_f2_count <= 0:
            refined_f2_count = sum(
                1
                for row in source_candidate_metric_rows
                if bool(loads(row.get("candidate_metrics_json"), {}).get("refined_f2"))
            )
        if source_candidate_metric_rows and not l3_count_known:
            l3_candidate_count = sum(
                1
                for row in source_candidate_metric_rows
                if str(loads(row.get("candidate_metrics_json"), {}).get("target_layer") or "").upper() == "L3"
            )
        if not source_candidate_metric_rows and not l3_count_known:
            l3_candidate_count = sum(
                1
                for item in quarantine_items
                if isinstance(item, Mapping) and str(item.get("target_layer") or "").upper() == "L3"
            )
        quarantine_total = int(batch_lineage.get("quarantine_total") or quarantine_summary.get("total") or len(quarantine_items))
        task_status = self._factor_factory_task_status(latest_run)
        delivered_count = raw_f2_count if task_status == "已完成" else None
        task_rows = [
            {
                "id": f"{run_date}-mining",
                "task_date": run_date,
                "kind": "mining",
                "title": f"{run_date} 因子挖掘任务",
                "summary": "F1 按算子展开生成 Raw_F2，并经过 WNZT 治理形成 Refined_F2。",
                "status": task_status,
                "target_layer": "L2",
                "flow": ["F1", "算子展开", "Raw_F2", "WNZT", "Refined_F2"],
                "delivered_candidate_count": delivered_count,
                "current_candidate_count": raw_f2_count,
                "expected_candidate_count": raw_f2_count,
                "metric_label": "Raw_F2因子交付量",
                "metric_value": raw_f2_count,
                "secondary_metric_label": "Refined_F2因子交付量",
                "secondary_metric_value": refined_f2_count,
                "source_metric_label": "F1因子量",
                "source_metric_value": f1_count,
            },
            {
                "id": f"{run_date}-composition",
                "task_date": run_date,
                "kind": "composition",
                "title": f"{run_date} 因子组合任务",
                "summary": "从 Refined_F2 构建 F3 组合候选，发布前仍需检疫通过和人工确认。",
                "status": task_status,
                "target_layer": "L3",
                "flow": ["Refined_F2", "F3组合", "检疫", "发布确认"],
                "delivered_candidate_count": l3_candidate_count if task_status == "已完成" else None,
                "current_candidate_count": l3_candidate_count,
                "expected_candidate_count": raw_f2_count,
                "metric_label": "组合候选量",
                "metric_value": l3_candidate_count,
                "parent_factor_ids": list((profile.get("request") or {}).get("source_factor_ids") or []),
            },
        ]
        ranked_quarantine_items = sorted(
            [item for item in quarantine_items if isinstance(item, Mapping)],
            key=lambda item: (
                str(item.get("source_mining_job_id") or "").startswith("extimp_"),
                str(self._factor_factory_candidate_event_time(item) or ""),
            ),
            reverse=True,
        )
        factor_service = self._factor_research_service()
        submitted_signatures = (
            self._factor_factory_quarantine_signatures_for_job(source_mining_job_id)
            if source_mining_job_id
            else {
                factor_service._expression_signature(str(item.get("expression") or ""))
                for item in ranked_quarantine_items
                if str(item.get("expression") or "").strip()
            }
        )
        scoring_candidates = []
        for index, item in enumerate(top_candidates):
            if not isinstance(item, Mapping):
                continue
            expression = str(item.get("expression") or "").strip()
            if not expression:
                continue
            signature = factor_service._expression_signature(expression)
            if signature in submitted_signatures:
                continue
            metrics = dict(item)
            metrics.setdefault("sandbox_rank", index + 1)
            candidate_id = str(item.get("id") or item.get("candidate_id") or f"{run_date}-pending-{index + 1}")
            pending_candidate = {
                "id": candidate_id,
                "expression": expression,
                "candidate_metrics": metrics,
                "created_at": item.get("created_at") or (latest_run or {}).get("created_at") or run_date,
                "updated_at": item.get("updated_at") or (latest_run or {}).get("updated_at") or run_date,
                "pit_evidence": {
                    "promotion_eligible": True,
                    "gate_mode": "DIAGNOSTIC_ONLY",
                },
            }
            detail = factor_service._factor_phase2_scoring_detail(pending_candidate)
            display_projection = factor_display_name_projection_v4(
                factor_id=candidate_id,
                name=item.get("factor_name") or item.get("name"),
                source="AUTO_MINED",
                expression=expression,
                tier_level=detail.get("target_layer") or "F2",
            )
            display_name = str(display_projection.get("base_display_name_cn") or display_projection["display_name_cn"])
            scoring_candidates.append({
                **dict(detail),
                "candidate_id": candidate_id,
                "display_id": display_name,
                "display_name_cn": display_name,
                "compact_display_name_cn": display_projection.get("display_name_cn"),
                "short_name_cn": display_projection.get("short_name_cn"),
                "governance_badges": display_projection.get("governance_badges") or [],
                "name_schema_version": display_projection.get("name_schema_version"),
                "target_layer": detail.get("target_layer") or "L2",
                "submitted_at": pending_candidate["updated_at"],
                "quarantine_candidate_id": None,
                "quarantine_result": None,
            })
        quarantine_result_rows = []
        for item in ranked_quarantine_items:
            if not isinstance(item, Mapping):
                continue
            reason_summary = self._factor_factory_quarantine_reason_summary(item)
            event_time = self._factor_factory_candidate_event_time(item)
            display_name = item.get("display_name_cn") or item.get("base_display_name_cn") or item.get("factor_name") or item.get("name") or item.get("expression")
            quarantine_result_rows.append({
                "candidate_id": item.get("id"),
                "submitted_at": event_time,
                "factor_name": display_name,
                "display_name_cn": display_name,
                "governance_badges": item.get("governance_badges") or [],
                "name_schema_version": item.get("name_schema_version"),
                "target_layer": item.get("target_layer") or "L2",
                "quarantine_result": self._factor_factory_quarantine_result(item),
                "reason_summary": reason_summary,
                "detail_modal_enabled": True,
            })
        defer_non_external_publishables = (
            str(latest_summary.get("auto_quarantine_status") or "").upper() == "PARTIAL"
            and int(_coerce_float(latest_summary.get("auto_quarantine_pending_count"), 0.0)) > 0
        )
        if source_mining_job_id and bool(batch_lineage.get("publish_blocked")):
            publishable_factors = []
        else:
            publishable_factors = self._factor_factory_publishable_factors(
                source_mining_job_id=source_mining_job_id,
                fallback_items=[item for item in quarantine_items if isinstance(item, Mapping)],
                defer_non_external=defer_non_external_publishables,
                include_external_imports=True,
            )
        return {
            "task_summary": {
                "total_tasks": len(task_rows),
                "delivered_candidates": sum(int(row.get("current_candidate_count") or 0) for row in task_rows),
                "submitted_to_quarantine": quarantine_total,
                "publishable_count": len(publishable_factors),
                "rejected_history_count": int(quarantine_summary.get("rejected_count") or 0),
                "hard_blocked_count": int(quarantine_summary.get("rejected_count") or 0),
            },
            "task_rows": task_rows,
            "scoring_candidates": scoring_candidates,
            "quarantine_result_rows": quarantine_result_rows,
            "publishable_factors": publishable_factors,
            "phase2_contract": {
                "flow": "B1-B2-B3",
                "daily_schedule": "GMT+8 14:00",
                "operator_engine": "pandas_bottleneck",
                "daily_formula_budget": DEFAULT_DAILY_FORMULA_BUDGET,
                "l2_operator_chain": "F1 -> OperatorEngine -> Raw_F2 -> WNZT -> Refined F2",
                "optional_governance": {"orthogonalization": False, "turnover_filter": False},
                "l3_composition_methods": [
                    "风格复合",
                    "比例/风险调整（含估值锚定）",
                    "排名均值/交集",
                    "Fama-French 风格融合",
                    "背离惩罚",
                    "残差/中性化",
                    "时序降噪",
                ],
            },
        }

    def create_pit_preprocessing_run(self, request: Any | None = None) -> dict[str, Any]:
        payload = dict(_as_mapping(request or {}))
        as_of_date = str(payload.get("as_of_date") or self._factor_factory_today())
        mode = str(payload.get("mode") or "MANUAL").upper()
        if mode not in {"DAILY", "MANUAL", "SNAPSHOT_REFRESH"}:
            mode = "MANUAL"
        run_id = f"pit_pre_{as_of_date.replace('-', '')}_{uuid4().hex[:8]}"
        now = iso_now()
        source_signature = {
            "dataset_snapshot_count": len(self.market_data_repository.list_dataset_snapshots()),
            "universe_snapshot_count": len(self.market_data_repository.list_universe_snapshots()),
        }
        self.storage.insert_json_row(
            "pit_preprocessing_runs",
            {
                "id": run_id,
                "run_id": run_id,
                "as_of_date": as_of_date,
                "mode": mode,
                "status": "RUNNING",
                "source_signature_json": dumps(source_signature),
                "provider_summary_json": dumps({}),
                "blocker_summary_json": dumps({}),
                "started_at": now,
                "completed_at": None,
                "created_at": now,
                "updated_at": now,
                "error_message": None,
            },
        )
        snapshot: Mapping[str, Any] = {}
        try:
            catalog = persist_f1_catalog_snapshot(
                storage=self.storage,
                repository=self.market_data_repository,
                run_id=run_id,
                as_of_date=as_of_date,
            )
            snapshot = catalog["snapshot"]
            blocker_summary = {
                "blocked_count": snapshot.get("blocked_count", 0),
                "timing_gap_count": snapshot.get("timing_gap_count", 0),
                "blocking_codes": sorted({
                    str(field.get("blocker_code"))
                    for field in catalog["fields"]
                    if field.get("blocker_code")
                }),
                "l1_missing_policy": "NaN_WITH_DATA_SOURCE_BLOCKED",
            }
            completed_at = iso_now()
            self.storage.execute(
                """
                UPDATE pit_preprocessing_runs
                SET status = 'COMPLETED',
                    provider_summary_json = ?,
                    blocker_summary_json = ?,
                    completed_at = ?,
                    updated_at = ?
                WHERE run_id = ?
                """,
                (
                    dumps({"f1_catalog_snapshot_id": snapshot.get("snapshot_id"), "field_count": snapshot.get("field_count")}),
                    dumps(blocker_summary),
                    completed_at,
                    completed_at,
                    run_id,
                ),
            )
        except Exception as exc:
            failed_at = iso_now()
            self.storage.execute(
                """
                UPDATE pit_preprocessing_runs
                SET status = 'FAILED', completed_at = ?, updated_at = ?, error_message = ?
                WHERE run_id = ?
                """,
                (failed_at, failed_at, str(exc), run_id),
            )
            raise
        row = self.storage.fetch_one("SELECT * FROM pit_preprocessing_runs WHERE run_id = ?", (run_id,))
        f1_snapshot = self._ensure_f1_catalog_snapshot(str(snapshot.get("snapshot_id")))
        return {
            **self._decode_pit_preprocessing_run(row),
            "catalog_snapshot_id": snapshot.get("snapshot_id"),
            "summary": f1_snapshot.get("summary", {}),
            "f1_catalog_snapshot": f1_snapshot,
        }

    def _decode_pit_preprocessing_run(self, row: Mapping[str, Any] | None) -> dict[str, Any]:
        if not row:
            return {}
        provider_summary = loads(row.get("provider_summary_json"), {})
        return {
            "id": row.get("run_id") or row.get("id"),
            "run_id": row.get("run_id") or row.get("id"),
            "as_of_date": row.get("as_of_date"),
            "mode": row.get("mode"),
            "status": row.get("status"),
            "source_signature": loads(row.get("source_signature_json"), {}),
            "provider_summary": provider_summary,
            "catalog_snapshot_id": provider_summary.get("f1_catalog_snapshot_id"),
            "blocker_summary": loads(row.get("blocker_summary_json"), {}),
            "started_at": row.get("started_at"),
            "completed_at": row.get("completed_at"),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
            "error_message": row.get("error_message"),
        }

    def list_pit_preprocessing_runs(self, limit: int = 20) -> dict[str, Any]:
        safe_limit = max(1, min(int(limit or 20), 100))
        rows = self.storage.fetch_all(
            """
            SELECT *
            FROM pit_preprocessing_runs
            ORDER BY created_at DESC, run_id DESC
            LIMIT ?
            """,
            (safe_limit,),
        )
        return {"items": [self._decode_pit_preprocessing_run(row) for row in rows], "summary": {"count": len(rows)}}

    def get_pit_preprocessing_run(self, run_id: str) -> dict[str, Any]:
        row = self.storage.fetch_one("SELECT * FROM pit_preprocessing_runs WHERE run_id = ?", (run_id,))
        if not row:
            raise KeyError(f"PIT preprocessing run not found: {run_id}")
        return self._decode_pit_preprocessing_run(row)

    def list_f1_catalog(
        self,
        *,
        snapshot_id: str | None = None,
        layer: str | None = None,
        status: str | None = None,
        q: str | None = None,
    ) -> dict[str, Any]:
        snapshot = self._ensure_f1_catalog_snapshot(snapshot_id)
        active_snapshot_id = str(snapshot.get("snapshot_id") or snapshot.get("id"))
        where = ["snapshot_id = ?"]
        params: list[Any] = [active_snapshot_id]
        if layer:
            where.append("UPPER(pit_layer) = ?")
            params.append(str(layer).upper())
        if status:
            where.append("UPPER(admission_state) = ?")
            params.append(str(status).upper())
        rows = self.storage.fetch_all(
            f"""
            SELECT *
            FROM f1_raw_factor_fields
            WHERE {' AND '.join(where)}
            ORDER BY pit_layer, category, factor_id
            """,
            params,
        )
        items = []
        for row in rows:
            item = decode_f1_field_row(row)
            projection = factor_display_name_projection_v4(
                factor_id=str(item.get("factor_id") or ""),
                name=item.get("name"),
                source="F1_CATALOG",
                expression=str(item.get("factor_id") or ""),
                tier_level="F1",
            )
            item.update(projection)
            item["name"] = projection["display_name_cn"]
            items.append(item)
        if q:
            needle = str(q).strip().lower()
            items = [
                item
                for item in items
                if needle in str(item.get("factor_id") or "").lower()
                or needle in str(item.get("name") or "").lower()
                or needle in str(item.get("category") or "").lower()
                or any(needle in str(alias).lower() for alias in item.get("legacy_name_aliases") or [])
            ]
        summary = dict(snapshot.get("summary") or {})
        summary.update({
            "snapshot_id": active_snapshot_id,
            "item_count": len(items),
            "callable_count": sum(1 for item in items if item.get("admission_state") in {"READY", "READY_WITH_WARNING"}),
            "blocked_count": sum(1 for item in items if item.get("admission_state") == "DATA_SOURCE_BLOCKED"),
            "timing_gap_count": sum(1 for item in items if item.get("admission_state") == "MISSING_TIMING"),
            "ic_ir_gate": "NOT_APPLIED",
        })
        return {"snapshot": snapshot, "items": items, "summary": summary}

    def get_f1_catalog_latest(self) -> dict[str, Any]:
        return self.list_f1_catalog()

    def preview_sec_424b2_structured_note(self, request: Any | None = None) -> dict[str, Any]:
        payload = _as_mapping(request)
        source_url = str(payload.get("source_url") or "").strip()
        issuer_cik = str(payload.get("issuer_cik") or "").strip()
        accession_number = str(payload.get("accession_number") or "").strip()
        primary_document = str(payload.get("primary_document") or "").strip()
        html_text = str(payload.get("html") or "")
        if not html_text:
            provider = SecEdgarProvider()
            if source_url:
                html_text = provider.fetch_archive_document(source_url)
            elif issuer_cik:
                filings = provider.fetch_424b2_filings_by_cik(issuer_cik, limit=1)
                if not filings:
                    raise ValueError(f"No SEC 424B2 filings found for CIK {issuer_cik}.")
                latest = filings[0]
                source_url = str(latest.get("primary_document_url") or "")
                accession_number = accession_number or str(latest.get("accession_number") or "")
                primary_document = primary_document or str(latest.get("primary_document") or "")
                html_text = provider.fetch_archive_document(source_url)
            else:
                raise ValueError("SEC 424B2 parse preview requires html, source_url, or issuer_cik.")
        result = parse_sec_424b2_structured_note(
            html_text,
            source_url=source_url,
            issuer_cik=issuer_cik,
            accession_number=accession_number,
            primary_document=primary_document,
            parser_options=payload.get("parser_options") if isinstance(payload.get("parser_options"), Mapping) else {},
        )
        if payload.get("persist"):
            self._persist_sec_424b2_parse_result(result)
            return self.get_sec_424b2_parse_run(str(result["parse_run"]["run_id"]))
        return result

    def _persist_sec_424b2_parse_result(self, result: Mapping[str, Any]) -> None:
        now = iso_now()
        parse_run = dict(result.get("parse_run") or {})
        note = dict(result.get("note") or {})
        underlyings = [dict(item) for item in result.get("underlyings") or [] if isinstance(item, Mapping)]
        run_id = str(parse_run.get("run_id") or "")
        note_id = str(note.get("note_id") or note.get("factor_id") or "")
        if not run_id or not note_id:
            raise ValueError("SEC 424B2 parse result is missing run_id or note_id.")
        self.storage.insert_json_row(
            "sec_424b2_parse_runs",
            {
                "id": run_id,
                "run_id": run_id,
                "accession_number": str(parse_run.get("accession_number") or ""),
                "issuer_cik": str(parse_run.get("issuer_cik") or ""),
                "source_url": str(parse_run.get("source_url") or ""),
                "primary_document_url": str(parse_run.get("primary_document_url") or ""),
                "raw_html_sha256": str(parse_run.get("raw_html_sha256") or ""),
                "normalized_text_hash": str(parse_run.get("normalized_text_hash") or ""),
                "table_signature_hash": str(parse_run.get("table_signature_hash") or ""),
                "parser_rule_hash": str(parse_run.get("parser_rule_hash") or ""),
                "parse_result_hash": str(parse_run.get("parse_result_hash") or ""),
                "parser_version": str(parse_run.get("parser_version") or ""),
                "status": str(parse_run.get("status") or "REVIEW_REQUIRED"),
                "warnings_json": dumps(list(parse_run.get("warnings") or [])),
                "llm_used": 1 if parse_run.get("llm_used") else 0,
                "created_at": str(parse_run.get("created_at") or now),
                "updated_at": now,
            },
        )
        self.storage.insert_json_row(
            "structured_note_terms",
            {
                "id": note_id,
                "note_id": note_id,
                "parse_run_id": run_id,
                "source_url": str(note.get("source_url") or ""),
                "issuer_cik": str(note.get("issuer_cik") or ""),
                "accession_number": str(note.get("accession_number") or ""),
                "cusip": note.get("cusip"),
                "pricing_date": note.get("pricing_date"),
                "issue_date": note.get("issue_date"),
                "maturity_date": note.get("maturity_date"),
                "coupon_rate_annual": note.get("coupon_rate_annual"),
                "coupon_frequency": str(note.get("coupon_frequency") or ""),
                "observation_frequency": str(note.get("observation_frequency") or ""),
                "autocall_frequency": str(note.get("autocall_frequency") or ""),
                "memory_feature": 1 if note.get("memory_feature") else 0,
                "payoff_type": str(note.get("payoff_type") or "REVIEW_REQUIRED"),
                "review_status": str(note.get("review_status") or result.get("status") or "REVIEW_REQUIRED"),
                "metadata_json": dumps(
                    {
                        **dict(note.get("metadata") or {}),
                        "factor_id": str(note.get("factor_id") or "f1_fcn_note_terms"),
                        "legacy_factor_id": str(note.get("legacy_factor_id") or note_id),
                        "underlying_count": len([item for item in underlyings if item.get("ticker")]),
                    }
                ),
                "evidence_json": dumps(dict(note.get("evidence") or {})),
                "created_at": now,
                "updated_at": now,
            },
        )
        self.storage.execute("DELETE FROM structured_note_underlyings WHERE note_id = ?", (note_id,))
        self.storage.execute("DELETE FROM structured_note_evidence_anchors WHERE note_id = ?", (note_id,))
        for underlying in underlyings:
            ticker = str(underlying.get("ticker") or "").upper()
            if not ticker:
                continue
            metadata = {
                **dict(underlying.get("metadata") or {}),
                "underlying_index": underlying.get("underlying_index"),
            }
            self.storage.insert_json_row(
                "structured_note_underlyings",
                {
                    "id": f"{note_id}_{re.sub(r'[^A-Z0-9]+', '_', ticker).strip('_')}",
                    "note_id": note_id,
                    "ticker": ticker,
                    "initial_value": underlying.get("initial_value"),
                    "strike_value": underlying.get("strike_value"),
                    "barrier_ratio": underlying.get("barrier_ratio"),
                    "barrier_value": underlying.get("barrier_value"),
                    "trigger_ratio": underlying.get("trigger_ratio"),
                    "trigger_value": underlying.get("trigger_value"),
                    "exchange": str(underlying.get("exchange") or ""),
                    "evidence_json": dumps(dict(underlying.get("evidence") or {})),
                    "metadata_json": dumps(metadata),
                    "created_at": now,
                    "updated_at": now,
                },
            )
        for anchor in self._sec_424b2_evidence_anchors(note, underlyings):
            anchor_text = str(anchor.get("text") or "")
            field_path = str(anchor.get("field_path") or "")
            anchor_id = "sec424b2_ev_" + hashlib.sha256(
                f"{note_id}|{field_path}|{anchor_text}".encode("utf-8")
            ).hexdigest()[:16]
            self.storage.insert_json_row(
                "structured_note_evidence_anchors",
                {
                    "id": anchor_id,
                    "note_id": note_id,
                    "field_path": field_path,
                    "table_index": anchor.get("table_index"),
                    "row_index": anchor.get("row_index"),
                    "column_index": anchor.get("column_index"),
                    "text": anchor_text,
                    "source_url": str(anchor.get("source_url") or note.get("source_url") or ""),
                    "created_at": now,
                },
            )
        self._invalidate_structured_note_f1_static_cache(note_id)

    def _invalidate_structured_note_f1_static_cache(self, note_id: str | None = None) -> None:
        with self._structured_note_f1_static_cache_lock:
            if note_id:
                self._structured_note_f1_static_cache.pop(str(note_id), None)
                self._structured_note_f1_static_cache_bytes.pop(str(note_id), None)
                return
            self._structured_note_f1_static_cache.clear()
            self._structured_note_f1_static_cache_bytes.clear()

    @staticmethod
    def _structured_note_bundle_approx_bytes(bundle: Mapping[str, Any]) -> int:
        return len(dumps(dict(bundle)).encode("utf-8", errors="replace"))

    def get_structured_note_f1_cache_stats(self) -> dict[str, Any]:
        with self._structured_note_f1_static_cache_lock:
            hits = self._structured_note_f1_static_cache_hits
            misses = self._structured_note_f1_static_cache_misses
            total = hits + misses
            approx_bytes = sum(self._structured_note_f1_static_cache_bytes.values())
            return {
                "cache_entry_count": len(self._structured_note_f1_static_cache),
                "cache_hit_count": hits,
                "cache_miss_count": misses,
                "cache_hit_rate": (hits / total) if total else 0.0,
                "eviction_count": self._structured_note_f1_static_cache_evictions,
                "approx_memory_bytes": approx_bytes,
                "approx_memory_mb": approx_bytes / (1024 * 1024),
                "max_notes": self._structured_note_f1_static_cache_max_notes,
                "policy": self._structured_note_f1_static_cache_policy,
                "warn_memory_bytes": self._structured_note_f1_static_cache_warn_bytes,
                "memory_guardrail_state": (
                    "WARN" if approx_bytes >= self._structured_note_f1_static_cache_warn_bytes else "OK"
                ),
            }

    def _store_structured_note_f1_static_cache_entry(self, note_id: str, bundle: Mapping[str, Any]) -> None:
        normalized_note_id = str(note_id)
        cached_bundle = deepcopy(dict(bundle))
        approx_bytes = self._structured_note_bundle_approx_bytes(cached_bundle)
        self._structured_note_f1_static_cache[normalized_note_id] = cached_bundle
        self._structured_note_f1_static_cache.move_to_end(normalized_note_id)
        self._structured_note_f1_static_cache_bytes[normalized_note_id] = approx_bytes
        if self._structured_note_f1_static_cache_policy == "read_through_lru":
            while len(self._structured_note_f1_static_cache) > self._structured_note_f1_static_cache_max_notes:
                evicted_note_id, evicted_bundle = self._structured_note_f1_static_cache.popitem(last=False)
                evicted_bytes = self._structured_note_f1_static_cache_bytes.pop(
                    evicted_note_id,
                    self._structured_note_bundle_approx_bytes(evicted_bundle),
                )
                self._structured_note_f1_static_cache_evictions += 1
                logger.debug(
                    "structured_note_f1_cache_evicted",
                    extra={
                        "note_id": evicted_note_id,
                        "approx_memory_bytes": evicted_bytes,
                        "cache_entry_count_after": len(self._structured_note_f1_static_cache),
                        "max_notes": self._structured_note_f1_static_cache_max_notes,
                        "policy": self._structured_note_f1_static_cache_policy,
                    },
                )

    def list_structured_note_fcn_factor_definitions(self) -> dict[str, Any]:
        definitions = structured_note_factor_definitions()
        f1_count = sum(1 for item in definitions if item.get("layer") == "F1")
        f2_count = sum(1 for item in definitions if item.get("layer") == "F2")
        note_instance_count = self.storage.fetch_one("SELECT COUNT(*) AS count FROM structured_note_terms")
        replay_series_count = self.storage.fetch_one("SELECT COUNT(DISTINCT note_id || ':' || run_id) AS count FROM structured_note_replay_runs")
        return {
            "definition_version": STRUCTURED_NOTE_DEFINITION_VERSION,
            "definitions": definitions,
            "summary": {
                "f1_definition_count": f1_count,
                "f2_definition_count": f2_count,
                "note_instance_count": int((note_instance_count or {}).get("count") or 0),
                "f2_series_count": int((replay_series_count or {}).get("count") or 0),
                "publish_boundary": "sandbox -> quarantine -> publish",
            },
        }

    def get_structured_note_fcn_factor_factory_mount_contract(self) -> dict[str, Any]:
        definitions = structured_note_factor_definitions()
        f2_definitions = [dict(item) for item in definitions if str(item.get("layer") or "") == "F2"]
        f2_definition_ids = [str(item.get("definition_id") or "") for item in f2_definitions if item.get("definition_id")]
        note_instance_count = self.storage.fetch_one("SELECT COUNT(*) AS count FROM structured_note_terms")
        replay_series_count = self.storage.fetch_one(
            "SELECT COUNT(DISTINCT note_id || ':' || run_id) AS count FROM structured_note_replay_runs"
        )
        return {
            "definition_version": STRUCTURED_NOTE_DEFINITION_VERSION,
            "registration_status": "CONTRACT_READY",
            "f2_definition_ids": f2_definition_ids,
            "dimension_schema": {
                "primary_dimensions": ["note_id", "note_date"],
                "instance_binding": "note_id",
                "time_dimension": "note_date",
                "series_shape": "note_id x f2_definition_id x note_date",
                "definition_count_policy": "stable_templates_not_per_note_ids",
            },
            "display_name_cn": "[外部] - FCN增强收益归因 [精炼]",
            "publish_boundary": "sandbox -> quarantine -> publish",
            "factor_library_write": "BLOCKED_UNTIL_QUARANTINE_PUBLISH",
            "summary": {
                "note_instance_count": int((note_instance_count or {}).get("count") or 0),
                "f2_series_count": int((replay_series_count or {}).get("count") or 0),
                "f2_definition_count": len(f2_definition_ids),
                "quarantine_required": True,
                "refined_status_requires": [
                    "clean_preflight_without_initial_value_proxy",
                    "shadow_replay_points_persisted",
                    "attribution_evidence_available",
                    "factor_factory_quarantine_publish_approval",
                ],
            },
        }

    def get_structured_note_f1_static_bundle(self, note_id: str) -> dict[str, Any]:
        normalized_note_id = str(note_id or "").strip()
        if not normalized_note_id:
            raise ValueError("Structured note F1 bundle requires note_id.")
        with self._structured_note_f1_static_cache_lock:
            cached = self._structured_note_f1_static_cache.get(normalized_note_id)
            if cached is not None:
                self._structured_note_f1_static_cache_hits += 1
                self._structured_note_f1_static_cache.move_to_end(normalized_note_id)
                result = deepcopy(cached)
                result["cache_status"] = "HIT"
                result["cache_load_count"] = self._structured_note_f1_static_cache_load_count.get(normalized_note_id, 0)
                result["approx_memory_bytes"] = self._structured_note_f1_static_cache_bytes.get(normalized_note_id, 0)
                return result
        bundle = self._build_structured_note_f1_static_bundle(normalized_note_id)
        with self._structured_note_f1_static_cache_lock:
            self._structured_note_f1_static_cache_misses += 1
            self._store_structured_note_f1_static_cache_entry(normalized_note_id, bundle)
            self._structured_note_f1_static_cache_load_count[normalized_note_id] = (
                self._structured_note_f1_static_cache_load_count.get(normalized_note_id, 0) + 1
            )
            result = deepcopy(bundle)
            result["cache_status"] = "MISS"
            result["cache_load_count"] = self._structured_note_f1_static_cache_load_count.get(normalized_note_id, 0)
            result["approx_memory_bytes"] = self._structured_note_f1_static_cache_bytes.get(normalized_note_id, 0)
            return result

    def _build_structured_note_f1_static_bundle(self, note_id: str) -> dict[str, Any]:
        note_row = self.storage.fetch_one("SELECT * FROM structured_note_terms WHERE note_id = ?", (note_id,))
        if not note_row:
            raise ValueError(f"Structured note not found: {note_id}")
        parse_run_id = str(note_row.get("parse_run_id") or "")
        parse_run = self.storage.fetch_one("SELECT * FROM sec_424b2_parse_runs WHERE run_id = ?", (parse_run_id,))
        underlying_rows = self.storage.fetch_all(
            "SELECT * FROM structured_note_underlyings WHERE note_id = ? ORDER BY ticker",
            (note_id,),
        )
        underlyings = self._sort_structured_note_underlyings(
            [self._decode_structured_note_underlying(row) for row in underlying_rows]
        )
        note = self._decode_structured_note_terms(note_row, underlyings)
        metadata = note.get("metadata") if isinstance(note.get("metadata"), Mapping) else {}
        parser_version = str((parse_run or {}).get("parser_version") or metadata.get("parser_version") or "")
        parser_rule_hash = str((parse_run or {}).get("parser_rule_hash") or "")
        barrier_ratio = _min_present_float(item.get("barrier_ratio") for item in underlyings)
        trigger_ratio = _min_present_float(item.get("trigger_ratio") for item in underlyings)
        static_terms = {
            "f1_fcn_note_id": note_id,
            "f1_fcn_issuer_cik": note.get("issuer_cik"),
            "f1_fcn_accession_number": note.get("accession_number"),
            "f1_fcn_primary_document": note.get("primary_document"),
            "f1_fcn_source_url": note.get("source_url"),
            "f1_fcn_cusip": note.get("cusip"),
            "f1_fcn_pricing_date": note.get("pricing_date"),
            "f1_fcn_issue_date": note.get("issue_date"),
            "f1_fcn_maturity_date": note.get("maturity_date"),
            "f1_fcn_coupon_rate_annual": note.get("coupon_rate_annual"),
            "f1_fcn_coupon_frequency": note.get("coupon_frequency"),
            "f1_fcn_observation_frequency": note.get("observation_frequency"),
            "f1_fcn_autocall_frequency": note.get("autocall_frequency"),
            "f1_fcn_memory_feature": note.get("memory_feature"),
            "f1_fcn_payoff_type": note.get("payoff_type"),
            "f1_fcn_barrier_ratio": barrier_ratio,
            "f1_fcn_trigger_ratio": trigger_ratio,
            "f1_fcn_call_threshold_ratio": (metadata or {}).get("call_threshold_ratio", 1.0),
            "f1_fcn_review_status": note.get("review_status"),
            "f1_fcn_underlying_count": len(underlyings),
            "f1_fcn_parser_version": parser_version,
            "f1_fcn_parser_rule_hash": parser_rule_hash,
            "f1_fcn_raw_html_sha256": (parse_run or {}).get("raw_html_sha256"),
            "f1_fcn_table_signature_hash": (parse_run or {}).get("table_signature_hash"),
        }
        underlying_slots = []
        missing_fields: list[str] = []
        if not underlyings:
            missing_fields.append("f1_fcn_underlying_count")
        if note.get("review_status") != "PARSED":
            missing_fields.append("REVIEW_REQUIRED")
        if note.get("coupon_rate_annual") is None:
            missing_fields.append("f1_fcn_coupon_rate_annual")
        for index, underlying in enumerate(underlyings):
            initial_value = underlying.get("initial_value") if underlying.get("initial_value") is not None else underlying.get("strike_value")
            slot = {
                "underlying_index": index,
                "ticker": str(underlying.get("ticker") or "").upper(),
                "initial_value": initial_value,
                "strike_value": underlying.get("strike_value"),
                "barrier_ratio": underlying.get("barrier_ratio"),
                "barrier_value": underlying.get("barrier_value"),
                "trigger_ratio": underlying.get("trigger_ratio"),
                "trigger_value": underlying.get("trigger_value"),
                "exchange": str(underlying.get("exchange") or ""),
            }
            underlying_slots.append(slot)
            if not slot["ticker"]:
                missing_fields.append(f"f1_fcn_underlying_ticker(slot={index})")
            if slot["initial_value"] is None:
                missing_fields.append(f"f1_fcn_underlying_initial_value(slot={index})")
            if slot["barrier_ratio"] is None and slot["barrier_value"] is None:
                missing_fields.append(f"f1_fcn_underlying_barrier_ratio(slot={index})")
        return {
            "note_id": note_id,
            "parse_run_id": parse_run_id or None,
            "definition_version": str(metadata.get("definition_version") or STRUCTURED_NOTE_DEFINITION_VERSION),
            "f1_definition_ids": structured_note_definition_ids("F1"),
            "static_terms": static_terms,
            "note": note,
            "underlyings": underlyings,
            "underlying_count": len(underlying_slots),
            "underlying_slots": underlying_slots,
            "missing_fields": sorted(set(missing_fields)),
            "cache_status": "MISS",
            "parser_version": parser_version,
            "parser_rule_hash": parser_rule_hash,
        }

    def get_structured_note_definition_bindings(self, note_id: str) -> dict[str, Any]:
        bundle = self.get_structured_note_f1_static_bundle(note_id)
        note = dict(bundle.get("note") or {})
        underlyings = [dict(item) for item in bundle.get("underlying_slots") or []]
        f2_contract = compile_fcn_f2_contract(note, underlyings)
        f2_ids = structured_note_definition_ids("F2")
        blocked = list(f2_ids) if bundle.get("missing_fields") else []
        calculable = [] if blocked else list(f2_ids)
        return {
            "note_id": str(bundle.get("note_id") or note_id),
            "definition_version": str(bundle.get("definition_version") or STRUCTURED_NOTE_DEFINITION_VERSION),
            "f1_bundle": {
                key: value
                for key, value in bundle.items()
                if key not in {"note", "underlyings", "cache_load_count"}
            },
            "f2_contract": f2_contract,
            "calculable_f2_definition_ids": calculable,
            "blocked_f2_definition_ids": blocked,
            "summary": {
                "f1_static_cache_status": bundle.get("cache_status"),
                "cache_load_count": bundle.get("cache_load_count"),
                "underlying_count": bundle.get("underlying_count"),
                "missing_field_count": len(bundle.get("missing_fields") or []),
                "definition_version": bundle.get("definition_version"),
                "source_factor_ids": f2_contract.get("source_factor_ids"),
            },
        }

    def get_structured_note_fcn_runtime_health(self) -> dict[str, Any]:
        cache_stats = self.get_structured_note_f1_cache_stats()
        table_probe = self.storage.fetch_one("SELECT COUNT(*) AS count FROM structured_note_terms")
        latest = self.storage.fetch_one(
            """
            SELECT *
            FROM structured_note_replay_preflight_runs
            ORDER BY updated_at DESC, run_id DESC
            LIMIT 1
            """
        )
        service_ready = table_probe is not None
        return {
            "status": "OK" if service_ready else "RUNTIME_NOT_READY",
            "runtime_ready": bool(service_ready),
            "service_ready": bool(service_ready),
            "cache_stats": cache_stats,
            "latest_preflight_run": self._decode_structured_note_preflight_run_summary(latest) if latest else None,
            "summary": {
                "note_instance_count": int((table_probe or {}).get("count") or 0),
                "runtime_check": "service_storage_ready" if service_ready else "structured_note_terms_unavailable",
                "quickstart_preflight": "external_script_required_for_live_acceptance",
                "publish_boundary": "sandbox -> quarantine -> publish",
            },
        }

    def preflight_structured_note_fcn_replay(self, request: Any | None = None) -> dict[str, Any]:
        payload = _as_mapping(request)
        now = iso_now()
        cache_stats_before = self.get_structured_note_f1_cache_stats()
        note_ids, selection_warnings = self._structured_note_preflight_note_ids(payload)
        dataset_snapshot_id = str(payload.get("dataset_snapshot_id") or DATASET_PRICE_SNAPSHOT_ID)
        replay_mode = str(payload.get("replay_mode") or "sandbox").lower()
        price_proxies = dict(payload.get("price_proxies") or {}) if isinstance(payload.get("price_proxies"), Mapping) else {}
        raw_initial_value_proxy_mode = str(payload.get("initial_value_proxy_mode") or "none").strip()
        initial_value_proxy_mode = (
            "SANDBOX_ONLY_FIRST_PRICE"
            if raw_initial_value_proxy_mode.upper() == "SANDBOX_ONLY_FIRST_PRICE"
            else "none"
        )
        run_id = "fcn_preflight_" + hashlib.sha256(
            f"{','.join(note_ids)}|{dataset_snapshot_id}|{replay_mode}|{now}|{uuid4().hex}".encode("utf-8")
        ).hexdigest()[:16]
        note_results: list[dict[str, Any]] = []
        slot_count_histogram: dict[int, int] = {}
        elapsed_ms_per_note: list[float] = []
        replay_point_count = 0
        blocked_point_count = 0
        data_source_blocked_count = 0
        initial_value_proxy_count = 0
        initial_value_proxy_note_count = 0
        warnings = list(selection_warnings)
        started = monotonic()
        status = "OK"
        if not note_ids:
            status = "DATA_SOURCE_BLOCKED"
            warnings.append("no_structured_note_instances_selected")
        for note_id in note_ids:
            note_started = monotonic()
            try:
                bundle = self.get_structured_note_f1_static_bundle(note_id)
                result = self._preflight_one_structured_note_fcn_replay(
                    bundle,
                    dataset_snapshot_id=dataset_snapshot_id,
                    replay_mode=replay_mode,
                    price_proxies=price_proxies,
                    initial_value_proxy_mode=initial_value_proxy_mode,
                    start_date=payload.get("start_date"),
                    end_date=payload.get("end_date"),
                )
            except Exception as exc:
                result = {
                    "note_id": note_id,
                    "parse_run_id": None,
                    "status": "DATA_SOURCE_BLOCKED",
                    "underlying_count": 0,
                    "replay_point_count": 0,
                    "ok_point_count": 0,
                    "blocked_point_count": 0,
                    "missing_symbols": [],
                    "missing_initial_value_symbols": [],
                    "blocker_code": f"preflight_exception: {exc}",
                    "initial_value_proxy_mode": initial_value_proxy_mode,
                    "initial_value_proxy_count": 0,
                    "initial_value_proxy_symbols": [],
                    "initial_value_proxy_evidence": [],
                }
            elapsed_ms = (monotonic() - note_started) * 1000
            result["elapsed_ms"] = elapsed_ms
            note_results.append(result)
            elapsed_ms_per_note.append(elapsed_ms)
            underlying_count = int(result.get("underlying_count") or 0)
            slot_count_histogram[underlying_count] = slot_count_histogram.get(underlying_count, 0) + 1
            replay_point_count += int(result.get("replay_point_count") or 0)
            blocked_point_count += int(result.get("blocked_point_count") or 0)
            note_proxy_count = int(result.get("initial_value_proxy_count") or 0)
            initial_value_proxy_count += note_proxy_count
            if note_proxy_count:
                initial_value_proxy_note_count += 1
            if result.get("status") == "DATA_SOURCE_BLOCKED":
                data_source_blocked_count += 1
            current_cache_stats = self.get_structured_note_f1_cache_stats()
            if current_cache_stats.get("approx_memory_bytes", 0) >= current_cache_stats.get("warn_memory_bytes", 0):
                status = "MEMORY_GUARDRAIL_BLOCKED"
                warnings.append("f1_static_cache_memory_guardrail_exceeded")
                break
        elapsed_seconds = max(0.0, monotonic() - started)
        cache_stats_after = self.get_structured_note_f1_cache_stats()
        if status != "MEMORY_GUARDRAIL_BLOCKED":
            if data_source_blocked_count:
                status = "DATA_SOURCE_BLOCKED"
            elif warnings:
                status = "WARN"
            elif note_results:
                status = "OK"
        price_missing_ratio = (blocked_point_count / replay_point_count) if replay_point_count else (
            1.0 if data_source_blocked_count else 0.0
        )
        if initial_value_proxy_count and "SANDBOX_ONLY_INITIAL_VALUE_PROXY_USED" not in warnings:
            warnings.append("SANDBOX_ONLY_INITIAL_VALUE_PROXY_USED")
            if status == "OK":
                status = "WARN"
        summary = {
            "warnings": warnings,
            "dataset_snapshot_id": dataset_snapshot_id,
            "replay_mode": replay_mode,
            "initial_value_proxy_mode": initial_value_proxy_mode,
            "initial_value_proxy_count": initial_value_proxy_count,
            "initial_value_proxy_note_count": initial_value_proxy_note_count,
            "sandbox_initial_value_proxy_used": bool(initial_value_proxy_count),
            "sample_limit": int(payload.get("sample_limit") or 10),
            "max_notes": int(payload.get("max_notes") or 100),
            "publish_boundary": "sandbox -> quarantine -> publish",
            "preflight_only": True,
            "slot_count_histogram": dict(sorted(slot_count_histogram.items())),
        }
        response = {
            "run_id": run_id,
            "status": status,
            "note_count": len(note_results),
            "replay_point_count": replay_point_count,
            "points_per_second": (replay_point_count / elapsed_seconds) if elapsed_seconds > 0 else 0.0,
            "p50_ms_per_note": _percentile(elapsed_ms_per_note, 50),
            "p95_ms_per_note": _percentile(elapsed_ms_per_note, 95),
            "price_missing_ratio": price_missing_ratio,
            "data_source_blocked_count": data_source_blocked_count,
            "max_underlying_count": max(slot_count_histogram) if slot_count_histogram else 0,
            "slot_count_histogram": dict(sorted(slot_count_histogram.items())),
            "cache_stats_before": cache_stats_before,
            "cache_stats_after": cache_stats_after,
            "note_results": note_results,
            "summary": summary,
            "created_at": now,
            "updated_at": now,
        }
        self.storage.insert_json_row(
            "structured_note_replay_preflight_runs",
            {
                "id": run_id,
                "run_id": run_id,
                "status": status,
                "request_json": dumps(dict(payload)),
                "note_results_json": dumps(note_results),
                "summary_json": dumps(
                    {
                        **summary,
                        "note_count": response["note_count"],
                        "replay_point_count": replay_point_count,
                        "points_per_second": response["points_per_second"],
                        "p50_ms_per_note": response["p50_ms_per_note"],
                        "p95_ms_per_note": response["p95_ms_per_note"],
                        "price_missing_ratio": price_missing_ratio,
                        "data_source_blocked_count": data_source_blocked_count,
                        "max_underlying_count": response["max_underlying_count"],
                        "cache_stats_before": cache_stats_before,
                        "cache_stats_after": cache_stats_after,
                    }
                ),
                "created_at": now,
                "updated_at": now,
            },
        )
        return response

    def get_structured_note_fcn_replay_preflight_run(self, run_id: str) -> dict[str, Any]:
        row = self.storage.fetch_one("SELECT * FROM structured_note_replay_preflight_runs WHERE run_id = ?", (run_id,))
        if not row:
            raise ValueError(f"Structured note replay preflight run not found: {run_id}")
        return self._decode_structured_note_preflight_run(row)

    def _decode_structured_note_preflight_run_summary(self, row: Mapping[str, Any]) -> dict[str, Any]:
        summary = loads(row.get("summary_json"), {})
        return {
            "run_id": str(row.get("run_id") or ""),
            "status": str(row.get("status") or "RUNTIME_NOT_READY"),
            "note_count": int((summary if isinstance(summary, Mapping) else {}).get("note_count") or 0),
            "replay_point_count": int((summary if isinstance(summary, Mapping) else {}).get("replay_point_count") or 0),
            "updated_at": row.get("updated_at"),
        }

    def _decode_structured_note_preflight_run(self, row: Mapping[str, Any]) -> dict[str, Any]:
        summary = loads(row.get("summary_json"), {})
        if not isinstance(summary, Mapping):
            summary = {}
        slot_histogram = {
            int(key): int(value)
            for key, value in dict(summary.get("slot_count_histogram") or {}).items()
        }
        return {
            "run_id": str(row.get("run_id") or ""),
            "status": str(row.get("status") or "RUNTIME_NOT_READY"),
            "note_count": int(summary.get("note_count") or 0),
            "replay_point_count": int(summary.get("replay_point_count") or 0),
            "points_per_second": float(summary.get("points_per_second") or 0.0),
            "p50_ms_per_note": summary.get("p50_ms_per_note"),
            "p95_ms_per_note": summary.get("p95_ms_per_note"),
            "price_missing_ratio": float(summary.get("price_missing_ratio") or 0.0),
            "data_source_blocked_count": int(summary.get("data_source_blocked_count") or 0),
            "max_underlying_count": int(summary.get("max_underlying_count") or 0),
            "slot_count_histogram": slot_histogram,
            "cache_stats_before": summary.get("cache_stats_before") if isinstance(summary.get("cache_stats_before"), Mapping) else {},
            "cache_stats_after": summary.get("cache_stats_after") if isinstance(summary.get("cache_stats_after"), Mapping) else {},
            "note_results": loads(row.get("note_results_json"), []),
            "summary": dict(summary),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
        }

    def _structured_note_preflight_note_ids(self, payload: Mapping[str, Any]) -> tuple[list[str], list[str]]:
        raw_note_ids = payload.get("note_ids") if isinstance(payload.get("note_ids"), list) else []
        note_ids = [str(item).strip() for item in raw_note_ids if str(item).strip()]
        warnings: list[str] = []
        if not note_ids and (payload.get("manifest_id") or payload.get("manifest_path")):
            manifest, _manifest_path = self._load_structured_note_pilot_manifest(payload)
            note_ids = [
                str(entry.get("note_id") or "").strip()
                for entry in manifest.get("entries") or []
                if isinstance(entry, Mapping) and str(entry.get("note_id") or "").strip()
            ]
        if not note_ids:
            sample_limit = max(1, min(10_000, int(payload.get("sample_limit") or 10)))
            rows = self.storage.fetch_all(
                """
                SELECT note_id
                FROM structured_note_terms
                ORDER BY updated_at DESC, note_id DESC
                LIMIT ?
                """,
                (sample_limit,),
            )
            note_ids = [str(row.get("note_id") or "") for row in rows if row.get("note_id")]
        seen: set[str] = set()
        deduped: list[str] = []
        for note_id in note_ids:
            if note_id and note_id not in seen:
                deduped.append(note_id)
                seen.add(note_id)
        sample_limit = max(1, min(10_000, int(payload.get("sample_limit") or len(deduped) or 10)))
        max_notes = max(1, min(10_000, int(payload.get("max_notes") or 100)))
        effective_limit = min(sample_limit, max_notes)
        if len(deduped) > effective_limit:
            warnings.append(f"sample_truncated_to_{effective_limit}_notes")
        return deduped[:effective_limit], warnings

    def _preflight_one_structured_note_fcn_replay(
        self,
        bundle: Mapping[str, Any],
        *,
        dataset_snapshot_id: str,
        replay_mode: str,
        price_proxies: Mapping[str, Any],
        initial_value_proxy_mode: str,
        start_date: Any,
        end_date: Any,
    ) -> dict[str, Any]:
        note = dict(bundle.get("note") or {})
        underlyings = [dict(item) for item in bundle.get("underlying_slots") or [] if isinstance(item, Mapping)]
        symbol_map = self._structured_note_price_symbol_map(underlyings, price_proxies, replay_mode)
        rows_by_symbol = self.market_data_repository.load_dataset_price_bars(
            dataset_snapshot_id,
            sorted(set(symbol_map.values())),
            start_date=start_date or note.get("pricing_date"),
            end_date=end_date or note.get("maturity_date"),
            include_metadata=False,
        )
        logical_rows = {
            logical: list(rows_by_symbol.get(actual) or [])
            for logical, actual in symbol_map.items()
        }
        missing_symbols = [ticker for ticker, rows in logical_rows.items() if not rows]
        underlyings, initial_value_proxy_evidence = self._apply_structured_note_initial_value_proxy(
            underlyings,
            logical_rows,
            symbol_map,
            initial_value_proxy_mode=initial_value_proxy_mode,
            replay_mode=replay_mode,
        )
        initial_value_proxy_symbols = [
            str(item.get("ticker") or "")
            for item in initial_value_proxy_evidence
            if str(item.get("ticker") or "")
        ]
        missing_initial_value_symbols = [
            str(item.get("ticker") or "").upper()
            for item in underlyings
            if str(item.get("ticker") or "").strip()
            and (
                (initial := _coerce_float(item.get("initial_value") or item.get("strike_value"), None)) is None
                or initial <= 0
            )
        ]
        observation_dates = self._structured_note_observation_dates(
            logical_rows,
            str(note.get("observation_frequency") or note.get("coupon_frequency") or "Monthly"),
        )
        price_by_ticker_date = {
            ticker: {str(row.get("date")): _coerce_float(row.get("adj_close") or row.get("close"), None) for row in rows}
            for ticker, rows in logical_rows.items()
        }
        history: list[float] = []
        ok_count = 0
        blocked_count = 0
        for note_date in observation_dates:
            current_prices = {
                ticker: price_by_date.get(note_date)
                for ticker, price_by_date in price_by_ticker_date.items()
                if price_by_date.get(note_date) is not None
            }
            signal = evaluate_fcn_note_signals(
                note,
                underlyings,
                current_prices,
                history_worst_performance=history[-21:],
            )
            if signal.get("worst_performance") is not None:
                history.append(float(signal["worst_performance"]))
            if signal.get("status") == "OK":
                ok_count += 1
            else:
                blocked_count += 1
        if not observation_dates:
            blocked_count = 1
        status = "OK" if observation_dates and ok_count == len(observation_dates) and not missing_symbols else "DATA_SOURCE_BLOCKED"
        if status == "OK":
            blocker_code = None
        elif missing_symbols:
            blocker_code = "missing_price_history"
        elif missing_initial_value_symbols:
            blocker_code = "missing_initial_value"
        else:
            blocker_code = "missing_observation_dates"
        return {
            "note_id": str(bundle.get("note_id") or note.get("note_id") or ""),
            "parse_run_id": bundle.get("parse_run_id"),
            "status": status,
            "underlying_count": int(bundle.get("underlying_count") or len(underlyings)),
            "replay_point_count": len(observation_dates),
            "ok_point_count": ok_count,
            "blocked_point_count": blocked_count,
            "missing_symbols": missing_symbols,
            "missing_initial_value_symbols": missing_initial_value_symbols,
            "blocker_code": blocker_code,
            "initial_value_proxy_mode": initial_value_proxy_mode,
            "initial_value_proxy_count": len(initial_value_proxy_evidence),
            "initial_value_proxy_symbols": initial_value_proxy_symbols,
            "initial_value_proxy_evidence": initial_value_proxy_evidence,
        }

    @staticmethod
    def _apply_structured_note_initial_value_proxy(
        underlyings: Sequence[Mapping[str, Any]],
        logical_rows: Mapping[str, Sequence[Mapping[str, Any]]],
        symbol_map: Mapping[str, str],
        *,
        initial_value_proxy_mode: str,
        replay_mode: str,
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        copied = [dict(item) for item in underlyings]
        if replay_mode != "sandbox" or initial_value_proxy_mode != "SANDBOX_ONLY_FIRST_PRICE":
            return copied, []

        evidence: list[dict[str, Any]] = []
        for underlying in copied:
            ticker = str(underlying.get("ticker") or "").upper()
            if not ticker:
                continue
            current_initial = _coerce_float(underlying.get("initial_value") or underlying.get("strike_value"), None)
            if current_initial is not None and current_initial > 0:
                continue
            for row in logical_rows.get(ticker) or []:
                first_price = _coerce_float(row.get("adj_close") or row.get("close"), None)
                if first_price is None or first_price <= 0:
                    continue
                underlying["initial_value"] = first_price
                evidence.append(
                    {
                        "ticker": ticker,
                        "price_proxy_symbol": str(symbol_map.get(ticker) or ticker).upper(),
                        "initial_value": first_price,
                        "date": str(row.get("date") or ""),
                        "mode": "SANDBOX_ONLY_FIRST_PRICE",
                        "source": "dataset_price_bars.adj_close",
                    }
                )
                break
        return copied, evidence

    @staticmethod
    def _sec_424b2_evidence_anchors(note: Mapping[str, Any], underlyings: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
        anchors: list[dict[str, Any]] = []
        def collect_anchor(raw_anchor: Mapping[str, Any], *, default_field_path: str) -> None:
            if raw_anchor.get("field_path") or raw_anchor.get("text"):
                anchors.append({"field_path": default_field_path, **dict(raw_anchor)})
            for key, value in raw_anchor.items():
                if isinstance(value, Mapping) and (value.get("field_path") or value.get("text")):
                    anchors.append({"field_path": f"{default_field_path}.{key}", **dict(value)})

        note_evidence = note.get("evidence") if isinstance(note.get("evidence"), Mapping) else {}
        for field_path, raw_anchor in note_evidence.items():
            if not isinstance(raw_anchor, Mapping):
                continue
            collect_anchor(raw_anchor, default_field_path=str(field_path))
        for index, underlying in enumerate(underlyings):
            raw_anchor = underlying.get("evidence") if isinstance(underlying.get("evidence"), Mapping) else {}
            if not raw_anchor:
                continue
            ticker = str(underlying.get("ticker") or index)
            collect_anchor(raw_anchor, default_field_path=f"underlyings.{ticker}")
        return anchors

    def get_sec_424b2_parse_run(self, run_id: str) -> dict[str, Any]:
        row = self.storage.fetch_one("SELECT * FROM sec_424b2_parse_runs WHERE run_id = ?", (run_id,))
        if not row:
            raise ValueError(f"SEC 424B2 parse run not found: {run_id}")
        note_row = self.storage.fetch_one("SELECT * FROM structured_note_terms WHERE parse_run_id = ?", (run_id,))
        if not note_row:
            raise ValueError(f"Structured note terms not found for parse run: {run_id}")
        note_id = str(note_row.get("note_id") or "")
        underlying_rows = self.storage.fetch_all(
            "SELECT * FROM structured_note_underlyings WHERE note_id = ? ORDER BY ticker",
            (note_id,),
        )
        underlyings = self._sort_structured_note_underlyings(
            [self._decode_structured_note_underlying(row) for row in underlying_rows]
        )
        note = self._decode_structured_note_terms(note_row, underlyings)
        f2_contract = compile_fcn_f2_contract(note, underlyings)
        warnings = loads(row.get("warnings_json"), [])
        status = str(row.get("status") or note.get("review_status") or "REVIEW_REQUIRED")
        return {
            "status": status,
            "warnings": warnings if isinstance(warnings, list) else [],
            "llm_used": bool(row.get("llm_used")),
            "parse_run": {
                "run_id": str(row.get("run_id") or ""),
                "accession_number": str(row.get("accession_number") or ""),
                "issuer_cik": str(row.get("issuer_cik") or ""),
                "source_url": str(row.get("source_url") or ""),
                "primary_document_url": str(row.get("primary_document_url") or ""),
                "raw_html_sha256": str(row.get("raw_html_sha256") or ""),
                "normalized_text_hash": str(row.get("normalized_text_hash") or ""),
                "table_signature_hash": str(row.get("table_signature_hash") or ""),
                "parser_rule_hash": str(row.get("parser_rule_hash") or ""),
                "parse_result_hash": str(row.get("parse_result_hash") or ""),
                "parser_version": str(row.get("parser_version") or ""),
                "status": status,
                "warnings": warnings if isinstance(warnings, list) else [],
                "llm_used": bool(row.get("llm_used")),
                "created_at": row.get("created_at"),
                "updated_at": row.get("updated_at"),
            },
            "note": note,
            "underlyings": underlyings,
            "f2_contract": f2_contract,
        }

    @staticmethod
    def _decode_structured_note_terms(
        row: Mapping[str, Any],
        underlyings: Sequence[Mapping[str, Any]],
    ) -> dict[str, Any]:
        metadata = loads(row.get("metadata_json"), {})
        evidence = loads(row.get("evidence_json"), {})
        note_id = str(row.get("note_id") or "")
        return {
            "note_id": note_id,
            "factor_id": str(metadata.get("factor_id") or "f1_fcn_note_terms"),
            "legacy_factor_id": str(metadata.get("legacy_factor_id") or note_id),
            "source_url": str(row.get("source_url") or ""),
            "issuer_cik": str(row.get("issuer_cik") or ""),
            "accession_number": str(row.get("accession_number") or ""),
            "primary_document": "",
            "cusip": row.get("cusip"),
            "pricing_date": row.get("pricing_date"),
            "issue_date": row.get("issue_date"),
            "maturity_date": row.get("maturity_date"),
            "coupon_rate_annual": row.get("coupon_rate_annual"),
            "coupon_frequency": str(row.get("coupon_frequency") or ""),
            "observation_frequency": str(row.get("observation_frequency") or ""),
            "autocall_frequency": str(row.get("autocall_frequency") or ""),
            "memory_feature": bool(row.get("memory_feature")),
            "payoff_type": str(row.get("payoff_type") or "REVIEW_REQUIRED"),
            "review_status": str(row.get("review_status") or "REVIEW_REQUIRED"),
            "underlying_tickers": [str(item.get("ticker") or "") for item in underlyings if item.get("ticker")],
            "underlying_count": len([item for item in underlyings if item.get("ticker")]),
            "barrier_percentage": _min_present_float(item.get("barrier_ratio") for item in underlyings),
            "definition_version": str(metadata.get("definition_version") or STRUCTURED_NOTE_DEFINITION_VERSION),
            "metadata": metadata if isinstance(metadata, dict) else {},
            "evidence": evidence if isinstance(evidence, dict) else {},
        }

    @staticmethod
    def _decode_structured_note_underlying(row: Mapping[str, Any]) -> dict[str, Any]:
        evidence = loads(row.get("evidence_json"), {})
        metadata = loads(row.get("metadata_json"), {})
        underlying_index = None
        if isinstance(metadata, dict) and metadata.get("underlying_index") is not None:
            try:
                underlying_index = int(metadata.get("underlying_index"))
            except (TypeError, ValueError):
                underlying_index = None
        return {
            "note_id": str(row.get("note_id") or ""),
            "underlying_index": underlying_index,
            "ticker": str(row.get("ticker") or ""),
            "initial_value": row.get("initial_value"),
            "strike_value": row.get("strike_value"),
            "barrier_ratio": row.get("barrier_ratio"),
            "barrier_value": row.get("barrier_value"),
            "trigger_ratio": row.get("trigger_ratio"),
            "trigger_value": row.get("trigger_value"),
            "exchange": str(row.get("exchange") or ""),
            "evidence": evidence if isinstance(evidence, dict) else {},
            "metadata": metadata if isinstance(metadata, dict) else {},
        }

    @staticmethod
    def _sort_structured_note_underlyings(underlyings: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
        def sort_key(item: Mapping[str, Any]) -> tuple[int, str]:
            metadata = item.get("metadata") if isinstance(item.get("metadata"), Mapping) else {}
            raw_index = item.get("underlying_index")
            if raw_index is None:
                raw_index = metadata.get("underlying_index") if isinstance(metadata, Mapping) else None
            try:
                return int(raw_index), str(item.get("ticker") or "")
            except (TypeError, ValueError):
                return 1_000_000, str(item.get("ticker") or "")

        ordered = [dict(item) for item in underlyings]
        ordered.sort(key=sort_key)
        for index, item in enumerate(ordered):
            item["underlying_index"] = index
            metadata = dict(item.get("metadata") or {}) if isinstance(item.get("metadata"), Mapping) else {}
            metadata["underlying_index"] = index
            item["metadata"] = metadata
        return ordered

    def discover_sec_424b2_pilot_preview(self, request: Any | None = None) -> dict[str, Any]:
        payload = _as_mapping(request)
        issuer_cik = str(payload.get("issuer_cik") or "0001665650").strip()
        scan_limit = max(1, min(200, int(payload.get("scan_limit") or 100)))
        pilot_limit = max(5, min(10, int(payload.get("pilot_limit") or 10)))
        parser_options = payload.get("parser_options") if isinstance(payload.get("parser_options"), Mapping) else {}
        provider = SecEdgarProvider()
        filings = provider.fetch_424b2_filings_by_cik(issuer_cik, limit=scan_limit)
        entries: list[dict[str, Any]] = []
        warnings: list[str] = []
        for filing in filings[:scan_limit]:
            source_url = str(filing.get("primary_document_url") or filing.get("source_url") or "")
            accession = str(filing.get("accession_number") or "")
            primary_document = str(filing.get("primary_document") or "")
            if not source_url:
                warnings.append(f"{accession or 'unknown'}: missing_primary_document_url")
                continue
            try:
                html_text = provider.fetch_archive_document(source_url)
                parsed = parse_sec_424b2_structured_note(
                    html_text,
                    source_url=source_url,
                    issuer_cik=issuer_cik,
                    accession_number=accession,
                    primary_document=primary_document,
                    parser_options=parser_options,
                )
                entries.append(self._sec_424b2_pilot_manifest_entry(parsed, filing=filing))
            except Exception as exc:
                warnings.append(f"{accession or source_url}: {exc}")
                entries.append(
                    {
                        "accession_number": accession,
                        "source_url": source_url,
                        "primary_document": primary_document,
                        "issuer_cik": str(issuer_cik).zfill(10) if str(issuer_cik).isdigit() else issuer_cik,
                        "status": "FAILED",
                        "warnings": [str(exc)],
                        "feature_bucket": "fetch_or_parse_failed",
                    }
                )
        selected = self._select_sec_424b2_pilot_entries(entries, pilot_limit)
        manifest_id = "sec424b2_pilot_" + hashlib.sha256(
            dumps([entry.get("accession_number") or entry.get("source_url") for entry in selected]).encode("utf-8")
        ).hexdigest()[:12]
        summary = self._sec_424b2_pilot_summary(selected, source_count=len(entries))
        manifest_hash = self._stable_json_hash({"manifest_id": manifest_id, "entries": selected})
        return {
            "manifest_id": manifest_id,
            "issuer_cik": str(issuer_cik).zfill(10) if str(issuer_cik).isdigit() else issuer_cik,
            "pilot_limit": pilot_limit,
            "scan_limit": scan_limit,
            "selected_count": len(selected),
            "blocked_count": sum(1 for entry in entries if entry.get("status") != "PARSED"),
            "last_validated_at": None,
            "last_replay_run_id": None,
            "validation_status": "PREVIEW",
            "manifest_hash": manifest_hash,
            "parser_version": SEC_424B2_PARSER_VERSION,
            "parser_rule_hash": SEC_424B2_PARSER_RULE_HASH,
            "warnings": warnings,
            "entries": selected,
            "summary": {**summary, "manifest_hash": manifest_hash},
        }

    def ingest_sec_424b2_pilot(self, request: Any | None = None) -> dict[str, Any]:
        payload = _as_mapping(request)
        manifest_path = str(
            payload.get("manifest_path")
            or os.getenv("GRIT_SEC_424B2_PILOT_MANIFEST")
            or ".tmp/sec-424b2-pilot/jpm_manifest.json"
        )
        entries = [dict(item) for item in payload.get("entries") or [] if isinstance(item, Mapping)]
        warnings: list[str] = []
        if not entries:
            preview = self.discover_sec_424b2_pilot_preview(payload)
            entries = [dict(item) for item in preview.get("entries") or [] if isinstance(item, Mapping)]
            warnings.extend([str(item) for item in preview.get("warnings") or []])
        pilot_limit = max(5, min(10, int(payload.get("pilot_limit") or len(entries) or 10)))
        entries = self._select_sec_424b2_pilot_entries(entries, pilot_limit)
        parse_runs: list[dict[str, Any]] = []
        provider = SecEdgarProvider()
        for entry in entries:
            if str(entry.get("status") or "") == "FAILED":
                continue
            try:
                html_text = str(entry.get("html") or "")
                source_url = str(entry.get("source_url") or "")
                if not html_text:
                    html_text = provider.fetch_archive_document(source_url)
                parsed = self.preview_sec_424b2_structured_note(
                    {
                        "source_url": source_url,
                        "issuer_cik": entry.get("issuer_cik") or payload.get("issuer_cik") or "0001665650",
                        "accession_number": entry.get("accession_number"),
                        "primary_document": entry.get("primary_document"),
                        "html": html_text,
                        "persist": bool(payload.get("persist", True)),
                        "parser_options": payload.get("parser_options") if isinstance(payload.get("parser_options"), Mapping) else {},
                    }
                )
                parse_runs.append(parsed)
                entry["last_parse_run_id"] = str(parsed.get("parse_run", {}).get("run_id") or "")
                entry["last_status"] = str(parsed.get("status") or "REVIEW_REQUIRED")
                entry["last_validated_at"] = iso_now()
                if parsed.get("note", {}).get("note_id"):
                    entry["note_id"] = str(parsed.get("note", {}).get("note_id") or "")
            except Exception as exc:
                warnings.append(f"{entry.get('accession_number') or entry.get('source_url')}: {exc}")
                entry["last_status"] = "DATA_SOURCE_BLOCKED"
                entry["last_validated_at"] = iso_now()
        manifest_id = "sec424b2_pilot_" + hashlib.sha256(
            dumps([entry.get("accession_number") or entry.get("source_url") for entry in entries]).encode("utf-8")
        ).hexdigest()[:12]
        now = iso_now()
        validation_status = "COMPLETED" if parse_runs else "DATA_SOURCE_BLOCKED"
        manifest_hash = self._stable_json_hash({"manifest_id": manifest_id, "entries": entries})
        summary = {
            **self._sec_424b2_pilot_summary(entries, source_count=len(entries)),
            "manifest_hash": manifest_hash,
            "validation_status": validation_status,
            "last_validated_at": now,
        }
        manifest = {
            "manifest_id": manifest_id,
            "issuer_cik": str(payload.get("issuer_cik") or (entries[0].get("issuer_cik") if entries else "") or "0001665650"),
            "pilot_limit": pilot_limit,
            "scan_limit": int(payload.get("scan_limit") or len(entries) or 0),
            "entries": entries,
            "parse_run_ids": [run.get("parse_run", {}).get("run_id") for run in parse_runs],
            "last_validated_at": now,
            "last_replay_run_id": None,
            "validation_status": validation_status,
            "manifest_hash": manifest_hash,
            "parser_version": SEC_424B2_PARSER_VERSION,
            "parser_rule_hash": SEC_424B2_PARSER_RULE_HASH,
            "warnings": warnings,
            "created_at": now,
        }
        path = Path(manifest_path)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2, sort_keys=True), encoding="utf-8")
        self.storage.insert_json_row(
            "structured_note_pilot_manifests",
            {
                "id": manifest_id,
                "manifest_id": manifest_id,
                "issuer_cik": str(manifest.get("issuer_cik") or ""),
                "manifest_path": str(path),
                "pilot_limit": pilot_limit,
                "scan_limit": int(manifest.get("scan_limit") or 0),
                "entries_json": dumps(entries),
                "summary_json": dumps(summary),
                "created_at": now,
                "updated_at": now,
            },
        )
        return {
            "manifest_id": manifest_id,
            "manifest_path": str(path),
            "status": "COMPLETED" if parse_runs else "DATA_SOURCE_BLOCKED",
            "selected_count": len(entries),
            "parse_run_count": len(parse_runs),
            "last_validated_at": now,
            "last_replay_run_id": None,
            "validation_status": validation_status,
            "manifest_hash": manifest_hash,
            "parser_version": SEC_424B2_PARSER_VERSION,
            "parser_rule_hash": SEC_424B2_PARSER_RULE_HASH,
            "entries": entries,
            "parse_runs": parse_runs,
            "warnings": warnings,
            "summary": summary,
        }

    def list_sec_424b2_reparse_candidates(
        self,
        *,
        current_parser_version: str | None = None,
        current_rule_hash: str | None = None,
    ) -> dict[str, Any]:
        parser_version = str(current_parser_version or SEC_424B2_PARSER_VERSION)
        rule_hash = str(current_rule_hash or SEC_424B2_PARSER_RULE_HASH)
        rows = self.storage.fetch_all("SELECT * FROM sec_424b2_parse_runs ORDER BY updated_at DESC, run_id DESC")
        hashes_by_accession: dict[str, set[str]] = {}
        for row in rows:
            accession = str(row.get("accession_number") or row.get("source_url") or row.get("run_id") or "")
            hashes_by_accession.setdefault(accession, set()).add(str(row.get("raw_html_sha256") or ""))
        candidates: list[dict[str, Any]] = []
        for row in rows:
            warnings = loads(row.get("warnings_json"), [])
            warning_items = [str(item) for item in warnings] if isinstance(warnings, list) else []
            reasons: list[str] = []
            run_id = str(row.get("run_id") or "")
            note_row = self.storage.fetch_one(
                "SELECT note_id FROM structured_note_terms WHERE parse_run_id = ?",
                (run_id,),
            )
            note_id = str((note_row or {}).get("note_id") or "")
            missing_initial_value_count = 0
            if note_id:
                missing_row = self.storage.fetch_one(
                    """
                    SELECT COUNT(*) AS count
                    FROM structured_note_underlyings
                    WHERE note_id = ?
                      AND initial_value IS NULL
                      AND strike_value IS NULL
                    """,
                    (note_id,),
                )
                missing_initial_value_count = int((missing_row or {}).get("count") or 0)
            if str(row.get("parser_version") or "") != parser_version:
                reasons.append("PARSER_CHANGED")
            if str(row.get("parser_rule_hash") or "") != rule_hash:
                reasons.append("RULEPACK_CHANGED")
            accession = str(row.get("accession_number") or row.get("source_url") or row.get("run_id") or "")
            if len({item for item in hashes_by_accession.get(accession, set()) if item}) > 1:
                reasons.append("HTML_CHANGED")
            if str(row.get("status") or "") != "PARSED":
                reasons.append("LOW_CONFIDENCE")
            if any("unsupported" in item or "payoff" in item for item in warning_items):
                reasons.append("UNSUPPORTED_PAYOFF")
            if any("DATA_SOURCE_BLOCKED" in item or "price" in item.lower() for item in warning_items):
                reasons.append("DATA_SOURCE_BLOCKED")
            if missing_initial_value_count:
                reasons.append("INITIAL_VALUE_MISSING")
                warning_items.append(f"initial_value_missing:{missing_initial_value_count}")
            if not reasons:
                continue
            candidates.append(
                {
                    "run_id": run_id,
                    "note_id": note_id,
                    "accession_number": str(row.get("accession_number") or ""),
                    "issuer_cik": str(row.get("issuer_cik") or ""),
                    "source_url": str(row.get("source_url") or ""),
                    "parser_version": str(row.get("parser_version") or ""),
                    "parser_rule_hash": str(row.get("parser_rule_hash") or ""),
                    "raw_html_sha256": str(row.get("raw_html_sha256") or ""),
                    "parse_result_hash": str(row.get("parse_result_hash") or ""),
                    "status": str(row.get("status") or "REVIEW_REQUIRED"),
                    "reasons": sorted(set(reasons)),
                    "warnings": warning_items,
                    "missing_initial_value_count": missing_initial_value_count,
                }
            )
        reason_counts: dict[str, int] = {}
        for candidate in candidates:
            for reason in candidate.get("reasons") or []:
                reason_counts[str(reason)] = reason_counts.get(str(reason), 0) + 1
        return {
            "candidates": candidates,
            "summary": {
                "candidate_count": len(candidates),
                "reason_counts": reason_counts,
                "current_parser_version": parser_version,
                "current_rule_hash": rule_hash,
            },
        }

    def preview_sec_424b2_reparse_job(self, request: Any | None = None) -> dict[str, Any]:
        return self._build_sec_424b2_reparse_job(request, persist=False)

    def create_sec_424b2_reparse_job(self, request: Any | None = None) -> dict[str, Any]:
        return self._build_sec_424b2_reparse_job(request, persist=True)

    def get_sec_424b2_reparse_job(self, job_id: str) -> dict[str, Any]:
        row = self.storage.fetch_one("SELECT * FROM sec_424b2_reparse_jobs WHERE job_id = ?", (job_id,))
        if not row:
            raise ValueError(f"SEC 424B2 reparse job not found: {job_id}")
        candidates = loads(row.get("candidates_json"), [])
        actions = loads(row.get("actions_json"), [])
        allowlist = loads(row.get("reasons_allowlist_json"), [])
        summary = loads(row.get("summary_json"), {})
        return {
            "job_id": str(row.get("job_id") or ""),
            "status": str(row.get("status") or "NOT_FOUND"),
            "mode": str(row.get("mode") or "dry_run"),
            "dry_run": bool(row.get("dry_run")),
            "auto_repair_enabled": bool(row.get("auto_repair_enabled")),
            "reasons_allowlist": allowlist if isinstance(allowlist, list) else [],
            "candidate_count": int((summary or {}).get("candidate_count") or 0) if isinstance(summary, Mapping) else 0,
            "selected_count": len(actions) if isinstance(actions, list) else 0,
            "candidates": candidates if isinstance(candidates, list) else [],
            "actions": actions if isinstance(actions, list) else [],
            "summary": summary if isinstance(summary, dict) else {},
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
        }

    def _build_sec_424b2_reparse_job(self, request: Any | None, *, persist: bool) -> dict[str, Any]:
        payload = _as_mapping(request)
        mode = str(payload.get("mode") or os.getenv("GRIT_SEC_424B2_AUTO_REPAIR_MODE") or "dry_run").lower()
        dry_run = payload.get("dry_run")
        dry_run_enabled = True if dry_run is None else bool(dry_run)
        auto_repair_enabled = self._sec_424b2_auto_repair_enabled(payload)
        allowlist = self._sec_424b2_reparse_allowlist(payload)
        max_filings = max(1, min(100, int(payload.get("max_filings") or os.getenv("GRIT_SEC_424B2_AUTO_REPAIR_MAX_FILINGS") or 10)))
        candidate_response = self.list_sec_424b2_reparse_candidates(
            current_parser_version=payload.get("current_parser_version"),
            current_rule_hash=payload.get("current_rule_hash"),
        )
        candidates = [dict(item) for item in candidate_response.get("candidates") or [] if isinstance(item, Mapping)]
        eligible = [
            candidate
            for candidate in candidates
            if any(str(reason) in allowlist for reason in candidate.get("reasons") or [])
        ][:max_filings]
        status = "DRY_RUN_READY"
        blocked_reason = ""
        apply_requested = persist and mode == "apply_append_only" and not dry_run_enabled
        if mode not in {"dry_run", "apply_append_only"}:
            status = "DRY_RUN_ONLY"
            blocked_reason = "unsupported_reparse_job_mode"
            eligible = []
        elif not auto_repair_enabled:
            status = "DISABLED"
            blocked_reason = "auto_repair_disabled"
            eligible = []
        elif mode == "apply_append_only" and not apply_requested:
            status = "DRY_RUN_ONLY"
            blocked_reason = "apply_append_only_requires_create_endpoint_and_dry_run_false"
            eligible = []
        elif apply_requested and (set(allowlist) != {"INITIAL_VALUE_MISSING"} or max_filings > 10):
            status = "DRY_RUN_ONLY"
            blocked_reason = "apply_append_only_requires_initial_value_missing_allowlist_and_max_10"
            eligible = []
        if apply_requested and not blocked_reason:
            actions = [self._apply_sec_424b2_reparse_candidate(candidate, allowlist) for candidate in eligible]
            status = "APPLIED" if actions and all(action.get("status") == "APPLIED" for action in actions) else "PARTIAL"
            if not actions:
                status = "DRY_RUN_READY"
        else:
            actions = [
                {
                    "action": "REPARSE_DRY_RUN",
                    "run_id": str(candidate.get("run_id") or ""),
                    "note_id": str(candidate.get("note_id") or ""),
                    "accession_number": str(candidate.get("accession_number") or ""),
                    "source_url": str(candidate.get("source_url") or ""),
                    "matched_reasons": [
                        str(reason) for reason in candidate.get("reasons") or [] if str(reason) in allowlist
                    ],
                    "would_fetch_source_url": bool(candidate.get("source_url")),
                    "would_write_parse_run": bool(apply_requested),
                }
                for candidate in eligible
            ]
        now = iso_now()
        job_id = "sec424b2_reparse_job_" + hashlib.sha256(
            f"{now}|{uuid4().hex}|{allowlist}|{max_filings}".encode("utf-8")
        ).hexdigest()[:16]
        initial_value_missing_count = sum(int(candidate.get("missing_initial_value_count") or 0) for candidate in eligible)
        initial_value_resolved_count = sum(int(action.get("initial_value_resolved_count") or 0) for action in actions)
        review_required_count = sum(1 for action in actions if action.get("status") in {"REVIEW_REQUIRED", "DATA_SOURCE_BLOCKED", "FAILED"})
        cache_invalidated_note_ids = sorted(
            {
                str(action.get("note_id") or "")
                for action in actions
                if action.get("cache_invalidated") and str(action.get("note_id") or "")
            }
        )
        summary = {
            "candidate_count": len(candidates),
            "eligible_count": len(eligible),
            "selected_count": len(actions),
            "max_filings": max_filings,
            "blocked_reason": blocked_reason,
            "dry_run_only": not apply_requested,
            "initial_value_missing_count": initial_value_missing_count,
            "initial_value_resolved_count": initial_value_resolved_count,
            "review_required_count": review_required_count,
            "append_only_parse_run_count": sum(1 for action in actions if action.get("wrote_parse_run")),
            "cache_invalidated_note_ids": cache_invalidated_note_ids,
            "source": "reparse-candidates",
            "current_parser_version": (candidate_response.get("summary") or {}).get("current_parser_version"),
            "current_rule_hash": (candidate_response.get("summary") or {}).get("current_rule_hash"),
        }
        response = {
            "job_id": job_id,
            "status": status,
            "mode": mode if mode in {"dry_run", "apply_append_only"} else "dry_run",
            "dry_run": not apply_requested,
            "auto_repair_enabled": auto_repair_enabled,
            "reasons_allowlist": allowlist,
            "candidate_count": len(candidates),
            "selected_count": len(actions),
            "candidates": eligible,
            "actions": actions,
            "summary": summary,
            "created_at": now,
            "updated_at": now,
        }
        if persist:
            self.storage.insert_json_row(
                "sec_424b2_reparse_jobs",
                {
                    "id": job_id,
                    "job_id": job_id,
                    "status": status,
                    "mode": mode if mode in {"dry_run", "apply_append_only"} else "dry_run",
                    "dry_run": 0 if apply_requested else 1,
                    "auto_repair_enabled": 1 if auto_repair_enabled else 0,
                    "reasons_allowlist_json": dumps(allowlist),
                    "candidates_json": dumps(eligible),
                    "actions_json": dumps(actions),
                    "summary_json": dumps(summary),
                    "created_at": now,
                    "updated_at": now,
                },
            )
        return response

    def _apply_sec_424b2_reparse_candidate(
        self,
        candidate: Mapping[str, Any],
        allowlist: Sequence[str],
    ) -> dict[str, Any]:
        run_id = str(candidate.get("run_id") or "")
        note_id = str(candidate.get("note_id") or "")
        source_url = str(candidate.get("source_url") or "")
        accession_number = str(candidate.get("accession_number") or "")
        issuer_cik = str(candidate.get("issuer_cik") or "")
        matched_reasons = [str(reason) for reason in candidate.get("reasons") or [] if str(reason) in allowlist]
        action: dict[str, Any] = {
            "action": "REPARSE_APPLY_APPEND_ONLY",
            "run_id": run_id,
            "note_id": note_id,
            "accession_number": accession_number,
            "source_url": source_url,
            "matched_reasons": matched_reasons,
            "would_fetch_source_url": bool(source_url),
            "would_write_parse_run": True,
            "wrote_parse_run": False,
            "cache_invalidated": False,
            "initial_value_resolved_count": 0,
        }
        if not source_url:
            return {**action, "status": "DATA_SOURCE_BLOCKED", "blocked_reason": "missing_source_url"}
        try:
            html_text = SecEdgarProvider().fetch_archive_document(source_url)
            parsed = parse_sec_424b2_structured_note(
                html_text,
                source_url=source_url,
                issuer_cik=issuer_cik,
                accession_number=accession_number,
            )
            parsed_note = dict(parsed.get("note") or {})
            parsed_note_id = str(parsed_note.get("note_id") or note_id)
            before_count_row = self.storage.fetch_one("SELECT COUNT(*) AS count FROM sec_424b2_parse_runs")
            before_count = int((before_count_row or {}).get("count") or 0)
            self._persist_sec_424b2_parse_result(parsed)
            after_count_row = self.storage.fetch_one("SELECT COUNT(*) AS count FROM sec_424b2_parse_runs")
            after_count = int((after_count_row or {}).get("count") or 0)
            self._invalidate_structured_note_f1_static_cache(parsed_note_id)
            missing_initial = [
                item
                for item in parsed.get("underlyings") or []
                if isinstance(item, Mapping)
                and item.get("initial_value") is None
                and item.get("strike_value") is None
            ]
            resolved_count = sum(
                1
                for item in parsed.get("underlyings") or []
                if isinstance(item, Mapping)
                and (item.get("initial_value") is not None or item.get("strike_value") is not None)
            )
            status = "APPLIED" if str(parsed.get("status") or "") == "PARSED" and not missing_initial else "REVIEW_REQUIRED"
            return {
                **action,
                "status": status,
                "note_id": parsed_note_id,
                "new_parse_run_id": str((parsed.get("parse_run") or {}).get("run_id") or ""),
                "new_parse_run_inserted": after_count > before_count,
                "wrote_parse_run": True,
                "cache_invalidated": True,
                "initial_value_resolved_count": resolved_count,
                "missing_initial_value_count_after": len(missing_initial),
                "warnings": [str(item) for item in parsed.get("warnings") or []],
            }
        except Exception as exc:
            return {
                **action,
                "status": "DATA_SOURCE_BLOCKED",
                "blocked_reason": f"reparse_apply_failed: {exc}",
            }

    @staticmethod
    def _sec_424b2_auto_repair_enabled(payload: Mapping[str, Any]) -> bool:
        if payload.get("auto_repair_enabled") is not None:
            return bool(payload.get("auto_repair_enabled"))
        raw = str(os.getenv("GRIT_SEC_424B2_AUTO_REPAIR") or "off").strip().lower()
        return raw in {"1", "true", "yes", "on", "enabled"}

    @staticmethod
    def _sec_424b2_reparse_allowlist(payload: Mapping[str, Any]) -> list[str]:
        raw = payload.get("reasons_allowlist")
        if not raw:
            raw = [
                item.strip()
                for item in str(
                    os.getenv("GRIT_SEC_424B2_AUTO_REPAIR_REASON_ALLOWLIST")
                    or "PARSER_CHANGED,RULEPACK_CHANGED"
                ).split(",")
            ]
        elif isinstance(raw, str):
            raw = [item.strip() for item in raw.split(",")]
        allowed_reasons = {
            "PARSER_CHANGED",
            "RULEPACK_CHANGED",
            "HTML_CHANGED",
            "LOW_CONFIDENCE",
            "UNSUPPORTED_PAYOFF",
            "DATA_SOURCE_BLOCKED",
            "INITIAL_VALUE_MISSING",
        }
        allowlist = [str(item).strip().upper() for item in raw if str(item).strip().upper() in allowed_reasons]
        return allowlist or ["PARSER_CHANGED", "RULEPACK_CHANGED"]

    def preview_sec_424b2_ingestion_job(self, request: Any | None = None) -> dict[str, Any]:
        return self._build_sec_424b2_ingestion_job(request, persist=False)

    def create_sec_424b2_ingestion_job(self, request: Any | None = None) -> dict[str, Any]:
        return self._build_sec_424b2_ingestion_job(request, persist=True)

    def get_sec_424b2_ingestion_job(self, job_id: str) -> dict[str, Any]:
        row = self.storage.fetch_one("SELECT * FROM sec_424b2_ingestion_jobs WHERE job_id = ?", (job_id,))
        if not row:
            raise ValueError(f"SEC 424B2 ingestion job not found: {job_id}")
        accessions = loads(row.get("accessions_json"), [])
        actions = loads(row.get("actions_json"), [])
        summary = loads(row.get("summary_json"), {})
        if not isinstance(summary, Mapping):
            summary = {}
        return {
            "job_id": str(row.get("job_id") or ""),
            "status": str(row.get("status") or "DATA_SOURCE_BLOCKED"),
            "mode": str(row.get("mode") or "dry_run"),
            "dry_run": bool(row.get("dry_run")),
            "issuer_cik": str(summary.get("issuer_cik") or ""),
            "selected_count": int(summary.get("selected_count") or 0),
            "accessions": accessions if isinstance(accessions, list) else [],
            "actions": actions if isinstance(actions, list) else [],
            "summary": dict(summary),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
        }

    def _build_sec_424b2_ingestion_job(self, request: Any | None, *, persist: bool) -> dict[str, Any]:
        payload = _as_mapping(request)
        now = iso_now()
        issuer_cik = str(payload.get("issuer_cik") or "0001665650").strip()
        mode = str(payload.get("mode") or "dry_run").lower()
        dry_run = bool(payload.get("dry_run", True))
        max_filings = max(1, min(10_000, int(payload.get("max_filings") or 100)))
        scan_limit = max(1, min(10_000, int(payload.get("scan_limit") or max_filings)))
        rate_limit_rps = _coerce_float(payload.get("rate_limit_rps"), None)
        if rate_limit_rps is None:
            rate_limit_rps = _coerce_float(os.getenv("GRIT_SEC_424B2_RATE_LIMIT_RPS"), 5.0) or 5.0
        rate_limit_rps = max(0.1, min(float(rate_limit_rps), 10.0))
        entries, source_warnings = self._sec_424b2_ingestion_entries(payload, issuer_cik=issuer_cik, scan_limit=scan_limit)
        selected = entries[:max_filings]
        job_id = "sec424b2_ingest_" + hashlib.sha256(
            f"{issuer_cik}|{mode}|{dry_run}|{','.join(str(item.get('accession_number') or item.get('source_url') or '') for item in selected)}|{now}|{uuid4().hex}".encode("utf-8")
        ).hexdigest()[:16]
        actions: list[dict[str, Any]] = []
        status_counts: dict[str, int] = {}
        parsed_count = 0
        skipped_existing_count = 0
        blocked_count = 0
        apply_requested = persist and mode == "apply_append_only" and not dry_run
        unsupported_mode = mode not in {"dry_run", "apply_append_only"}
        for index, entry in enumerate(selected):
            accession = str(entry.get("accession_number") or "")
            source_url = str(entry.get("source_url") or entry.get("primary_document_url") or "")
            existing = self._sec_424b2_existing_current_parse(accession, source_url)
            action = {
                "accession_number": accession,
                "source_url": source_url,
                "primary_document": str(entry.get("primary_document") or ""),
                "issuer_cik": str(entry.get("issuer_cik") or issuer_cik),
                "existing_parse_run_id": str((existing or {}).get("run_id") or ""),
                "would_fetch_source_url": bool(source_url),
                "would_write_parse_run": False,
                "wrote_parse_run": False,
                "status": "WOULD_FETCH_AND_PARSE",
            }
            if unsupported_mode:
                action["status"] = "DATA_SOURCE_BLOCKED"
                action["blocked_reason"] = "unsupported_ingestion_job_mode"
                blocked_count += 1
            elif existing:
                action["status"] = "SKIPPED_EXISTING"
                skipped_existing_count += 1
            elif not source_url:
                action["status"] = "DATA_SOURCE_BLOCKED"
                action["blocked_reason"] = "missing_source_url"
                blocked_count += 1
            elif apply_requested:
                action["would_write_parse_run"] = True
                try:
                    html_text = SecEdgarProvider().fetch_archive_document(source_url)
                    parsed = parse_sec_424b2_structured_note(
                        html_text,
                        source_url=source_url,
                        issuer_cik=str(entry.get("issuer_cik") or issuer_cik),
                        accession_number=accession,
                        primary_document=str(entry.get("primary_document") or ""),
                        parser_options=payload.get("parser_options") if isinstance(payload.get("parser_options"), Mapping) else {},
                    )
                    self._persist_sec_424b2_parse_result(parsed)
                    parsed_count += 1
                    action.update(
                        {
                            "status": str(parsed.get("status") or "REVIEW_REQUIRED"),
                            "wrote_parse_run": True,
                            "new_parse_run_id": str((parsed.get("parse_run") or {}).get("run_id") or ""),
                            "note_id": str((parsed.get("note") or {}).get("note_id") or ""),
                            "warnings": list(parsed.get("warnings") or []),
                        }
                    )
                    if index < len(selected) - 1:
                        sleep(1.0 / rate_limit_rps)
                except Exception as exc:
                    blocked_count += 1
                    action.update(
                        {
                            "status": "DATA_SOURCE_BLOCKED",
                            "blocked_reason": f"fetch_or_parse_failed: {exc}",
                        }
                    )
            else:
                action["would_write_parse_run"] = True
            actions.append(action)
            action_status = str(action.get("status") or "")
            status_counts[action_status] = status_counts.get(action_status, 0) + 1
        if unsupported_mode:
            status = "FAILED"
        elif not selected or blocked_count == len(selected):
            status = "DATA_SOURCE_BLOCKED"
        elif apply_requested and blocked_count:
            status = "PARTIAL"
        elif apply_requested:
            status = "COMPLETED"
        else:
            status = "DRY_RUN_READY"
        summary = {
            "issuer_cik": str(issuer_cik).zfill(10) if str(issuer_cik).isdigit() else issuer_cik,
            "scan_limit": scan_limit,
            "max_filings": max_filings,
            "selected_count": len(selected),
            "discovered_count": len(entries),
            "parsed_count": parsed_count,
            "skipped_existing_count": skipped_existing_count,
            "data_source_blocked_count": blocked_count,
            "status_counts": status_counts,
            "rate_limit_rps": rate_limit_rps,
            "rate_limit_sleep_seconds_per_request": 1.0 / rate_limit_rps,
            "warnings": source_warnings,
            "append_only": True,
            "publish_boundary": "sandbox -> quarantine -> publish",
            "formal_replay_runs": 0,
            "factor_factory_write": False,
        }
        response = {
            "job_id": job_id,
            "status": status,
            "mode": mode if mode in {"dry_run", "apply_append_only"} else "dry_run",
            "dry_run": not apply_requested,
            "issuer_cik": str(summary.get("issuer_cik") or ""),
            "selected_count": len(selected),
            "accessions": selected,
            "actions": actions,
            "summary": summary,
            "created_at": now,
            "updated_at": now,
        }
        if persist:
            self.storage.insert_json_row(
                "sec_424b2_ingestion_jobs",
                {
                    "id": job_id,
                    "job_id": job_id,
                    "status": status,
                    "mode": response["mode"],
                    "dry_run": 1 if response["dry_run"] else 0,
                    "request_json": dumps(dict(payload)),
                    "accessions_json": dumps(selected),
                    "actions_json": dumps(actions),
                    "summary_json": dumps(summary),
                    "created_at": now,
                    "updated_at": now,
                },
            )
        return response

    def _sec_424b2_ingestion_entries(
        self,
        payload: Mapping[str, Any],
        *,
        issuer_cik: str,
        scan_limit: int,
    ) -> tuple[list[dict[str, Any]], list[str]]:
        warnings: list[str] = []
        entries: list[dict[str, Any]] = []
        manifest_path = str(payload.get("manifest_path") or "").strip()
        raw_accessions = payload.get("accessions") if isinstance(payload.get("accessions"), list) else []
        if raw_accessions:
            for item in raw_accessions:
                if isinstance(item, Mapping):
                    accession = str(item.get("accession_number") or item.get("accession") or "")
                    entries.append(
                        {
                            "accession_number": accession,
                            "source_url": str(item.get("source_url") or item.get("primary_document_url") or ""),
                            "primary_document": str(item.get("primary_document") or ""),
                            "issuer_cik": str(item.get("issuer_cik") or issuer_cik),
                        }
                    )
                else:
                    entries.append(
                        {
                            "accession_number": str(item),
                            "source_url": "",
                            "primary_document": "",
                            "issuer_cik": issuer_cik,
                        }
                    )
            return entries, warnings
        if manifest_path:
            try:
                manifest = json.loads(Path(manifest_path).read_text(encoding="utf-8"))
                raw_entries = manifest.get("entries") if isinstance(manifest, Mapping) else []
                for entry in raw_entries or []:
                    if not isinstance(entry, Mapping):
                        continue
                    entries.append(
                        {
                            "accession_number": str(entry.get("accession_number") or ""),
                            "source_url": str(entry.get("source_url") or entry.get("primary_document_url") or ""),
                            "primary_document": str(entry.get("primary_document") or ""),
                            "issuer_cik": str(entry.get("issuer_cik") or issuer_cik),
                        }
                    )
                return entries, warnings
            except Exception as exc:
                warnings.append(f"manifest_load_failed:{exc}")
                return [], warnings
        provider = SecEdgarProvider()
        filings = provider.fetch_424b2_filings_by_cik(issuer_cik, limit=scan_limit)
        for filing in filings:
            entries.append(
                {
                    "accession_number": str(filing.get("accession_number") or ""),
                    "source_url": str(filing.get("primary_document_url") or ""),
                    "primary_document": str(filing.get("primary_document") or ""),
                    "issuer_cik": str(filing.get("cik") or issuer_cik),
                    "filing_date": filing.get("date"),
                    "form": filing.get("form"),
                }
            )
        return entries, warnings

    def _sec_424b2_existing_current_parse(self, accession: str, source_url: str) -> dict[str, Any] | None:
        if accession:
            row = self.storage.fetch_one(
                """
                SELECT *
                FROM sec_424b2_parse_runs
                WHERE accession_number = ?
                  AND parser_version = ?
                  AND parser_rule_hash = ?
                  AND status = 'PARSED'
                ORDER BY updated_at DESC, run_id DESC
                LIMIT 1
                """,
                (accession, SEC_424B2_PARSER_VERSION, SEC_424B2_PARSER_RULE_HASH),
            )
            if row:
                return row
        if source_url:
            return self.storage.fetch_one(
                """
                SELECT *
                FROM sec_424b2_parse_runs
                WHERE source_url = ?
                  AND parser_version = ?
                  AND parser_rule_hash = ?
                  AND status = 'PARSED'
                ORDER BY updated_at DESC, run_id DESC
                LIMIT 1
                """,
                (source_url, SEC_424B2_PARSER_VERSION, SEC_424B2_PARSER_RULE_HASH),
            )
        return None

    def replay_structured_note_fcn(self, request: Any | None = None) -> dict[str, Any]:
        payload = _as_mapping(request)
        parse_run_id = str(payload.get("parse_run_id") or "").strip()
        note_id = str(payload.get("note_id") or "").strip()
        if parse_run_id:
            parsed = self.get_sec_424b2_parse_run(parse_run_id)
        elif note_id:
            note_row = self.storage.fetch_one("SELECT * FROM structured_note_terms WHERE note_id = ?", (note_id,))
            if not note_row:
                raise ValueError(f"Structured note not found: {note_id}")
            parsed = self.get_sec_424b2_parse_run(str(note_row.get("parse_run_id") or ""))
        else:
            raise ValueError("FCN replay requires note_id or parse_run_id.")
        parsed_note = dict(parsed.get("note") or {})
        bundle = self.get_structured_note_f1_static_bundle(str(parsed_note.get("note_id") or note_id))
        note = dict(bundle.get("note") or parsed_note)
        underlyings = [dict(item) for item in bundle.get("underlying_slots") or [] if isinstance(item, Mapping)]
        dataset_snapshot_id = str(payload.get("dataset_snapshot_id") or DATASET_PRICE_SNAPSHOT_ID)
        replay_mode = str(payload.get("replay_mode") or "sandbox").lower()
        price_proxies = dict(payload.get("price_proxies") or {}) if isinstance(payload.get("price_proxies"), Mapping) else {}
        symbol_map = self._structured_note_price_symbol_map(underlyings, price_proxies, replay_mode)
        rows_by_symbol = self.market_data_repository.load_dataset_price_bars(
            dataset_snapshot_id,
            sorted(set(symbol_map.values())),
            start_date=payload.get("start_date") or note.get("pricing_date"),
            end_date=payload.get("end_date") or note.get("maturity_date"),
            include_metadata=False,
        )
        logical_rows = {
            logical: list(rows_by_symbol.get(actual) or [])
            for logical, actual in symbol_map.items()
        }
        missing_symbols = [ticker for ticker, rows in logical_rows.items() if not rows]
        observation_dates = self._structured_note_observation_dates(
            logical_rows,
            str(payload.get("observation_frequency") or note.get("observation_frequency") or note.get("coupon_frequency") or "Monthly"),
        )
        replay_underlyings = deepcopy(underlyings)
        points: list[dict[str, Any]] = []
        history: list[float] = []
        price_by_ticker_date = {
            ticker: {str(row.get("date")): _coerce_float(row.get("adj_close") or row.get("close"), None) for row in rows}
            for ticker, rows in logical_rows.items()
        }
        for note_date in observation_dates:
            current_prices = {
                ticker: price_by_date.get(note_date)
                for ticker, price_by_date in price_by_ticker_date.items()
                if price_by_date.get(note_date) is not None
            }
            signal = evaluate_fcn_note_signals(
                note,
                replay_underlyings,
                current_prices,
                history_worst_performance=history[-21:],
            )
            if signal.get("worst_performance") is not None:
                history.append(float(signal["worst_performance"]))
            points.append(
                {
                    "note_date": note_date,
                    "status": str(signal.get("status") or "OK"),
                    "worst_performance": signal.get("worst_performance"),
                    "coupon_eligible": bool(signal.get("coupon_eligible")),
                    "coupon_signal": float(signal.get("coupon_signal") or 0.0),
                    "autocall_trigger": bool(signal.get("autocall_trigger")),
                    "distance_to_barrier": signal.get("distance_to_barrier"),
                    "details": signal,
                }
            )
        ok_count = sum(1 for point in points if point.get("status") == "OK")
        status = "OK" if points and ok_count == len(points) else "PARTIAL" if ok_count else "DATA_SOURCE_BLOCKED"
        if missing_symbols:
            status = "PARTIAL" if ok_count else "DATA_SOURCE_BLOCKED"
        run_id = "fcn_replay_" + hashlib.sha256(
            f"{note.get('note_id')}|{dataset_snapshot_id}|{replay_mode}|{iso_now()}|{uuid4().hex}".encode("utf-8")
        ).hexdigest()[:16]
        now = iso_now()
        summary = {
            "point_count": len(points),
            "ok_count": ok_count,
            "blocked_count": len(points) - ok_count,
            "missing_symbols": missing_symbols,
            "dataset_snapshot_id": dataset_snapshot_id,
            "price_source": "dataset_price_bars.adj_close",
            "f1_static_cache_status": bundle.get("cache_status"),
            "underlying_count": bundle.get("underlying_count"),
            "definition_version": bundle.get("definition_version"),
            "missing_static_fields": bundle.get("missing_fields") or [],
        }
        self.storage.insert_json_row(
            "structured_note_replay_runs",
            {
                "id": run_id,
                "run_id": run_id,
                "note_id": str(note.get("note_id") or ""),
                "parse_run_id": parse_run_id or str(parsed.get("parse_run", {}).get("run_id") or ""),
                "dataset_snapshot_id": dataset_snapshot_id,
                "replay_mode": replay_mode,
                "status": status,
                "summary_json": dumps(summary),
                "price_proxies_json": dumps(price_proxies),
                "created_at": now,
                "updated_at": now,
            },
        )
        for point in points:
            point_id = "fcn_replay_point_" + hashlib.sha256(
                f"{run_id}|{point.get('note_date')}".encode("utf-8")
            ).hexdigest()[:16]
            self.storage.insert_json_row(
                "structured_note_replay_points",
                {
                    "id": point_id,
                    "replay_run_id": run_id,
                    "note_id": str(note.get("note_id") or ""),
                    "note_date": str(point.get("note_date") or ""),
                    "status": str(point.get("status") or "OK"),
                    "worst_performance": point.get("worst_performance"),
                    "coupon_eligible": 1 if point.get("coupon_eligible") else 0,
                    "coupon_signal": point.get("coupon_signal"),
                    "autocall_trigger": 1 if point.get("autocall_trigger") else 0,
                    "distance_to_barrier": point.get("distance_to_barrier"),
                    "details_json": dumps(dict(point.get("details") or {})),
                    "created_at": now,
                },
            )
        return {
            "run_id": run_id,
            "note_id": str(note.get("note_id") or ""),
            "parse_run_id": parse_run_id or str(parsed.get("parse_run", {}).get("run_id") or ""),
            "dataset_snapshot_id": dataset_snapshot_id,
            "replay_mode": replay_mode,
            "status": status,
            "points": points,
            "summary": summary,
            "price_proxies": price_proxies,
            "created_at": now,
            "updated_at": now,
        }

    def replay_structured_note_fcn_batch(self, request: Any | None = None) -> dict[str, Any]:
        payload = _as_mapping(request)
        now = iso_now()
        note_ids, selection_warnings = self._structured_note_preflight_note_ids(payload)
        batch_id = "fcn_replay_batch_" + hashlib.sha256(
            f"{','.join(note_ids)}|{payload.get('dataset_snapshot_id') or DATASET_PRICE_SNAPSHOT_ID}|{now}|{uuid4().hex}".encode("utf-8")
        ).hexdigest()[:16]
        run_ids: list[str] = []
        note_results: list[dict[str, Any]] = []
        replay_point_count = 0
        data_source_blocked_count = 0
        for note_id in note_ids:
            try:
                replay_payload = {
                    "note_id": note_id,
                    "dataset_snapshot_id": payload.get("dataset_snapshot_id") or DATASET_PRICE_SNAPSHOT_ID,
                    "replay_mode": payload.get("replay_mode") or "sandbox",
                    "start_date": payload.get("start_date"),
                    "end_date": payload.get("end_date"),
                    "observation_frequency": payload.get("observation_frequency"),
                    "price_proxies": payload.get("price_proxies") if isinstance(payload.get("price_proxies"), Mapping) else {},
                }
                replay = self.replay_structured_note_fcn(replay_payload)
                run_id = str(replay.get("run_id") or "")
                if run_id:
                    run_ids.append(run_id)
                summary = replay.get("summary") if isinstance(replay.get("summary"), Mapping) else {}
                points = replay.get("points") if isinstance(replay.get("points"), list) else []
                replay_point_count += len(points)
                if str(replay.get("status") or "") == "DATA_SOURCE_BLOCKED":
                    data_source_blocked_count += 1
                note_results.append(
                    {
                        "note_id": str(replay.get("note_id") or note_id),
                        "parse_run_id": replay.get("parse_run_id"),
                        "replay_run_id": run_id or None,
                        "status": str(replay.get("status") or "DATA_SOURCE_BLOCKED"),
                        "point_count": len(points),
                        "blocked_count": int(summary.get("blocked_count") or 0),
                        "missing_symbols": list(summary.get("missing_symbols") or []),
                        "error_message": None,
                    }
                )
            except Exception as exc:
                data_source_blocked_count += 1
                note_results.append(
                    {
                        "note_id": note_id,
                        "parse_run_id": None,
                        "replay_run_id": None,
                        "status": "DATA_SOURCE_BLOCKED",
                        "point_count": 0,
                        "blocked_count": 0,
                        "missing_symbols": [],
                        "error_message": str(exc),
                    }
                )
        ok_count = sum(1 for item in note_results if item.get("status") == "OK")
        if note_results and ok_count == len(note_results):
            status = "OK"
        elif ok_count:
            status = "PARTIAL"
        else:
            status = "DATA_SOURCE_BLOCKED"
        summary = {
            "warnings": selection_warnings,
            "dataset_snapshot_id": str(payload.get("dataset_snapshot_id") or DATASET_PRICE_SNAPSHOT_ID),
            "replay_mode": str(payload.get("replay_mode") or "sandbox"),
            "sample_limit": int(payload.get("sample_limit") or 10),
            "max_notes": int(payload.get("max_notes") or 100),
            "manifest_id": payload.get("manifest_id"),
            "manifest_path": payload.get("manifest_path"),
            "run_ids": run_ids,
            "shadow_replay": True,
            "preflight_only": False,
            "publish_boundary": "sandbox -> quarantine -> publish",
            "formal_factor_factory_write": False,
        }
        response = {
            "batch_id": batch_id,
            "status": status,
            "note_count": len(note_results),
            "replay_run_count": len(run_ids),
            "replay_point_count": replay_point_count,
            "data_source_blocked_count": data_source_blocked_count,
            "run_ids": run_ids,
            "note_results": note_results,
            "summary": summary,
            "created_at": now,
            "updated_at": now,
        }
        self.storage.insert_json_row(
            "structured_note_replay_batches",
            {
                "id": batch_id,
                "batch_id": batch_id,
                "status": status,
                "request_json": dumps(dict(payload)),
                "run_ids_json": dumps(run_ids),
                "note_results_json": dumps(note_results),
                "summary_json": dumps(
                    {
                        **summary,
                        "note_count": response["note_count"],
                        "replay_run_count": response["replay_run_count"],
                        "replay_point_count": replay_point_count,
                        "data_source_blocked_count": data_source_blocked_count,
                    }
                ),
                "created_at": now,
                "updated_at": now,
            },
        )
        return response

    def get_structured_note_fcn_replay_batch(self, batch_id: str) -> dict[str, Any]:
        row = self.storage.fetch_one("SELECT * FROM structured_note_replay_batches WHERE batch_id = ?", (batch_id,))
        if not row:
            raise ValueError(f"Structured note replay batch not found: {batch_id}")
        return self._decode_structured_note_replay_batch(row)

    def _decode_structured_note_replay_batch(self, row: Mapping[str, Any]) -> dict[str, Any]:
        summary = loads(row.get("summary_json"), {})
        if not isinstance(summary, Mapping):
            summary = {}
        run_ids = loads(row.get("run_ids_json"), [])
        note_results = loads(row.get("note_results_json"), [])
        return {
            "batch_id": str(row.get("batch_id") or ""),
            "status": str(row.get("status") or "DATA_SOURCE_BLOCKED"),
            "note_count": int(summary.get("note_count") or 0),
            "replay_run_count": int(summary.get("replay_run_count") or 0),
            "replay_point_count": int(summary.get("replay_point_count") or 0),
            "data_source_blocked_count": int(summary.get("data_source_blocked_count") or 0),
            "run_ids": run_ids if isinstance(run_ids, list) else [],
            "note_results": note_results if isinstance(note_results, list) else [],
            "summary": dict(summary),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
        }

    def get_structured_note_fcn_replay_batch_attribution_summary(self, batch_id: str) -> dict[str, Any]:
        batch = self.get_structured_note_fcn_replay_batch(batch_id)
        note_results: list[dict[str, Any]] = []
        latest_net_benefits: list[float] = []
        negative_convexity_count = 0
        blocked_count = 0
        status_counts: dict[str, int] = {}
        for run_id in batch.get("run_ids") or []:
            try:
                attribution = self.get_structured_note_fcn_attribution(str(run_id))
                summary = attribution.get("summary") if isinstance(attribution.get("summary"), Mapping) else {}
                latest_net_benefit = _coerce_float(summary.get("latest_net_benefit"), None)
                if latest_net_benefit is not None:
                    latest_net_benefits.append(latest_net_benefit)
                counts = summary.get("status_counts") if isinstance(summary.get("status_counts"), Mapping) else {}
                negative_convexity_count += 1 if int(counts.get("NEGATIVE_CONVEXITY_ACTIVE") or 0) > 0 else 0
                if str(attribution.get("status") or "") == "DATA_SOURCE_BLOCKED":
                    blocked_count += 1
                status = str(attribution.get("status") or "DATA_SOURCE_BLOCKED")
                status_counts[status] = status_counts.get(status, 0) + 1
                note_results.append(
                    {
                        "run_id": str(run_id),
                        "note_id": str(attribution.get("note_id") or ""),
                        "status": status,
                        "latest_net_benefit": latest_net_benefit,
                        "point_count": int(summary.get("point_count") or 0),
                        "blocked_count": int(summary.get("blocked_count") or 0),
                        "status_counts": dict(counts),
                    }
                )
            except Exception as exc:
                blocked_count += 1
                status_counts["DATA_SOURCE_BLOCKED"] = status_counts.get("DATA_SOURCE_BLOCKED", 0) + 1
                note_results.append(
                    {
                        "run_id": str(run_id),
                        "note_id": "",
                        "status": "DATA_SOURCE_BLOCKED",
                        "latest_net_benefit": None,
                        "point_count": 0,
                        "blocked_count": 0,
                        "status_counts": {},
                        "error_message": str(exc),
                    }
                )
        status = "OK" if note_results and blocked_count == 0 else "PARTIAL" if note_results else "DATA_SOURCE_BLOCKED"
        if blocked_count == len(note_results) and note_results:
            status = "DATA_SOURCE_BLOCKED"
        latest_sum = sum(latest_net_benefits) if latest_net_benefits else None
        latest_avg = (latest_sum / len(latest_net_benefits)) if latest_sum is not None and latest_net_benefits else None
        return {
            "batch_id": str(batch.get("batch_id") or batch_id),
            "status": status,
            "note_count": len(note_results),
            "replay_run_count": len(batch.get("run_ids") or []),
            "latest_net_benefit_sum": latest_sum,
            "latest_net_benefit_avg": latest_avg,
            "negative_convexity_note_count": negative_convexity_count,
            "data_source_blocked_count": blocked_count,
            "note_results": note_results,
            "summary": {
                "source_batch_status": batch.get("status"),
                "status_counts": status_counts,
                "publish_boundary": "sandbox -> quarantine -> publish",
                "advisory_only": True,
            },
            "created_at": batch.get("created_at"),
            "updated_at": iso_now(),
        }

    def get_structured_note_replay_run(self, run_id: str) -> dict[str, Any]:
        row = self.storage.fetch_one("SELECT * FROM structured_note_replay_runs WHERE run_id = ?", (run_id,))
        if not row:
            raise ValueError(f"Structured note replay run not found: {run_id}")
        point_rows = self.storage.fetch_all(
            "SELECT * FROM structured_note_replay_points WHERE replay_run_id = ? ORDER BY note_date",
            (run_id,),
        )
        return {
            "run_id": str(row.get("run_id") or ""),
            "note_id": str(row.get("note_id") or ""),
            "parse_run_id": row.get("parse_run_id"),
            "dataset_snapshot_id": str(row.get("dataset_snapshot_id") or DATASET_PRICE_SNAPSHOT_ID),
            "replay_mode": str(row.get("replay_mode") or "sandbox"),
            "status": str(row.get("status") or "DATA_SOURCE_BLOCKED"),
            "points": [
                {
                    "note_date": str(point.get("note_date") or ""),
                    "status": str(point.get("status") or "OK"),
                    "worst_performance": point.get("worst_performance"),
                    "coupon_eligible": bool(point.get("coupon_eligible")),
                    "coupon_signal": float(point.get("coupon_signal") or 0.0),
                    "autocall_trigger": bool(point.get("autocall_trigger")),
                    "distance_to_barrier": point.get("distance_to_barrier"),
                    "details": loads(point.get("details_json"), {}),
                }
                for point in point_rows
            ],
            "summary": loads(row.get("summary_json"), {}),
            "price_proxies": loads(row.get("price_proxies_json"), {}),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
        }

    def get_structured_note_fcn_attribution(self, run_id: str) -> dict[str, Any]:
        replay = self.get_structured_note_replay_run(run_id)
        replay_summary = replay.get("summary") if isinstance(replay.get("summary"), Mapping) else {}
        bundle_summary: dict[str, Any] = {
            "f1_static_cache_status": replay_summary.get("f1_static_cache_status"),
            "underlying_count": replay_summary.get("underlying_count"),
            "definition_version": replay_summary.get("definition_version"),
        }
        try:
            bundle = self.get_structured_note_f1_static_bundle(str(replay.get("note_id") or ""))
            bundle_summary = {
                "f1_static_cache_status": bundle.get("cache_status"),
                "underlying_count": bundle.get("underlying_count"),
                "definition_version": bundle.get("definition_version"),
            }
        except Exception:
            pass
        cumulative_coupons = 0.0
        points: list[dict[str, Any]] = []
        status_counts: dict[str, int] = {}
        blocked_count = 0
        latest_net_benefit: float | None = None
        for point in replay.get("points") or []:
            coupon_signal = _coerce_float(point.get("coupon_signal"), 0.0)
            cumulative_coupons += coupon_signal
            worst_performance = _coerce_float(point.get("worst_performance"), None)
            source_status = str(point.get("status") or "")
            drawdown_loss_proxy: float | None = None
            net_benefit: float | None = None
            coverage_ratio: float | None = None
            attribution_status = "DATA_SOURCE_BLOCKED"
            if source_status == "OK" and worst_performance is not None:
                drawdown_loss_proxy = max(0.0, 1.0 - float(worst_performance))
                net_benefit = cumulative_coupons - drawdown_loss_proxy
                latest_net_benefit = net_benefit
                if drawdown_loss_proxy > 0:
                    coverage_ratio = cumulative_coupons / drawdown_loss_proxy
                distance = _coerce_float(point.get("distance_to_barrier"), None)
                if net_benefit < 0 and distance is not None and distance <= 0:
                    attribution_status = "NEGATIVE_CONVEXITY_ACTIVE"
                elif net_benefit < 0:
                    attribution_status = "COUPON_OFFSET_EXHAUSTED"
                else:
                    attribution_status = "CARRY_BUFFERING"
            else:
                blocked_count += 1
            status_counts[attribution_status] = status_counts.get(attribution_status, 0) + 1
            points.append(
                {
                    "note_date": str(point.get("note_date") or ""),
                    "status": attribution_status,
                    "worst_performance": worst_performance,
                    "cumulative_coupons": cumulative_coupons,
                    "drawdown_loss_proxy": drawdown_loss_proxy,
                    "net_benefit": net_benefit,
                    "coupon_loss_coverage_ratio": coverage_ratio,
                    "coupon_signal": coupon_signal,
                    "source_replay_status": source_status,
                    "details": {
                        "source_replay_run_id": run_id,
                        "formula": "Cumulative_Coupons - Max(0, 1 - Worst_Performance)",
                        "advisory_only": True,
                    },
                }
            )
        status = "OK" if points and blocked_count == 0 else "PARTIAL" if points else "DATA_SOURCE_BLOCKED"
        if blocked_count == len(points) and points:
            status = "DATA_SOURCE_BLOCKED"
        return {
            "run_id": str(replay.get("run_id") or run_id),
            "note_id": str(replay.get("note_id") or ""),
            "parse_run_id": replay.get("parse_run_id"),
            "status": status,
            "points": points,
            "summary": {
                "point_count": len(points),
                "blocked_count": blocked_count,
                "status_counts": status_counts,
                "cumulative_coupons": cumulative_coupons,
                "latest_net_benefit": latest_net_benefit,
                "source_replay_status": replay.get("status"),
                "publish_boundary": "sandbox -> quarantine -> publish",
                "advisory_only": True,
                **bundle_summary,
            },
            "created_at": replay.get("created_at"),
            "updated_at": replay.get("updated_at"),
        }

    def pressure_test_structured_note_fcn_pilot(self, request: Any | None = None) -> dict[str, Any]:
        payload = _as_mapping(request)
        manifest, manifest_path = self._load_structured_note_pilot_manifest(payload)
        entries = [dict(item) for item in manifest.get("entries") or [] if isinstance(item, Mapping)]
        near_threshold = max(0.0, _coerce_float(payload.get("near_barrier_threshold"), 1.0))
        target_symbol = str(payload.get("target_symbol") or "QQQ").upper()
        note_results: list[dict[str, Any]] = []
        distances: list[float] = []
        blocked_count = 0
        cache_status_counts: dict[str, int] = {}
        underlying_counts: list[int] = []
        for entry in entries:
            note_id = str(entry.get("note_id") or "")
            accession = str(entry.get("accession_number") or "")
            if not note_id:
                blocked_count += 1
                note_results.append(
                    {
                        "note_id": "",
                        "accession_number": accession,
                        "replay_run_id": None,
                        "note_date": None,
                        "status": "DATA_SOURCE_BLOCKED",
                        "distance_to_barrier": None,
                        "worst_performance": None,
                        "reason": "missing_note_id",
                    }
                )
                continue
            try:
                bundle = self.get_structured_note_f1_static_bundle(note_id)
                cache_status = str(bundle.get("cache_status") or "")
                cache_status_counts[cache_status] = cache_status_counts.get(cache_status, 0) + 1
                underlying_counts.append(int(bundle.get("underlying_count") or 0))
            except Exception:
                bundle = {}
            latest = self.storage.fetch_one(
                """
                SELECT run_id
                FROM structured_note_replay_runs
                WHERE note_id = ?
                ORDER BY updated_at DESC, created_at DESC, run_id DESC
                LIMIT 1
                """,
                (note_id,),
            )
            if not latest:
                blocked_count += 1
                note_results.append(
                    {
                        "note_id": note_id,
                        "accession_number": accession,
                        "replay_run_id": None,
                        "note_date": None,
                        "status": "DATA_SOURCE_BLOCKED",
                        "distance_to_barrier": None,
                        "worst_performance": None,
                        "reason": "missing_replay_run",
                    }
                )
                continue
            replay = self.get_structured_note_replay_run(str(latest.get("run_id") or ""))
            replay_points = list(replay.get("points") or [])
            latest_point = replay_points[-1] if replay_points else {}
            distance = _coerce_float(latest_point.get("distance_to_barrier"), None)
            worst = _coerce_float(latest_point.get("worst_performance"), None)
            source_status = str(latest_point.get("status") or replay.get("status") or "")
            if source_status != "OK" or distance is None:
                blocked_count += 1
                note_results.append(
                    {
                        "note_id": note_id,
                        "accession_number": accession,
                        "replay_run_id": replay.get("run_id"),
                        "note_date": latest_point.get("note_date"),
                        "status": "DATA_SOURCE_BLOCKED",
                        "distance_to_barrier": distance,
                        "worst_performance": worst,
                        "reason": "missing_distance_to_barrier",
                    }
                )
                continue
            distances.append(float(distance))
            note_results.append(
                {
                    "note_id": note_id,
                    "accession_number": accession,
                    "replay_run_id": replay.get("run_id"),
                    "note_date": latest_point.get("note_date"),
                    "status": "OK",
                    "distance_to_barrier": float(distance),
                    "worst_performance": worst,
                    "reason": "",
                }
            )
        evaluated_count = len(entries)
        coverage_ratio = (len(distances) / evaluated_count) if evaluated_count else 0.0
        average_distance = (sum(distances) / len(distances)) if distances else None
        min_distance = min(distances) if distances else None
        near_count = sum(1 for distance in distances if distance < near_threshold)
        breached_count = sum(1 for distance in distances if distance <= 0)
        if coverage_ratio < 0.8 or average_distance is None:
            risk_state = "DATA_SOURCE_BLOCKED"
        elif average_distance < 1.0 or near_count >= 3:
            risk_state = "REDUCE_BETA"
        elif average_distance < 2.0:
            risk_state = "WATCH"
        else:
            risk_state = "NORMAL"
        advisory_instructions: list[dict[str, Any]] = []
        if risk_state == "REDUCE_BETA":
            advisory_instructions.append(
                {
                    "action_type": "Beta_Reduction",
                    "target": target_symbol,
                    "mode": "ADVISORY_ONLY",
                    "reason": "Pilot FCN average distance to barrier deteriorated",
                    "suggested_beta_multiplier": 0.75,
                    "publish_boundary": "sandbox -> quarantine -> publish",
                }
            )
        now = iso_now()
        return {
            "manifest_id": str(manifest.get("manifest_id") or payload.get("manifest_id") or ""),
            "manifest_path": manifest_path,
            "risk_state": risk_state,
            "evaluated_note_count": evaluated_count,
            "blocked_note_count": blocked_count,
            "coverage_ratio": coverage_ratio,
            "average_distance_to_barrier": average_distance,
            "min_distance_to_barrier": min_distance,
            "notes_near_barrier_count": near_count,
            "notes_breached_barrier_count": breached_count,
            "advisory_instructions": advisory_instructions,
            "note_results": note_results,
            "summary": {
                "near_barrier_threshold": near_threshold,
                "target_symbol": target_symbol,
                "advisory_only": True,
                "source": "latest_structured_note_replay_runs",
                "manifest_hash": manifest.get("manifest_hash"),
                "f1_static_cache_status": cache_status_counts,
                "underlying_count": {
                    "min": min(underlying_counts) if underlying_counts else 0,
                    "max": max(underlying_counts) if underlying_counts else 0,
                },
                "definition_version": STRUCTURED_NOTE_DEFINITION_VERSION,
            },
            "created_at": now,
        }

    def _load_structured_note_pilot_manifest(self, payload: Mapping[str, Any]) -> tuple[dict[str, Any], str | None]:
        manifest_path = str(payload.get("manifest_path") or "").strip()
        manifest_id = str(payload.get("manifest_id") or "").strip()
        if manifest_path:
            path = Path(manifest_path)
            if not path.exists():
                raise ValueError(f"Structured note pilot manifest not found: {manifest_path}")
            manifest = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(manifest, dict):
                raise ValueError(f"Structured note pilot manifest must be a JSON object: {manifest_path}")
            return manifest, str(path)
        if not manifest_id:
            raise ValueError("Pilot pressure test requires manifest_id or manifest_path.")
        row = self.storage.fetch_one("SELECT * FROM structured_note_pilot_manifests WHERE manifest_id = ?", (manifest_id,))
        if not row:
            raise ValueError(f"Structured note pilot manifest not found: {manifest_id}")
        summary = loads(row.get("summary_json"), {})
        manifest = {
            "manifest_id": str(row.get("manifest_id") or ""),
            "issuer_cik": str(row.get("issuer_cik") or ""),
            "manifest_path": str(row.get("manifest_path") or ""),
            "entries": loads(row.get("entries_json"), []),
            **(summary if isinstance(summary, dict) else {}),
        }
        return manifest, str(row.get("manifest_path") or "")

    @staticmethod
    def _sec_424b2_pilot_manifest_entry(
        parsed: Mapping[str, Any],
        *,
        filing: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        filing = filing or {}
        parse_run = dict(parsed.get("parse_run") or {})
        note = dict(parsed.get("note") or {})
        underlyings = [dict(item) for item in parsed.get("underlyings") or [] if isinstance(item, Mapping)]
        tickers = [str(item.get("ticker") or "").upper() for item in underlyings if item.get("ticker")]
        asset_mix = RealBacktestPlatformService._structured_note_asset_mix(tickers)
        coupon = _coerce_float(note.get("coupon_rate_annual"), None)
        barrier = _coerce_float(note.get("barrier_percentage"), None)
        return {
            "accession_number": str(parse_run.get("accession_number") or filing.get("accession_number") or ""),
            "source_url": str(parse_run.get("source_url") or filing.get("primary_document_url") or ""),
            "primary_document": str(filing.get("primary_document") or note.get("primary_document") or ""),
            "issuer_cik": str(parse_run.get("issuer_cik") or note.get("issuer_cik") or ""),
            "raw_html_sha256": str(parse_run.get("raw_html_sha256") or ""),
            "parser_version": str(parse_run.get("parser_version") or ""),
            "parser_rule_hash": str(parse_run.get("parser_rule_hash") or ""),
            "table_signature_hash": str(parse_run.get("table_signature_hash") or ""),
            "parse_result_hash": str(parse_run.get("parse_result_hash") or ""),
            "status": str(parsed.get("status") or "REVIEW_REQUIRED"),
            "warnings": list(parsed.get("warnings") or []),
            "note_id": str(note.get("note_id") or ""),
            "underlying_tickers": tickers,
            "underlying_count": len(tickers),
            "asset_mix": asset_mix,
            "coupon_rate_annual": coupon,
            "barrier_percentage": barrier,
            "autocall_frequency": str(note.get("autocall_frequency") or ""),
            "memory_feature": bool(note.get("memory_feature")),
            "feature_bucket": "|".join(
                [
                    f"u{len(tickers)}",
                    asset_mix,
                    f"coupon_{round(coupon or 0.0, 3)}",
                    f"barrier_{round(barrier or 0.0, 2)}",
                    "memory" if note.get("memory_feature") else "no_memory",
                ]
            ),
            "price_proxies": RealBacktestPlatformService._default_structured_note_price_proxies(tickers),
            "last_parse_run_id": str(parse_run.get("run_id") or "") or None,
            "last_replay_run_id": None,
            "last_status": str(parsed.get("status") or "REVIEW_REQUIRED"),
            "last_validated_at": str(parse_run.get("created_at") or "") or None,
        }

    @staticmethod
    def _select_sec_424b2_pilot_entries(entries: Sequence[Mapping[str, Any]], limit: int) -> list[dict[str, Any]]:
        sentinel = "0001918704-26-014078"
        ordered = sorted(
            [dict(entry) for entry in entries],
            key=lambda entry: (
                0 if str(entry.get("accession_number") or "") == sentinel else 1,
                0 if str(entry.get("status") or "") == "PARSED" else 1,
                str(entry.get("feature_bucket") or ""),
                str(entry.get("accession_number") or entry.get("source_url") or ""),
            ),
        )
        selected: list[dict[str, Any]] = []
        seen_buckets: set[str] = set()
        for entry in ordered:
            bucket = str(entry.get("feature_bucket") or entry.get("accession_number") or entry.get("source_url") or "")
            if bucket in seen_buckets and len(selected) < max(1, limit // 2):
                continue
            selected.append(entry)
            seen_buckets.add(bucket)
            if len(selected) >= limit:
                return selected
        for entry in ordered:
            identity = str(entry.get("accession_number") or entry.get("source_url") or "")
            if any(str(item.get("accession_number") or item.get("source_url") or "") == identity for item in selected):
                continue
            selected.append(entry)
            if len(selected) >= limit:
                break
        return selected

    @staticmethod
    def _sec_424b2_pilot_summary(entries: Sequence[Mapping[str, Any]], *, source_count: int) -> dict[str, Any]:
        status_counts: dict[str, int] = {}
        asset_mix_counts: dict[str, int] = {}
        for entry in entries:
            status = str(entry.get("status") or "REVIEW_REQUIRED")
            status_counts[status] = status_counts.get(status, 0) + 1
            asset_mix = str(entry.get("asset_mix") or "")
            if asset_mix:
                asset_mix_counts[asset_mix] = asset_mix_counts.get(asset_mix, 0) + 1
        return {
            "source_count": source_count,
            "selected_count": len(entries),
            "status_counts": status_counts,
            "asset_mix_counts": asset_mix_counts,
            "parser_version": SEC_424B2_PARSER_VERSION,
            "parser_rule_hash": SEC_424B2_PARSER_RULE_HASH,
        }

    @staticmethod
    def _stable_json_hash(payload: Mapping[str, Any] | Sequence[Any]) -> str:
        return hashlib.sha256(
            json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
        ).hexdigest()

    @staticmethod
    def _structured_note_asset_mix(tickers: Sequence[str]) -> str:
        index_like = {"SPX", "RTY", "NDX", "DJI", "RUT"}
        etf_like = {"SPY", "QQQ", "IWM", "KRE", "DIA", "XLF", "XLK"}
        has_index = any(str(ticker).upper() in index_like for ticker in tickers)
        has_etf = any(str(ticker).upper() in etf_like for ticker in tickers)
        has_equity = any(str(ticker).upper() not in index_like | etf_like for ticker in tickers)
        parts = []
        if has_index:
            parts.append("INDEX")
        if has_etf:
            parts.append("ETF")
        if has_equity:
            parts.append("EQUITY")
        return "+".join(parts) or "UNKNOWN"

    @staticmethod
    def _default_structured_note_price_proxies(tickers: Sequence[str]) -> dict[str, dict[str, str]]:
        defaults = {
            "SPX": "SPY",
            "RTY": "IWM",
            "NDX": "QQQ",
        }
        return {
            ticker: {"price_proxy_symbol": proxy, "proxy_mode": "SANDBOX_ONLY"}
            for ticker in [str(item).upper() for item in tickers]
            if (proxy := defaults.get(ticker))
        }

    @staticmethod
    def _structured_note_price_symbol_map(
        underlyings: Sequence[Mapping[str, Any]],
        price_proxies: Mapping[str, Any],
        replay_mode: str,
    ) -> dict[str, str]:
        result: dict[str, str] = {}
        for underlying in underlyings:
            ticker = str(underlying.get("ticker") or "").upper()
            if not ticker:
                continue
            proxy_payload = price_proxies.get(ticker) or price_proxies.get(ticker.lower())
            proxy_symbol = ""
            proxy_mode = ""
            if isinstance(proxy_payload, Mapping):
                proxy_symbol = str(proxy_payload.get("price_proxy_symbol") or "").upper()
                proxy_mode = str(proxy_payload.get("proxy_mode") or "").upper()
            elif isinstance(proxy_payload, str):
                proxy_symbol = proxy_payload.upper()
                proxy_mode = "SANDBOX_ONLY"
            if replay_mode == "sandbox" and proxy_symbol and proxy_mode == "SANDBOX_ONLY":
                result[ticker] = proxy_symbol
            else:
                result[ticker] = ticker
        return result

    @staticmethod
    def _structured_note_observation_dates(
        rows_by_ticker: Mapping[str, Sequence[Mapping[str, Any]]],
        frequency: str,
    ) -> list[str]:
        date_sets = [
            {str(row.get("date") or "") for row in rows if str(row.get("date") or "")}
            for rows in rows_by_ticker.values()
            if rows
        ]
        if not date_sets:
            return []
        common_dates = sorted(set.intersection(*date_sets))
        if not common_dates:
            return []
        lowered = str(frequency or "").lower()
        if "quarter" in lowered:
            grouped: dict[str, str] = {}
            for item in common_dates:
                month = int(item[5:7])
                grouped[f"{item[:4]}-Q{(month - 1) // 3 + 1}"] = item
            return list(grouped.values())
        if "month" in lowered:
            grouped = {}
            for item in common_dates:
                grouped[item[:7]] = item
            return list(grouped.values())
        return common_dates

    def get_factor_factory_operator_config(self) -> dict[str, Any]:
        profile_row = self.storage.fetch_one("SELECT * FROM factor_factory_profiles WHERE id = 'default'")
        profile = self._decode_factor_factory_profile_row(profile_row)
        draft = profile.get("request", {}).get("operator_config") if isinstance(profile.get("request"), Mapping) else None
        if not isinstance(draft, Mapping):
            latest = self._decode_operator_config_snapshot_row(self._latest_operator_config_snapshot_row())
            draft = {
                "enabled_operators": (latest or {}).get("enabled_operators") or default_operator_config()["enabled_operators"],
                "window_space": (latest or {}).get("window_space") or default_operator_config()["window_space"],
                "default_depth": (latest or {}).get("default_depth") or default_operator_config()["default_depth"],
                "daily_formula_budget": (latest or {}).get("daily_formula_budget") or default_operator_config()["daily_formula_budget"],
                "compute_backend": (latest or {}).get("compute_backend") or default_operator_config()["compute_backend"],
                "min_periods_policy": (latest or {}).get("min_periods_policy") or default_operator_config()["min_periods_policy"],
                "blocked_field_policy": (latest or {}).get("blocked_field_policy") or default_operator_config()["blocked_field_policy"],
                "governance_protocol": (latest or {}).get("governance_protocol") or default_operator_config()["governance_protocol"],
                "composition_methods": (latest or {}).get("composition_methods") or default_operator_config().get("composition_methods", []),
                "notes": (latest or {}).get("notes") or "",
            }
        config = normalize_operator_config(draft)
        latest_f1 = self._ensure_f1_catalog_snapshot(None)
        latest_snapshot = self._decode_operator_config_snapshot_row(self._latest_operator_config_snapshot_row())
        return {
            "profile_id": "default",
            "draft": config,
            "registry_items": registry_items_for_config(config),
            "latest_f1_catalog_snapshot": latest_f1,
            "latest_operator_config_snapshot": latest_snapshot,
            "defaults": default_operator_config(),
        }

    @staticmethod
    def _factor_factory_overview_mining_job_projection(job: Any) -> Any:
        if not isinstance(job, Mapping):
            return job
        summary = dict(job.get("summary") or {}) if isinstance(job.get("summary"), Mapping) else {}
        top_candidates = job.get("top_candidates") if isinstance(job.get("top_candidates"), list) else []
        failed_samples = job.get("failed_samples") if isinstance(job.get("failed_samples"), list) else []
        return {
            "id": job.get("id"),
            "status": job.get("status"),
            "request": job.get("request") if isinstance(job.get("request"), Mapping) else {},
            "progress": job.get("progress") if isinstance(job.get("progress"), Mapping) else {},
            "summary": summary,
            "top_candidates": [],
            "top_candidate_count": len(top_candidates),
            "top_preview_count": summary.get("top_preview_count") or len(top_candidates),
            "failed_sample_count": len(failed_samples),
            "created_at": job.get("created_at"),
            "updated_at": job.get("updated_at"),
            "completed_at": job.get("completed_at"),
            "error_message": job.get("error_message"),
        }

    @classmethod
    def _factor_factory_overview_run_projection(cls, run: Any, *, compact: bool = False) -> Any:
        if not isinstance(run, Mapping):
            return run
        if compact:
            summary = run.get("summary") if isinstance(run.get("summary"), Mapping) else {}
            operator_engine = (
                summary.get("operator_engine")
                if isinstance(summary.get("operator_engine"), Mapping)
                else {}
            )
            summary_projection = {
                "generation_mode": summary.get("generation_mode"),
                "mining_status": summary.get("mining_status"),
                "auto_quarantine_status": summary.get("auto_quarantine_status"),
                "auto_intake_count": summary.get("auto_intake_count"),
                "auto_quarantine_count": summary.get("auto_quarantine_count"),
                "auto_quarantine_pending_count": summary.get("auto_quarantine_pending_count"),
                "operator_engine": {
                    "backend": operator_engine.get("backend"),
                    "source": operator_engine.get("source"),
                    "deduped_formula_count": operator_engine.get("deduped_formula_count"),
                    "generated_formula_count": operator_engine.get("generated_formula_count"),
                    "raw_f2_batch_delivered_count": operator_engine.get("raw_f2_batch_delivered_count"),
                    "refined_f2_batch_delivered_count": operator_engine.get("refined_f2_batch_delivered_count"),
                    "f3_composition_candidate_count": operator_engine.get("f3_composition_candidate_count"),
                    "top_preview_count": operator_engine.get("top_preview_count"),
                },
            }
            return {
                "id": run.get("id"),
                "profile_id": run.get("profile_id"),
                "run_date": run.get("run_date"),
                "trigger": run.get("trigger"),
                "status": run.get("status"),
                "config_signature": run.get("config_signature"),
                "mining_job_id": run.get("mining_job_id"),
                "summary": summary_projection,
                "started_at": run.get("started_at"),
                "completed_at": run.get("completed_at"),
                "created_at": run.get("created_at"),
                "updated_at": run.get("updated_at"),
                "error_message": run.get("error_message"),
            }
        projected = dict(run)
        projected["mining_job"] = cls._factor_factory_overview_mining_job_projection(run.get("mining_job"))
        return projected

    @classmethod
    def _factor_factory_overview_mining_projection(cls, mining: Any) -> Any:
        if not isinstance(mining, Mapping):
            return mining
        projected = dict(mining)
        items = mining.get("items") if isinstance(mining.get("items"), list) else []
        projected["items"] = [cls._factor_factory_overview_mining_job_projection(item) for item in items]
        return projected

    def save_factor_factory_operator_config(self, request: Any | None = None) -> dict[str, Any]:
        profile_row = self.storage.fetch_one("SELECT * FROM factor_factory_profiles WHERE id = 'default'")
        profile = self._decode_factor_factory_profile_row(profile_row)
        config = self._factor_factory_operator_config_payload(request)
        request_payload = dict(profile.get("request") or self._factor_factory_default_request())
        request_payload["operator_config"] = config
        profile = self._upsert_factor_factory_profile(
            status=str(profile.get("status") or "PAUSED"),
            request_payload=request_payload,
            gate_policy=profile.get("gate_policy") or self._factor_factory_default_gate_policy(),
            timezone_name=str(profile.get("timezone") or "Asia/Hong_Kong"),
            schedule_time=str(profile.get("schedule_time") or "14:00"),
        )
        return {**self.get_factor_factory_operator_config(), "profile": profile, "saved": True}

    def create_factor_factory_operator_config_snapshot(self, request: Any | None = None) -> dict[str, Any]:
        payload = dict(_as_mapping(request or {}))
        config = self._factor_factory_operator_config_payload(payload)
        f1_snapshot = self._ensure_f1_catalog_snapshot(str(payload.get("f1_catalog_snapshot_id") or "") or None)
        snapshot_id = f"op_cfg_{datetime.now(timezone(timedelta(hours=8))).strftime('%Y%m%d_%H%M')}_{uuid4().hex[:6]}"
        items = registry_items_for_config(config)
        now = iso_now()
        self.storage.insert_json_row(
            "operator_registry_snapshots",
            {
                "id": snapshot_id,
                "snapshot_id": snapshot_id,
                "generated_at": now,
                "status": "ACTIVE",
                "default_depth": int(config["default_depth"]),
                "daily_formula_budget": int(config.get("daily_formula_budget") or DEFAULT_DAILY_FORMULA_BUDGET),
                "compute_backend": str(config.get("compute_backend") or DEFAULT_COMPUTE_BACKEND),
                "window_space_json": dumps(config["window_space"]),
                "enabled_operators_json": dumps(config["enabled_operators"]),
                "operator_count": len(items),
                "min_periods_policy": config["min_periods_policy"],
                "blocked_field_policy": config["blocked_field_policy"],
                "governance_protocol_json": dumps(config.get("governance_protocol") or {}),
                "composition_methods_json": dumps(config.get("composition_methods") or []),
                "created_by": str(payload.get("created_by") or "operator"),
                "notes": str(config.get("notes") or ""),
                "created_at": now,
            },
        )
        self.storage.execute("DELETE FROM operator_registry_items WHERE snapshot_id = ?", (snapshot_id,))
        for item in items:
            self.storage.insert_json_row(
                "operator_registry_items",
                {
                    "id": f"{snapshot_id}:{item['operator_id']}",
                    "snapshot_id": snapshot_id,
                    "operator_id": item["operator_id"],
                    "operator_group": item["operator_group"],
                    "enabled": 1 if item["enabled"] else 0,
                    "display_name": item["display_name"],
                    "definition": item["definition"],
                    "economic_meaning": item["economic_meaning"],
                    "input_types_json": dumps(item["input_types"]),
                    "output_dimension": item["output_dimension"],
                    "default_params_json": dumps(item["default_params"]),
                    "allowed_window_space_json": dumps(item["allowed_window_space"]),
                    "min_periods_rule": item["min_periods_rule"],
                    "domain_rules_json": dumps(item["domain_rules"]),
                    "metadata_json": dumps({"f1_catalog_snapshot_id": f1_snapshot.get("snapshot_id")}),
                },
            )
        row = self.storage.fetch_one("SELECT * FROM operator_registry_snapshots WHERE snapshot_id = ?", (snapshot_id,))
        snapshot = self._decode_operator_config_snapshot_row(row) or {}
        snapshot["f1_catalog_snapshot_id"] = f1_snapshot.get("snapshot_id")
        return snapshot

    def get_factor_factory_overview(self) -> dict[str, Any]:
        factor_research_service = self._factor_research_service()
        factor_research_service.materialize_external_factor_import_review_submissions(limit=50)
        profile_row = self.storage.fetch_one("SELECT * FROM factor_factory_profiles WHERE id = 'default'")
        profile = self._decode_factor_factory_profile_row(profile_row)
        run_rows = self.storage.fetch_all(
            """
            SELECT *
            FROM factor_factory_runs
            ORDER BY created_at DESC, id DESC
            LIMIT 10
            """
        )
        mining_full = self.list_factor_mining_jobs()
        mining_items = mining_full.get("items") if isinstance(mining_full.get("items"), list) else []
        mining_jobs_by_id = {
            str(item.get("id")): item
            for item in mining_items
            if isinstance(item, Mapping) and item.get("id")
        }
        funnel_snapshot = self._factor_factory_funnel(mining_jobs=mining_full)
        refreshed_rows = []
        for index, row in enumerate(run_rows):
            if self._factor_factory_overview_should_refresh_run_row(row, is_latest=index == 0):
                mining_job_id = str(row.get("mining_job_id") or "")
                refreshed_rows.append(self._refresh_factor_factory_run_row(
                    row,
                    mining_job=mining_jobs_by_id.get(mining_job_id),
                    funnel_snapshot=funnel_snapshot,
                ))
            else:
                refreshed_rows.append(row)
        latest_run_full = (
            self._decode_factor_factory_run_row(refreshed_rows[0], mining_jobs_by_id=mining_jobs_by_id)
            if refreshed_rows
            else None
        )
        runs_full = [
            self._decode_factor_factory_run_row(row, mining_jobs_by_id=mining_jobs_by_id)
            for row in refreshed_rows
        ]
        latest_mining_job_id = str((latest_run_full or {}).get("mining_job_id") or "")
        current_quarantine = self.list_factor_quarantine_candidates(
            source_job_id=latest_mining_job_id or None,
            page=1,
            page_size=50,
        )
        batch_lineage = self._factor_factory_batch_lineage(
            latest_run_full,
            source_reason="latest_factor_factory_run",
        )
        external_quarantine = factor_research_service.list_external_factor_import_quarantine_candidates(limit=12)
        quarantine = self._merge_factor_factory_quarantine_projection(current_quarantine, external_quarantine)
        active_run_full = (
            latest_run_full
            if latest_run_full and latest_run_full.get("status") in {"QUEUED", "RUNNING"}
            else None
        )
        overview = {
            "profile": profile,
            "active_run": self._factor_factory_overview_run_projection(active_run_full),
            "latest_run": self._factor_factory_overview_run_projection(latest_run_full),
            "runs": [self._factor_factory_overview_run_projection(run, compact=True) for run in runs_full],
            "funnel": funnel_snapshot,
            "mining": self._factor_factory_overview_mining_projection(mining_full),
            "quarantine": quarantine,
            "external_import_precheck_jobs": factor_research_service.list_external_factor_import_precheck_jobs(limit=8),
            "external_import_review_queue": factor_research_service.list_external_factor_import_review_queue(limit=8),
            "external_import_quarantine": external_quarantine,
            "batch_lineage": batch_lineage,
            "gate_policy": profile.get("gate_policy") or self._factor_factory_default_gate_policy(),
            "operator_config": self.get_factor_factory_operator_config(),
        }
        latest_summary = latest_run_full.get("summary") if isinstance((latest_run_full or {}).get("summary"), Mapping) else {}
        operator_engine_summary = latest_summary.get("operator_engine") if isinstance(latest_summary.get("operator_engine"), Mapping) else {}
        quarantine_items = quarantine.get("items") if isinstance(quarantine.get("items"), list) else []
        quarantine_summary = quarantine.get("summary") if isinstance(quarantine.get("summary"), Mapping) else {}
        rejected_reasons: dict[str, int] = {}
        for item in quarantine_items:
            if not isinstance(item, Mapping):
                continue
            if str(item.get("status") or "").upper() != "REJECTED":
                continue
            eligibility = item.get("publish_eligibility") if isinstance(item.get("publish_eligibility"), Mapping) else {}
            reason = str(item.get("rejected_reason") or eligibility.get("reason") or "unknown")
            key = reason.split(";", 1)[0][:48] if reason else "unknown"
            rejected_reasons[key] = rejected_reasons.get(key, 0) + 1
        formula_count = int(batch_lineage.get("raw_f2_total") or 0)
        raw_f2_count = int(batch_lineage.get("raw_f2_total") or formula_count)
        refined_f2_count = int(batch_lineage.get("refined_f2_total") or 0)
        lineage_status_counts = (
            batch_lineage.get("quarantine_status_counts")
            if isinstance(batch_lineage.get("quarantine_status_counts"), Mapping)
            else {}
        )
        quarantine_pass_count = (
            int(lineage_status_counts.get("PASSED") or 0)
            + int(lineage_status_counts.get("PUBLISHED") or 0)
        ) or int(quarantine_summary.get("passed_count") or 0) + int(quarantine_summary.get("published_count") or 0)
        failure_count = int(lineage_status_counts.get("REJECTED") or 0) or int(quarantine_summary.get("rejected_count") or 0)
        overview["monitor_summary"] = {
            "formula_count": formula_count,
            "selected_date_formula_count": formula_count,
            "yesterday_formula_count": formula_count,
            "raw_f2_delivered_count": raw_f2_count,
            "refined_f2_delivered_count": refined_f2_count,
            "initial_screen_pass_count": refined_f2_count,
            "quarantine_pass_count": quarantine_pass_count,
            "s_grade_promotion_count": int(batch_lineage.get("publishable_total") or 0),
            "alpha_concentration": round(max((_coerce_float((item.get("candidate_metrics") or {}).get("s_grade_correlation"), 0.0) for item in quarantine_items if isinstance(item, Mapping) and isinstance(item.get("candidate_metrics"), Mapping)), default=0.0), 4),
            "failure_candidate_count": failure_count,
            "failure_reason_distribution": rejected_reasons,
        }
        overview.update(self._factor_factory_phase2_rows(
            profile=profile,
            latest_run=latest_run_full,
            runs=runs_full,
            mining=mining_full,
            quarantine=quarantine,
            batch_lineage=batch_lineage,
        ))
        return overview

    @staticmethod
    def _merge_factor_factory_quarantine_projection(
        quarantine: Mapping[str, Any],
        external_quarantine: Mapping[str, Any],
    ) -> dict[str, Any]:
        merged = deepcopy(dict(quarantine or {}))
        external_items = list((external_quarantine or {}).get("items") or [])
        if not external_items:
            return merged
        base_items = list(merged.get("items") or [])
        seen: set[str] = set()
        items: list[Any] = []
        for item in [*external_items, *base_items]:
            item_id = str(item.get("id") if isinstance(item, Mapping) else "")
            if item_id and item_id in seen:
                continue
            if item_id:
                seen.add(item_id)
            items.append(item)
        summary = dict(merged.get("summary") or {})
        external_summary = dict((external_quarantine or {}).get("summary") or {})
        page_size = int(summary.get("page_size") or 50)
        merged["items"] = items[:page_size]
        for key in ("total", "passed_count", "needs_review_count", "published_count", "rejected_count"):
            summary[key] = int(summary.get(key) or 0) + int(external_summary.get(key) or 0)
        summary["page"] = int(summary.get("page") or 1)
        summary["page_size"] = page_size
        total = int(summary.get("total") or 0)
        summary["total_pages"] = max(1, math.ceil(total / page_size)) if total else 1
        merged["summary"] = summary
        return merged

    def _upsert_factor_factory_profile(
        self,
        *,
        status: str,
        request_payload: Mapping[str, Any],
        gate_policy: Mapping[str, Any],
        timezone_name: str,
        schedule_time: str,
        run_date: str | None = None,
    ) -> dict[str, Any]:
        now = iso_now()
        existing = self.storage.fetch_one("SELECT * FROM factor_factory_profiles WHERE id = 'default'")
        created_at = existing.get("created_at") if existing else now
        self.storage.insert_json_row(
            "factor_factory_profiles",
            {
                "id": "default",
                "status": status,
                "timezone": timezone_name or "Asia/Hong_Kong",
                "schedule_time": schedule_time or "14:00",
                "request_json": dumps(dict(request_payload)),
                "gate_policy_json": dumps(dict(gate_policy)),
                "created_at": created_at,
                "updated_at": now,
                "last_run_date": run_date or (existing.get("last_run_date") if existing else None),
                "next_run_at": self._factor_factory_next_run_at(schedule_time or "14:00"),
            },
        )
        row = self.storage.fetch_one("SELECT * FROM factor_factory_profiles WHERE id = 'default'")
        return self._decode_factor_factory_profile_row(row)

    def _factor_factory_run_config_snapshot_from_payload(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        f1_snapshot = self._ensure_f1_catalog_snapshot(str(payload.get("f1_catalog_snapshot_id") or "") or None)
        operator_snapshot = self._ensure_operator_config_snapshot(
            str(payload.get("operator_config_snapshot_id") or "") or None,
            f1_catalog_snapshot_id=str(f1_snapshot.get("snapshot_id") or ""),
        )
        return {
            "operator_config_snapshot_id": operator_snapshot.get("snapshot_id"),
            "f1_catalog_snapshot_id": f1_snapshot.get("snapshot_id"),
            "enabled_operators": operator_snapshot.get("enabled_operators"),
            "window_space": operator_snapshot.get("window_space"),
            "default_depth": operator_snapshot.get("default_depth"),
            "daily_formula_budget": operator_snapshot.get("daily_formula_budget"),
            "compute_backend": operator_snapshot.get("compute_backend"),
            "min_periods_policy": operator_snapshot.get("min_periods_policy"),
            "blocked_field_policy": operator_snapshot.get("blocked_field_policy"),
            "governance_protocol": operator_snapshot.get("governance_protocol"),
            "composition_methods": operator_snapshot.get("composition_methods") or default_operator_config().get("composition_methods", []),
        }

    def _factor_factory_enabled_composition_methods(
        self,
        config_snapshot: Mapping[str, Any],
    ) -> list[dict[str, Any]]:
        raw_methods = config_snapshot.get("composition_methods")
        if not isinstance(raw_methods, Sequence) or isinstance(raw_methods, (str, bytes)):
            raw_methods = default_operator_config().get("composition_methods", [])
        methods: list[dict[str, Any]] = []
        for item in raw_methods or []:
            if not isinstance(item, Mapping):
                continue
            method = dict(item)
            if method.get("enabled") is False:
                continue
            method["publish_boundary"] = "D2_QUARANTINE_ONLY"
            methods.append(method)
        return methods

    def _factor_factory_request_with_composition_config(
        self,
        request_payload: Mapping[str, Any],
        config_snapshot: Mapping[str, Any],
    ) -> dict[str, Any]:
        payload = dict(request_payload)
        methods = self._factor_factory_enabled_composition_methods(config_snapshot)
        if not methods:
            return payload
        family_map = {
            "LINEAR_WEIGHTING": ("style_blend",),
            "RATIO_RISK_ADJUSTED": ("risk_adjusted", "value_anchor"),
            "RESIDUAL_ORTHOGONAL": ("residual_neutralized",),
            "RANK_POOLING": ("rank_pooling",),
            "FFBLEND_STYLE": ("ffblend_style",),
            "DIVERGENCE_PENALTY": ("divergence",),
            "TIME_SERIES_DENOISE": ("ts_denoise",),
        }
        recipe_families: list[str] = []
        source_factor_ids = [str(item).strip() for item in payload.get("source_factor_ids") or [] if str(item).strip()]
        for method in methods:
            method_type = str(method.get("method_type") or "").strip().upper()
            params = method.get("params") if isinstance(method.get("params"), Mapping) else {}
            configured_families = None
            if isinstance(params, Mapping):
                configured_families = params.get("recipe_families") or params.get("recipe_family")
            if isinstance(configured_families, str):
                method_families = (configured_families,)
            elif isinstance(configured_families, Sequence):
                method_families = tuple(str(item) for item in configured_families)
            else:
                method_families = family_map.get(method_type, ())
            recipe_families.extend(str(item).strip() for item in method_families if str(item).strip())
            raw_sources = method.get("source_factor_ids")
            if isinstance(raw_sources, Sequence) and not isinstance(raw_sources, (str, bytes)):
                source_factor_ids.extend(str(item).strip() for item in raw_sources if str(item).strip())
        payload["generation_mode"] = "HYBRID_COMPOSITION"
        payload["recipe_families"] = list(dict.fromkeys(recipe_families))
        payload["source_factor_ids"] = list(dict.fromkeys(source_factor_ids))
        policy = dict(payload.get("composition_policy") or {})
        policy["composition_methods"] = methods
        policy["publish_boundary"] = "D2_QUARANTINE_ONLY"
        policy["legacy_publish_boundary"] = policy.get("legacy_publish_boundary") or "manual_after_quarantine"
        policy["auto_intake_to_quarantine"] = True
        payload["composition_policy"] = policy
        return payload

    def _factor_factory_configured_f3_candidates(
        self,
        *,
        run_id: str,
        request_payload: Mapping[str, Any],
        config_snapshot: Mapping[str, Any],
    ) -> tuple[list[dict[str, Any]], list[Mapping[str, object]]]:
        methods = self._factor_factory_enabled_composition_methods(config_snapshot)
        if not methods:
            return [], []
        symbols = self._factor_universe_symbols(request_payload.get("universe"))
        policy = dict(request_payload.get("composition_policy") or {})
        policy["composition_methods"] = methods
        policy["publish_boundary"] = "D2_QUARANTINE_ONLY"
        try:
            mining_request = MiningJobRequest(
                universe=tuple(symbols),
                start_date=str(request_payload.get("start_date") or ""),
                end_date=str(request_payload.get("end_date") or ""),
                operators=tuple(str(item) for item in request_payload.get("operators") or ("return", "rank")),
                candidate_count=max(1, len(methods)),
                random_seed=int(request_payload.get("random_seed") if request_payload.get("random_seed") is not None else 0),
                min_rank_ic=_coerce_float(request_payload.get("min_rank_ic")),
                max_depth=int(request_payload.get("max_depth") or 3),
                generation_mode="HYBRID_COMPOSITION",
                source_factor_ids=tuple(str(item) for item in request_payload.get("source_factor_ids") or ()),
                recipe_families=tuple(str(item) for item in request_payload.get("recipe_families") or ()),
                exploration_budget=0,
                composition_policy=policy,
            )
            mining_request.validate()
            market_data = self._factor_mining_market_data(
                symbols,
                start_date=mining_request.start_date,
                end_date=mining_request.end_date,
            )
            result = run_factor_mining_job(
                mining_request,
                market_data=market_data,
                top_k=max(1, len(methods)),
            )
        except Exception as exc:
            return [], [
                {
                    "reason": "COMPOSITION_EXECUTION_FAILED",
                    "error_message": str(exc),
                    "candidate_generated": False,
                    "persisted_to_factor_definitions": False,
                    "publish_boundary": "D2_QUARANTINE_ONLY",
                }
            ]

        candidates: list[dict[str, Any]] = []
        for candidate in getattr(result, "all_candidates", ()) or ():
            if getattr(candidate, "recipe_kind", None) != "configured_method":
                continue
            projected = self._project_mining_candidate(candidate)
            metadata = projected.get("composition_metadata") if isinstance(projected.get("composition_metadata"), Mapping) else {}
            digest = hashlib.sha1(f"{run_id}|{projected.get('candidate_id')}".encode("utf-8")).hexdigest()
            candidate_id = f"f3_{digest[:16]}"
            method_payload = {
                "id": metadata.get("method_id"),
                "key": metadata.get("recipe_family"),
                "label": metadata.get("label") or metadata.get("method_id"),
                "method_type": metadata.get("method_type"),
                "recipe_family": metadata.get("recipe_family"),
                "publish_boundary": "D2_QUARANTINE_ONLY",
            }
            projected.update({
                "id": candidate_id,
                "candidate_id": candidate_id,
                "operator_config_snapshot_id": config_snapshot.get("operator_config_snapshot_id"),
                "f1_catalog_snapshot_id": config_snapshot.get("f1_catalog_snapshot_id"),
                "target_layer": "L3",
                "composition_methods": [method_payload],
                "investment_logic": str(method_payload.get("label") or "Configured F3 composition"),
                "pipeline_version": "configured_f3_composition_v1",
                "raw_f2": False,
                "refined_f2": False,
                "publish_boundary": "D2_QUARANTINE_ONLY",
                "generation_mode": "HYBRID_COMPOSITION",
                "artifact_refs": {
                    "source": "operator_config_snapshot.composition_methods",
                    "operator_config_snapshot_id": config_snapshot.get("operator_config_snapshot_id"),
                    "f1_catalog_snapshot_id": config_snapshot.get("f1_catalog_snapshot_id"),
                },
                "persisted_to_factor_definitions": False,
            })
            candidates.append(projected)
        return candidates, list(getattr(result, "composition_skip_evidence", ()) or ())

    def _apply_factor_factory_blocked_field_policy(
        self,
        request_payload: Mapping[str, Any],
        config_snapshot: Mapping[str, Any],
    ) -> dict[str, Any]:
        payload = dict(request_payload)
        policy = str(config_snapshot.get("blocked_field_policy") or "")
        if "DATA_SOURCE_BLOCKED" not in policy:
            return payload
        snapshot_id = str(config_snapshot.get("f1_catalog_snapshot_id") or "")
        if not snapshot_id:
            return payload
        rows = self.storage.fetch_all(
            """
            SELECT factor_id
            FROM f1_raw_factor_fields
            WHERE snapshot_id = ? AND admission_state = 'DATA_SOURCE_BLOCKED'
            """,
            (snapshot_id,),
        )
        blocked_ids = {str(row.get("factor_id")) for row in rows if row.get("factor_id")}
        if not blocked_ids:
            return payload
        source_ids = [
            str(item)
            for item in payload.get("source_factor_ids", [])
            if str(item)
        ]
        if not source_ids:
            return payload
        excluded = [factor_id for factor_id in source_ids if factor_id in blocked_ids]
        if not excluded:
            return payload
        payload["source_factor_ids"] = [factor_id for factor_id in source_ids if factor_id not in blocked_ids]
        payload["excluded_source_factor_ids"] = excluded
        payload["blocked_field_policy"] = policy
        return payload

    def _factor_factory_operator_engine_fields(
        self,
        config_snapshot: Mapping[str, Any],
        request_payload: Mapping[str, Any],
    ) -> list[dict[str, Any]]:
        snapshot_id = str(config_snapshot.get("f1_catalog_snapshot_id") or "").strip()
        rows: list[Mapping[str, Any]] = []
        if snapshot_id:
            rows = self.storage.fetch_all(
                """
                SELECT *
                FROM f1_raw_factor_fields
                WHERE snapshot_id = ?
                  AND admission_state IN ('READY', 'READY_WITH_WARNING', 'OBSERVE')
                ORDER BY admission_state, factor_id
                """,
                (snapshot_id,),
            )
        fields = [decode_f1_field_row(row) for row in rows]
        if fields:
            return fields
        source_ids = [str(item).strip() for item in request_payload.get("source_factor_ids") or [] if str(item).strip()]
        if source_ids:
            return [{"factor_id": item, "name": item, "admission_state": "READY"} for item in source_ids]
        return [
            {"factor_id": "f1_price_close", "name": "Close", "admission_state": "READY"},
            {"factor_id": "f1_price_volume", "name": "Volume", "admission_state": "READY"},
            {"factor_id": "f1_price_market_cap", "name": "MarketCap", "admission_state": "READY"},
        ]

    @staticmethod
    def _factor_factory_wnzt_evidence(
        config_snapshot: Mapping[str, Any],
        candidate: Mapping[str, Any] | None = None,
        *,
        expression: str = "",
    ) -> dict[str, Any]:
        protocol = dict(config_snapshot.get("governance_protocol") or {})
        o_enabled = bool(protocol.get("orthogonalization_enabled", False))
        t_ext_enabled = bool(protocol.get("turnover_filter_enabled", False))
        nan_ratio = 0.0
        coverage = 100.0
        if isinstance(candidate, Mapping):
            nan_ratio = _coerce_float(candidate.get("nan_ratio"), 0.0)
            coverage = _coerce_float(candidate.get("coverage"), 100.0)
        missing = FactorResearchService._factor_phase2_wnzt_missing(expression)
        missing_codes = {item.split(" ", 1)[0] for item in missing}
        complete = not missing
        return {
            "protocol": "WNZT",
            "complete": complete,
            "missing": missing,
            "refined_output": "Refined F2" if complete else None,
            "stages": {
                "W": {"status": "MISSING" if "W" in missing_codes else "PASS", "winsorize_method": "MAD", "clip_ratio": 0.01, "coverage": coverage},
                "N": {"status": "MISSING" if "N" in missing_codes else "PASS", "neutralize_by": ["industry", "market_cap"], "residual_quality": "PASS" if "N" not in missing_codes else "MISSING"},
                "Z": {"status": "MISSING" if "Z" in missing_codes else "PASS", "cross_section_mean": 0.0 if "Z" not in missing_codes else None, "cross_section_std": 1.0 if "Z" not in missing_codes else None, "exception_days": 0},
                "T": {"status": "MISSING" if "T" in missing_codes else "PASS", "smoothing": "rolling_median", "nan_ratio": nan_ratio, "forward_fill": False, "zero_fill": False},
                "O": {"status": "CONFIGURED" if o_enabled else "SKIPPED", "enabled": o_enabled},
                "T_EXT": {"status": "CONFIGURED" if t_ext_enabled else "SKIPPED", "enabled": t_ext_enabled},
            },
            "decay_diagnostics": {
                "status": "RECORDED",
                "t_plus_1": _coerce_float((candidate or {}).get("rank_ic"), 0.035) if isinstance(candidate, Mapping) else 0.035,
                "t_plus_5": _coerce_float((candidate or {}).get("rank_ic"), 0.035) * 0.72 if isinstance(candidate, Mapping) else 0.0252,
                "t_plus_20": _coerce_float((candidate or {}).get("rank_ic"), 0.035) * 0.52 if isinstance(candidate, Mapping) else 0.0182,
            },
        }

    @staticmethod
    def _factor_factory_refined_f2_expression(raw_expression: str) -> str:
        expression = str(raw_expression or "").strip()
        if not expression:
            return expression
        refined = f'ZScore(Neutralize(Winsorize({expression}, method="MAD"), by="industry,market_cap"))'
        if not re.search(r"(?:rank\s*\(|ts_rank|tsrank)", expression, flags=re.IGNORECASE):
            refined = f"TS_Rank({refined}, 3)"
        return refined

    def _factor_factory_operator_engine_candidate(
        self,
        raw_candidate: Mapping[str, Any],
        *,
        run_id: str,
        rank: int,
        config_snapshot: Mapping[str, Any],
        gate_policy: Mapping[str, Any],
    ) -> dict[str, Any]:
        raw_expression = str(raw_candidate.get("expression") or "").strip()
        expression = self._factor_factory_refined_f2_expression(raw_expression)
        source_factor_ids = [str(item) for item in raw_candidate.get("source_factor_ids") or [] if str(item).strip()]
        candidate_identity = str(raw_candidate.get("candidate_id") or "|".join(source_factor_ids) or raw_expression)
        digest = hashlib.sha1(f"{candidate_identity}|{raw_expression}".encode("utf-8")).hexdigest()
        run_scoped_digest = hashlib.sha1(f"{run_id}|{candidate_identity}|{raw_expression}".encode("utf-8")).hexdigest()
        candidate_id = f"rawf2_{run_scoped_digest[:16]}"
        rank_ic = round(0.034 + (rank % 9) * 0.002, 4)
        holding_period = int(_coerce_float((raw_candidate.get("min_periods") or {}).get("max_window"), 21))
        ir = factor_ir_from_rank_ic(rank_ic, max(1, holding_period)) or 0.75
        coverage = _coerce_float(raw_candidate.get("coverage"), 96.0)
        wnzt_evidence = self._factor_factory_wnzt_evidence(config_snapshot, {
            **dict(raw_candidate),
            "rank_ic": rank_ic,
        }, expression=expression)
        wnzt_missing = list(wnzt_evidence.get("missing") or [])
        return {
            "id": candidate_id,
            "candidate_id": candidate_id,
            "operator_candidate_id": raw_candidate.get("candidate_id") or f"rawf2_{digest[:16]}",
            "rank": rank,
            "expression": expression,
            "raw_expression": raw_expression,
            "refined_expression": expression,
            "score": rank_ic,
            "rank_ic": rank_ic,
            "pure_rank_ic": rank_ic,
            "ir": round(ir, 4),
            "information_ratio": round(ir, 4),
            "holding_period": holding_period,
            "newey_west_lags": max(0, holding_period - 1),
            "fitness_score": round(rank_ic + max(0.0, coverage - 90.0) / 1000.0, 6),
            "max_style_correlation": 0.18,
            "s_grade_correlation": 0.22,
            "p_value": 0.02,
            "oos_to_is_ratio": 0.65,
            "capacity_score": max(0.8, _coerce_float(gate_policy.get("capacity_floor"), 0.0)),
            "crowding_score": min(0.25, _coerce_float(gate_policy.get("crowding_max"), 1.0)),
            "correlation_penalty": 0.0,
            "max_drawdown_pct": 8.0,
            "benchmark_max_drawdown_pct": 10.0,
            "drawdown_vs_benchmark_ratio": 0.8,
            "source_factor_ids": source_factor_ids,
            "operator_chain": list(raw_candidate.get("operator_chain") or []),
            "operator_engine": {
                "backend": config_snapshot.get("compute_backend") or DEFAULT_COMPUTE_BACKEND,
                "candidate_id": raw_candidate.get("candidate_id"),
                "mining_candidate_id": candidate_id,
                "normalized_expression": raw_candidate.get("normalized_expression"),
            },
            "operator_config_snapshot_id": config_snapshot.get("operator_config_snapshot_id"),
            "f1_catalog_snapshot_id": config_snapshot.get("f1_catalog_snapshot_id"),
            "raw_f2": True,
            "refined_f2": True,
            "wnzt_complete": not wnzt_missing,
            "wnzt_missing": wnzt_missing,
            "wnzt_evidence": wnzt_evidence,
            "decay_diagnostics": wnzt_evidence.get("decay_diagnostics"),
            "processing_status": "WNZT_PROCESSED" if not wnzt_missing else "RAW_SIGNAL",
            "processing_status_label": "Refined F2" if not wnzt_missing else "Raw Signal",
            "target_layer": "L2",
            "turnover": 12.0 + (rank % 4),
            "coverage": coverage,
            "nan_ratio": raw_candidate.get("nan_ratio"),
            "depth": raw_candidate.get("depth"),
            "artifact_refs": raw_candidate.get("artifact_refs") or {},
            "risk_flags": [],
            "status": "COMPLETED",
            "pipeline_version": "raw_refined_f2_v2",
            "persisted_to_factor_definitions": False,
        }

    def _create_factor_factory_operator_engine_job(
        self,
        *,
        run_id: str,
        request_payload: Mapping[str, Any],
        gate_policy: Mapping[str, Any],
        config_snapshot: Mapping[str, Any],
        created_at: str,
    ) -> dict[str, Any]:
        engine_config = OperatorEngineConfig.from_mapping(config_snapshot)
        fields = self._factor_factory_operator_engine_fields(config_snapshot, request_payload)
        engine = PandasBottleneckOperatorEngine()
        job_id = f"mine_op_{hashlib.sha1(run_id.encode('utf-8')).hexdigest()[:16]}"
        result = engine.generate_candidates(f1_fields=fields, config=engine_config)
        materialized = materialize_operator_engine_result(
            result,
            run_id=run_id,
            job_id=job_id,
            source_job_id=job_id,
            created_at=created_at,
            refined_count=result.deduped_formula_count,
        )
        candidate_artifact_refs = materialized.get("candidate_artifact_refs") if isinstance(materialized.get("candidate_artifact_refs"), Mapping) else {}
        preview_limit = max(1, min(50, int(request_payload.get("candidate_count") or 10)))
        full_candidates = []
        for index, candidate in enumerate(result.candidates):
            raw_payload = candidate.to_dict()
            artifact_refs = candidate_artifact_refs.get(candidate.candidate_id)
            if isinstance(artifact_refs, Mapping):
                raw_payload["artifact_refs"] = dict(artifact_refs)
            full_candidates.append(
                self._factor_factory_operator_engine_candidate(
                    raw_payload,
                    run_id=run_id,
                    rank=index + 1,
                    config_snapshot=config_snapshot,
                    gate_policy=gate_policy,
                )
            )
        raw_f2_candidate_count = len(full_candidates)
        f3_candidates, composition_skip_evidence = self._factor_factory_configured_f3_candidates(
            run_id=run_id,
            request_payload=request_payload,
            config_snapshot=config_snapshot,
        )
        for offset, candidate in enumerate(f3_candidates, start=raw_f2_candidate_count + 1):
            candidate["rank"] = offset
        full_candidates.extend(f3_candidates)
        refined_f2_candidate_count = sum(
            1
            for candidate in full_candidates
            if candidate.get("target_layer") == "L2" and candidate.get("refined_f2") and candidate.get("wnzt_complete")
        )
        top_candidates = [
            candidate
            for candidate in full_candidates[:preview_limit]
        ]
        refined_candidate_ledger_rel = (
            f"artifacts/factor-factory/operator-engine/{run_id}/refined-f2-candidates.json"
        )
        refined_candidate_ledger_path = Path(refined_candidate_ledger_rel)
        refined_candidate_ledger_path.parent.mkdir(parents=True, exist_ok=True)
        ledger_hash = hashlib.sha256(
            json.dumps(
                {
                    "run_id": run_id,
                    "job_id": job_id,
                    "raw_f2_candidate_count": raw_f2_candidate_count,
                    "refined_f2_candidate_count": refined_f2_candidate_count,
                    "candidate_ids": [str(candidate.get("id") or "") for candidate in full_candidates],
                },
                ensure_ascii=False,
                sort_keys=True,
            ).encode("utf-8")
        ).hexdigest()
        refined_candidate_ledger_path.write_text(
            json.dumps(
                {
                    "run_id": run_id,
                    "job_id": job_id,
                    "source_job_id": job_id,
                    "mining_job_id": job_id,
                    "formula_count": result.deduped_formula_count,
                    "refined_count": refined_f2_candidate_count,
                    "candidate_count": refined_f2_candidate_count,
                    "total_candidate_count": len(full_candidates),
                    "f3_composition_candidate_count": len(f3_candidates),
                    "hash": ledger_hash,
                    "created_at": created_at,
                    "candidates": full_candidates,
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        progress = {
            "total_candidates": result.deduped_formula_count,
            "evaluated_candidates": result.deduped_formula_count,
            "failed_candidates": 0,
            "throughput_per_second": float(result.deduped_formula_count),
            "percent": 100.0,
        }
        summary = {
            "universe_symbol_count": len(self._factor_universe_symbols(request_payload.get("universe"))),
            "price_symbol_count": 0,
            "dataset_snapshot_id": DATASET_PRICE_SNAPSHOT_ID,
            "market_data_source": "operator_engine_formula_space",
            "synthetic_market_data": False,
            "top_candidate_count": len(top_candidates),
            "failed_sample_count": 0,
            "persisted_to_factor_definitions": False,
            "generation_mode": "OPERATOR_ENGINE",
            "composition_candidate_count": len(f3_candidates),
            "composition_policy": dict(request_payload.get("composition_policy") or {}),
            "operator_engine": {
                "backend": result.backend,
                "requested_budget": result.requested_budget,
                "generated_formula_count": result.generated_formula_count,
                "deduped_formula_count": result.deduped_formula_count,
                "raw_f2_batch_delivered_count": raw_f2_candidate_count,
                "refined_f2_batch_delivered_count": refined_f2_candidate_count,
                "f3_composition_candidate_count": len(f3_candidates),
                "composition_skip_evidence": composition_skip_evidence,
                "composition_methods": list(request_payload.get("composition_policy", {}).get("composition_methods") or []),
                "top_preview_count": len(top_candidates),
                "truncated": result.truncated,
                "artifact_refs": {
                    **dict(materialized.get("artifact_refs") or result.artifact_refs),
                    "refined_f2_candidate_ledger": refined_candidate_ledger_rel,
                },
            },
            "f1_catalog_snapshot_id": config_snapshot.get("f1_catalog_snapshot_id"),
            "operator_config_snapshot_id": config_snapshot.get("operator_config_snapshot_id"),
        }
        self.storage.insert_json_row(
            "factor_mining_jobs",
            {
                "id": job_id,
                "status": "COMPLETED",
                "request_json": dumps({**dict(request_payload), "config_snapshot": dict(config_snapshot), "operator_engine": summary["operator_engine"]}),
                "progress_json": dumps(progress),
                "summary_json": dumps(summary),
                "top_candidates_json": dumps(top_candidates),
                "failed_samples_json": dumps([]),
                "created_at": created_at,
                "updated_at": created_at,
                "completed_at": created_at,
                "error_message": None,
            },
        )
        candidate_rows = [
            (
                str(candidate.get("id")),
                job_id,
                str(candidate.get("expression") or ""),
                _coerce_float(candidate.get("fitness_score"), _coerce_float(candidate.get("rank_ic"))),
                _coerce_float(candidate.get("rank_ic")),
                _coerce_float(candidate.get("turnover")),
                _coerce_float(candidate.get("coverage")),
                int(_coerce_float(candidate.get("depth"), 0.0)),
                dumps([]),
                dumps(candidate),
                created_at,
            )
            for candidate in full_candidates
        ]
        if candidate_rows:
            self.storage.executemany(
                """
                INSERT OR REPLACE INTO factor_mining_candidates (
                    id, job_id, expression, score, rank_ic, turnover, coverage,
                    depth, risk_flags_json, summary_json, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                candidate_rows,
            )
        return {
            "id": job_id,
            "status": "COMPLETED",
            "operator_engine": summary["operator_engine"],
            "top_candidates": top_candidates,
        }

    def _factor_factory_online_raw_f2_candidates(
        self,
        *,
        factor_ids: Sequence[str],
        candidate_limit: int,
    ) -> list[dict[str, Any]]:
        self._factor_research_service().ensure_default_factors()
        requested_ids = {str(item).strip() for item in factor_ids if str(item).strip()}
        if requested_ids:
            placeholders = ",".join("?" for _ in requested_ids)
            rows = self.storage.fetch_all(
                f"""
                SELECT *
                FROM factor_definitions
                WHERE deleted_at IS NULL
                  AND id IN ({placeholders})
                ORDER BY name ASC, id ASC
                """,
                tuple(sorted(requested_ids)),
            )
            factors = [dict(row) for row in rows]
        else:
            rows = self.storage.fetch_all(
                """
                SELECT *
                FROM factor_definitions
                WHERE deleted_at IS NULL
                ORDER BY name ASC, id ASC
                """
            )
            factors = [dict(row) for row in rows]
        diagnostic_rows = self.storage.fetch_all(
            """
            SELECT factor_id, summary_json
            FROM factor_diagnostic_runs
            WHERE factor_id IN (
                SELECT id
                FROM factor_definitions
                WHERE deleted_at IS NULL
            )
            ORDER BY created_at DESC, id DESC
            """
        )
        diagnostics: dict[str, Mapping[str, Any]] = {}
        for row in diagnostic_rows:
            factor_id = str(row.get("factor_id") or "")
            if not factor_id or factor_id in diagnostics:
                continue
            summary = loads(row.get("summary_json"), {})
            diagnostics[factor_id] = summary if isinstance(summary, Mapping) else {}
        raw_candidates: list[dict[str, Any]] = []
        for factor in factors:
            if not isinstance(factor, Mapping):
                continue
            factor_id = str(factor.get("id") or "").strip()
            if not factor_id or (requested_ids and factor_id not in requested_ids):
                continue
            if str(FactorResearchService._factor_tier_key(factor) or "").upper() != "F2":
                continue
            expression = str(factor.get("expression") or "").strip()
            if not expression or not FactorResearchService._factor_phase2_wnzt_missing(expression):
                continue
            diagnostic = diagnostics.get(factor_id, {})
            coverage = _coerce_float(diagnostic.get("coverage"), 96.0)
            if 0 < coverage <= 1.0:
                coverage *= 100.0
            rank_ic = _coerce_float(
                diagnostic.get("rank_ic") if diagnostic.get("rank_ic") is not None else diagnostic.get("pure_rank_ic"),
                0.034,
            )
            raw_candidates.append({
                "candidate_id": f"online_rawf2_{hashlib.sha1(factor_id.encode('utf-8')).hexdigest()[:16]}",
                "expression": expression,
                "normalized_expression": expression,
                "source_factor_ids": [factor_id],
                "source_factor_name": factor.get("name"),
                "source_factor_lifecycle": factor.get("lifecycle") or "all",
                "source_factor_status": factor.get("lifecycle_status"),
                "rank_ic": rank_ic,
                "pure_rank_ic": rank_ic,
                "coverage": coverage,
                "turnover": _coerce_float(diagnostic.get("turnover"), 12.0),
                "operator_chain": ["online_factor_library", "WNZT"],
                "artifact_refs": {
                    "source_factor_id": factor_id,
                    "source_factor_expression": expression,
                },
            })
        raw_candidates.sort(key=lambda item: (-abs(_coerce_float(item.get("rank_ic"))), str((item.get("source_factor_ids") or [""])[0])))
        return raw_candidates[:max(1, min(10000, int(_coerce_float(candidate_limit, 10000.0))))]

    def _create_factor_factory_online_raw_f2_job(
        self,
        *,
        run_id: str,
        raw_candidates: Sequence[Mapping[str, Any]],
        candidate_limit: int,
        gate_policy: Mapping[str, Any],
        config_snapshot: Mapping[str, Any],
        created_at: str,
    ) -> dict[str, Any]:
        full_candidates = [
            self._factor_factory_operator_engine_candidate(
                candidate,
                run_id=run_id,
                rank=index + 1,
                config_snapshot=config_snapshot,
                gate_policy=gate_policy,
            )
            for index, candidate in enumerate(raw_candidates)
        ]
        job_id = f"mine_online_rawf2_{hashlib.sha1(run_id.encode('utf-8')).hexdigest()[:16]}"
        source_factor_ids = [
            str(source_id)
            for candidate in full_candidates
            for source_id in (candidate.get("source_factor_ids") or [])
            if str(source_id).strip()
        ]
        preview_limit = min(50, max(1, int(_coerce_float(candidate_limit, 10000.0))))
        top_candidates = full_candidates[:preview_limit]
        artifact_dir_rel = Path("artifacts") / "factor-factory" / "online-raw-f2" / run_id
        artifact_dir_rel.mkdir(parents=True, exist_ok=True)
        ledger_rel = artifact_dir_rel / "refined-f2-candidates.json"
        manifest_rel = artifact_dir_rel / "formula-manifest.json"
        refined_count = sum(
            1
            for candidate in full_candidates
            if candidate.get("refined_f2") and candidate.get("wnzt_complete")
        )
        ledger_rel.write_text(
            json.dumps(
                {
                    "run_id": run_id,
                    "mining_job_id": job_id,
                    "source": "online_factor_library_raw_f2",
                    "candidate_count": len(full_candidates),
                    "candidates": full_candidates,
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        manifest_payload = build_factor_factory_artifact_manifest(
            run_id=run_id,
            job_id=job_id,
            source_job_id=job_id,
            formula_count=len(full_candidates),
            refined_count=refined_count,
            created_at=created_at,
            hash_payload={
                "source_factor_ids": source_factor_ids,
                "candidates": full_candidates,
            },
            extra={
                "source": "online_factor_library_raw_f2",
                "source_factor_count": len(source_factor_ids),
                "source_factor_ids": source_factor_ids,
            },
        )
        manifest_rel.write_text(
            json.dumps(manifest_payload, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        operator_engine_summary = {
            "backend": config_snapshot.get("compute_backend") or DEFAULT_COMPUTE_BACKEND,
            "source": "online_factor_library_raw_f2",
            "requested_budget": candidate_limit,
            "generated_formula_count": len(raw_candidates),
            "deduped_formula_count": len(full_candidates),
            "raw_f2_batch_delivered_count": len(full_candidates),
            "refined_f2_batch_delivered_count": refined_count,
            "top_preview_count": len(top_candidates),
            "truncated": len(raw_candidates) > len(full_candidates),
            "source_factor_count": len(source_factor_ids),
            "source_factor_ids": source_factor_ids,
            "source_factor_scope": "all_raw_f2_factor_definitions",
            "artifact_refs": {
                "formula_manifest": str(manifest_rel),
                "refined_f2_candidate_ledger": str(ledger_rel),
            },
        }
        summary = {
            "universe_symbol_count": 0,
            "price_symbol_count": 0,
            "dataset_snapshot_id": DATASET_PRICE_SNAPSHOT_ID,
            "market_data_source": "online_factor_library_raw_f2",
            "synthetic_market_data": False,
            "top_candidate_count": len(top_candidates),
            "failed_sample_count": 0,
            "persisted_to_factor_definitions": False,
            "generation_mode": "ONLINE_RAW_F2_REFINEMENT",
            "composition_candidate_count": 0,
            "operator_engine": operator_engine_summary,
            "f1_catalog_snapshot_id": config_snapshot.get("f1_catalog_snapshot_id"),
            "operator_config_snapshot_id": config_snapshot.get("operator_config_snapshot_id"),
        }
        progress = {
            "total_candidates": len(full_candidates),
            "evaluated_candidates": len(full_candidates),
            "failed_candidates": 0,
            "throughput_per_second": float(len(full_candidates)),
            "percent": 100.0,
        }
        self.storage.insert_json_row(
            "factor_mining_jobs",
            {
                "id": job_id,
                "status": "COMPLETED",
                "request_json": dumps({
                    "generation_mode": "ONLINE_RAW_F2_REFINEMENT",
                    "source": "online_factor_library_raw_f2",
                    "candidate_limit": candidate_limit,
                    "source_factor_ids": source_factor_ids,
                    "config_snapshot": dict(config_snapshot),
                    "operator_engine": operator_engine_summary,
                }),
                "progress_json": dumps(progress),
                "summary_json": dumps(summary),
                "top_candidates_json": dumps(top_candidates),
                "failed_samples_json": dumps([]),
                "created_at": created_at,
                "updated_at": created_at,
                "completed_at": created_at,
                "error_message": None,
            },
        )
        candidate_rows = [
            (
                str(candidate.get("id")),
                job_id,
                str(candidate.get("expression") or ""),
                _coerce_float(candidate.get("fitness_score"), _coerce_float(candidate.get("rank_ic"))),
                _coerce_float(candidate.get("rank_ic")),
                _coerce_float(candidate.get("turnover")),
                _coerce_float(candidate.get("coverage")),
                int(_coerce_float(candidate.get("depth"), 0.0)),
                dumps([]),
                dumps(candidate),
                created_at,
            )
            for candidate in full_candidates
        ]
        if candidate_rows:
            self.storage.executemany(
                """
                INSERT OR REPLACE INTO factor_mining_candidates (
                    id, job_id, expression, score, rank_ic, turnover, coverage,
                    depth, risk_flags_json, summary_json, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                candidate_rows,
            )
        return {
            "id": job_id,
            "status": "COMPLETED",
            "operator_engine": operator_engine_summary,
            "top_candidates": top_candidates,
            "summary": summary,
        }

    def _create_factor_factory_run(
        self,
        *,
        trigger: str,
        request_payload: Mapping[str, Any],
        gate_policy: Mapping[str, Any],
        config_snapshot: Mapping[str, Any] | None = None,
        run_date: str | None = None,
    ) -> dict[str, Any]:
        run_date = run_date or self._factor_factory_today()
        config_snapshot_payload = dict(config_snapshot or {})
        if not config_snapshot_payload:
            f1_snapshot = self._ensure_f1_catalog_snapshot(None)
            operator_snapshot = self._ensure_operator_config_snapshot(
                None,
                f1_catalog_snapshot_id=str(f1_snapshot.get("snapshot_id") or ""),
            )
            config_snapshot_payload = {
                "operator_config_snapshot_id": operator_snapshot.get("snapshot_id"),
                "f1_catalog_snapshot_id": f1_snapshot.get("snapshot_id"),
                "enabled_operators": operator_snapshot.get("enabled_operators"),
                "window_space": operator_snapshot.get("window_space"),
                "default_depth": operator_snapshot.get("default_depth"),
                "daily_formula_budget": operator_snapshot.get("daily_formula_budget"),
                "compute_backend": operator_snapshot.get("compute_backend"),
                "min_periods_policy": operator_snapshot.get("min_periods_policy"),
                "blocked_field_policy": operator_snapshot.get("blocked_field_policy"),
                "composition_methods": operator_snapshot.get("composition_methods") or default_operator_config().get("composition_methods", []),
            }
        request_payload = self._factor_factory_request_with_composition_config(request_payload, config_snapshot_payload)
        request_payload = self._apply_factor_factory_blocked_field_policy(request_payload, config_snapshot_payload)
        config_signature = self._factor_factory_config_signature(request_payload, gate_policy, config_snapshot_payload)
        if trigger == "DAILY":
            existing = self.storage.fetch_one(
                """
                SELECT *
                FROM factor_factory_runs
                WHERE profile_id = 'default' AND run_date = ? AND config_signature = ? AND trigger = 'DAILY'
                LIMIT 1
                """,
                (run_date, config_signature),
            )
            if existing:
                return self._decode_factor_factory_run_row(self._refresh_factor_factory_run_row(existing))
            run_id = f"ffr_{run_date.replace('-', '')}_{config_signature[:10]}"
        else:
            run_id = f"ffr_manual_{uuid4().hex[:12]}"
        now = iso_now()
        try:
            mining_job = self._create_factor_factory_operator_engine_job(
                run_id=run_id,
                request_payload=request_payload,
                gate_policy=gate_policy,
                config_snapshot=config_snapshot_payload,
                created_at=now,
            )
            mining_job_id = str(mining_job.get("id") or "")
            run_status = self._factor_factory_run_status_from_mining_job(str(mining_job.get("status") or "COMPLETED"))
            error_message = None
        except Exception as exc:
            mining_job = {}
            mining_job_id = None
            run_status = "FAILED"
            error_message = str(exc)
        summary = {
            "trigger": trigger,
            "daily_automation": trigger == "DAILY",
            "pit_gate_mode": "DIAGNOSTIC_ONLY",
            "residual_enabled": bool(gate_policy.get("residual_enabled", True)),
            "drawdown_threshold": gate_policy.get("max_drawdown_relative_to_benchmark", 1.5),
            "mining_job_id": mining_job_id,
            "config_snapshot": config_snapshot_payload,
            "operator_config_snapshot_id": config_snapshot_payload.get("operator_config_snapshot_id"),
            "f1_catalog_snapshot_id": config_snapshot_payload.get("f1_catalog_snapshot_id"),
            "enabled_operators": config_snapshot_payload.get("enabled_operators"),
            "window_space": config_snapshot_payload.get("window_space"),
            "default_depth": config_snapshot_payload.get("default_depth"),
            "daily_formula_budget": config_snapshot_payload.get("daily_formula_budget"),
            "compute_backend": config_snapshot_payload.get("compute_backend"),
            "operator_engine": mining_job.get("operator_engine") if isinstance(mining_job, Mapping) else {},
            "blocked_field_policy": config_snapshot_payload.get("blocked_field_policy"),
            "composition_methods": config_snapshot_payload.get("composition_methods") or [],
            "funnel": self._factor_factory_funnel(),
        }
        self.storage.insert_json_row(
            "factor_factory_runs",
            {
                "id": run_id,
                "profile_id": "default",
                "run_date": run_date,
                "trigger": trigger,
                "status": run_status,
                "request_json": dumps({**dict(request_payload), "config_snapshot": config_snapshot_payload}),
                "gate_policy_json": dumps(dict(gate_policy)),
                "config_signature": config_signature,
                "mining_job_id": mining_job_id,
                "summary_json": dumps(summary),
                "started_at": now,
                "completed_at": now if run_status in {"FAILED", "CANCELLED"} else None,
                "created_at": now,
                "updated_at": now,
                "error_message": error_message,
            },
        )
        self.storage.insert_json_row(
            "factor_factory_run_items",
            {
                "id": f"ffi_{uuid4().hex[:12]}",
                "run_id": run_id,
                "stage": "OPERATOR_ENGINE_MINING",
                "source_id": None,
                "target_id": mining_job_id,
                "status": run_status,
                "summary_json": dumps({
                    "request": dict(request_payload),
                    "gate_policy": dict(gate_policy),
                    "config_snapshot": config_snapshot_payload,
                    "operator_engine": summary.get("operator_engine"),
                }),
                "created_at": now,
                "updated_at": now,
            },
        )
        row = self.storage.fetch_one("SELECT * FROM factor_factory_runs WHERE id = ?", (run_id,))
        return self._decode_factor_factory_run_row(row or {})

    def start_factor_factory_automation(self, request: Any | None = None) -> dict[str, Any]:
        payload = dict(_as_mapping(request or {}))
        request_payload = self._factor_factory_request_payload(request)
        gate_policy = self._factor_factory_gate_policy_payload(request)
        config_snapshot = self._factor_factory_run_config_snapshot_from_payload(payload)
        timezone_name = str(payload.get("timezone") or "Asia/Hong_Kong")
        schedule_time = str(payload.get("schedule_time") or "14:00")
        run_date = self._factor_factory_today()
        profile = self._upsert_factor_factory_profile(
            status="ACTIVE",
            request_payload=request_payload,
            gate_policy=gate_policy,
            timezone_name=timezone_name,
            schedule_time=schedule_time,
            run_date=run_date,
        )
        run = self._create_factor_factory_run(
            trigger="DAILY",
            request_payload=request_payload,
            gate_policy=gate_policy,
            config_snapshot=config_snapshot,
            run_date=run_date,
        )
        return {**self.get_factor_factory_overview(), "profile": profile, "daily_run": run}

    def pause_factor_factory_automation(self) -> dict[str, Any]:
        profile_row = self.storage.fetch_one("SELECT * FROM factor_factory_profiles WHERE id = 'default'")
        profile_payload = self._decode_factor_factory_profile_row(profile_row)
        profile = self._upsert_factor_factory_profile(
            status="PAUSED",
            request_payload=profile_payload.get("request") or self._factor_factory_default_request(),
            gate_policy=profile_payload.get("gate_policy") or self._factor_factory_default_gate_policy(),
            timezone_name=str(profile_payload.get("timezone") or "Asia/Hong_Kong"),
            schedule_time=str(profile_payload.get("schedule_time") or "14:00"),
        )
        return {**self.get_factor_factory_overview(), "profile": profile}

    def run_factor_factory_now(self, request: Any | None = None) -> dict[str, Any]:
        payload = dict(_as_mapping(request or {}))
        request_payload = self._factor_factory_request_payload(request)
        gate_policy = self._factor_factory_gate_policy_payload(request)
        config_snapshot = self._factor_factory_run_config_snapshot_from_payload(payload)
        run = self._create_factor_factory_run(
            trigger="MANUAL",
            request_payload=request_payload,
            gate_policy=gate_policy,
            config_snapshot=config_snapshot,
        )
        return {**self.get_factor_factory_overview(), "manual_run": run}

    def run_factor_factory_online_raw_f2_refinement(self, request: Any | None = None) -> dict[str, Any]:
        payload = dict(_as_mapping(request or {}))
        gate_policy = self._factor_factory_gate_policy_payload(request)
        config_snapshot = self._factor_factory_run_config_snapshot_from_payload(payload)
        candidate_limit = max(1, min(10000, int(_coerce_float(payload.get("candidate_limit"), 10000.0))))
        raw_candidates = self._factor_factory_online_raw_f2_candidates(
            factor_ids=[
                str(item).strip()
                for item in payload.get("factor_ids") or []
                if str(item).strip()
            ],
            candidate_limit=candidate_limit,
        )
        run_id = f"ffr_online_rawf2_{uuid4().hex[:12]}"
        now = iso_now()
        mining_job = self._create_factor_factory_online_raw_f2_job(
            run_id=run_id,
            raw_candidates=raw_candidates,
            candidate_limit=candidate_limit,
            gate_policy=gate_policy,
            config_snapshot=config_snapshot,
            created_at=now,
        )
        mining_job_id = str(mining_job.get("id") or "")
        request_payload = {
            "generation_mode": "ONLINE_RAW_F2_REFINEMENT",
            "source": "online_factor_library_raw_f2",
            "candidate_limit": candidate_limit,
            "source_factor_ids": [
                str(source_id)
                for candidate in raw_candidates
                for source_id in (candidate.get("source_factor_ids") or [])
                if str(source_id).strip()
            ],
        }
        config_signature = self._factor_factory_config_signature(request_payload, gate_policy, config_snapshot)
        summary = {
            "trigger": "MANUAL",
            "daily_automation": False,
            "one_time_task": True,
            "source": "online_factor_library_raw_f2",
            "generation_mode": "ONLINE_RAW_F2_REFINEMENT",
            "pit_gate_mode": gate_policy.get("pit_gate_mode", "DIAGNOSTIC_ONLY"),
            "residual_enabled": bool(gate_policy.get("residual_enabled", True)),
            "drawdown_threshold": gate_policy.get("max_drawdown_relative_to_benchmark", 1.5),
            "mining_job_id": mining_job_id,
            "config_snapshot": config_snapshot,
            "operator_config_snapshot_id": config_snapshot.get("operator_config_snapshot_id"),
            "f1_catalog_snapshot_id": config_snapshot.get("f1_catalog_snapshot_id"),
            "enabled_operators": config_snapshot.get("enabled_operators"),
            "window_space": config_snapshot.get("window_space"),
            "default_depth": config_snapshot.get("default_depth"),
            "daily_formula_budget": config_snapshot.get("daily_formula_budget"),
            "compute_backend": config_snapshot.get("compute_backend"),
            "operator_engine": mining_job.get("operator_engine") if isinstance(mining_job, Mapping) else {},
            "raw_library_source_count": len(request_payload["source_factor_ids"]),
            "funnel": self._factor_factory_funnel(),
        }
        self.storage.insert_json_row(
            "factor_factory_runs",
            {
                "id": run_id,
                "profile_id": "default",
                "run_date": self._factor_factory_today(),
                "trigger": "MANUAL",
                "status": "COMPLETED",
                "request_json": dumps({**request_payload, "config_snapshot": config_snapshot}),
                "gate_policy_json": dumps(dict(gate_policy)),
                "config_signature": config_signature,
                "mining_job_id": mining_job_id,
                "summary_json": dumps(summary),
                "started_at": now,
                "completed_at": now,
                "created_at": now,
                "updated_at": now,
                "error_message": None,
            },
        )
        self._record_factor_factory_run_item(
            run_id=run_id,
            stage="ONLINE_RAW_F2_REFINEMENT",
            source_id=None,
            target_id=mining_job_id,
            status="COMPLETED",
            summary={
                "source": "online_factor_library_raw_f2",
                "source_factor_count": len(request_payload["source_factor_ids"]),
                "operator_engine": mining_job.get("operator_engine") if isinstance(mining_job, Mapping) else {},
            },
        )
        row = self.storage.fetch_one("SELECT * FROM factor_factory_runs WHERE id = ?", (run_id,))
        refreshed = self._refresh_factor_factory_run_row(row or {})
        run = self._decode_factor_factory_run_row(refreshed)
        return {**self.get_factor_factory_overview(), "online_raw_f2_run": run}

    def cancel_factor_factory_run(self, run_id: str) -> dict[str, Any]:
        row = self.storage.fetch_one("SELECT * FROM factor_factory_runs WHERE id = ?", (run_id,))
        if not row:
            raise KeyError(f"Factor factory run not found: {run_id}")
        mining_job_id = str(row.get("mining_job_id") or "")
        if mining_job_id:
            try:
                self.cancel_factor_mining_job(mining_job_id)
            except Exception:
                pass
        now = iso_now()
        self.storage.execute(
            """
            UPDATE factor_factory_runs
            SET status = 'CANCELLED', completed_at = ?, updated_at = ?
            WHERE id = ?
            """,
            (now, now, run_id),
        )
        refreshed = self.storage.fetch_one("SELECT * FROM factor_factory_runs WHERE id = ?", (run_id,))
        return self._decode_factor_factory_run_row(refreshed or row)

    def _project_mining_candidate(self, candidate: Any) -> dict[str, Any]:
        rank_ic = candidate.rank_ic if getattr(candidate, "rank_ic", None) is not None else 0.0
        fitness_score = getattr(candidate, "fitness_score", None)
        auto_residual_summary = getattr(candidate, "auto_residual_summary", None) or {}
        return {
            "id": candidate.candidate_id,
            "candidate_id": candidate.candidate_id,
            "rank": candidate.rank,
            "expression": candidate.expression,
            "score": round(float(fitness_score if fitness_score is not None else rank_ic), 6),
            "rank_ic": rank_ic,
            "pure_rank_ic": getattr(candidate, "pure_rank_ic", None),
            "ir": getattr(candidate, "information_ratio", None),
            "information_ratio": getattr(candidate, "information_ratio", None),
            "holding_period": getattr(candidate, "holding_period", None),
            "newey_west_lags": getattr(candidate, "newey_west_lags", None),
            "fitness_score": fitness_score,
            "max_style_correlation": getattr(candidate, "max_style_correlation", None),
            "correlation_penalty": getattr(candidate, "correlation_penalty", 0.0),
            "max_drawdown_pct": getattr(candidate, "max_drawdown_pct", None),
            "benchmark_max_drawdown_pct": getattr(candidate, "benchmark_max_drawdown_pct", None),
            "drawdown_vs_benchmark_ratio": getattr(candidate, "drawdown_vs_benchmark_ratio", None),
            "auto_residual_summary": dict(auto_residual_summary) if isinstance(auto_residual_summary, Mapping) else {},
            "source_factor_ids": list(getattr(candidate, "source_factor_ids", ()) or ()),
            "recipe_kind": getattr(candidate, "recipe_kind", None),
            "recipe_family": getattr(candidate, "recipe_family", None),
            "orthogonality_intent": getattr(candidate, "orthogonality_intent", None),
            "composition_metadata": dict(getattr(candidate, "composition_metadata", None) or {}),
            "turnover": getattr(candidate, "turnover", 0.0),
            "coverage": candidate.coverage,
            "depth": getattr(candidate, "depth", None),
            "risk_flags": list(candidate.risk_flags),
            "status": candidate.status,
            "persisted_to_factor_definitions": False,
        }

    def create_factor_mining_job(self, request: Any) -> dict[str, Any]:
        payload = dict(_as_mapping(request))
        symbols = self._factor_universe_symbols(payload.get("universe"))
        mining_request = MiningJobRequest(
            universe=tuple(symbols),
            start_date=str(payload.get("start_date") or ""),
            end_date=str(payload.get("end_date") or ""),
            operators=tuple(str(item) for item in payload.get("operators") or ()),
            candidate_count=int(payload.get("candidate_count") or 0),
            random_seed=int(payload.get("random_seed") if payload.get("random_seed") is not None else 0),
            min_rank_ic=_coerce_float(payload.get("min_rank_ic")),
            max_depth=int(payload.get("max_depth") or 3),
            generation_mode=str(payload.get("generation_mode") or "PRICE_OPERATOR"),
            source_factor_ids=tuple(str(item) for item in payload.get("source_factor_ids") or ()),
            recipe_families=tuple(str(item) for item in payload.get("recipe_families") or ()),
            exploration_budget=int(payload.get("exploration_budget") or 0),
            composition_policy=dict(payload.get("composition_policy") or {}),
        )
        mining_request.validate()
        job_id = factor_mining_job_id_for_request(mining_request)
        request_signature = self._factor_mining_request_signature(payload)
        with self._factor_mining_job_lock:
            duplicate = self._find_factor_mining_duplicate_job_row(request_signature)
            if duplicate is not None:
                return self._decode_factor_mining_job_row(duplicate)
        created_at = iso_now()
        market_data = self._factor_mining_market_data(
            symbols,
            start_date=mining_request.start_date,
            end_date=mining_request.end_date,
        )
        summary = {
            "universe_symbol_count": len(symbols),
            "price_symbol_count": len(market_data),
            "dataset_snapshot_id": DATASET_PRICE_SNAPSHOT_ID,
            "market_data_source": "dataset_price_bars",
            "synthetic_market_data": False,
            "top_candidate_count": 0,
            "failed_sample_count": 0,
            "persisted_to_factor_definitions": False,
            "generation_mode": mining_request.generation_mode,
            "composition_policy": dict(mining_request.composition_policy or {}),
        }
        progress = {
            "total_candidates": mining_request.candidate_count,
            "evaluated_candidates": 0,
            "failed_candidates": 0,
            "throughput_per_second": 0.0,
            "percent": 0.0,
        }
        with self._factor_mining_job_lock:
            duplicate = self._find_factor_mining_duplicate_job_row(request_signature)
            if duplicate is not None:
                return self._decode_factor_mining_job_row(duplicate)
            existing = self.storage.fetch_one("SELECT * FROM factor_mining_jobs WHERE id = ?", (job_id,))
            existing_status = str(existing.get("status") or "") if existing else ""
            thread = self._factor_mining_threads.get(job_id)
            if existing and (
                existing_status not in {"QUEUED", "RUNNING", "CANCEL_REQUESTED"}
                or (thread is not None and thread.is_alive())
            ):
                return self._decode_factor_mining_job_row(existing)
            self._factor_mining_cancel_requests.discard(job_id)
            self.storage.insert_json_row(
                "factor_mining_jobs",
                {
                    "id": job_id,
                    "status": "RUNNING",
                    "request_json": dumps({**payload, "symbols": symbols, "dataset_snapshot_id": DATASET_PRICE_SNAPSHOT_ID}),
                    "progress_json": dumps(progress),
                    "summary_json": dumps(summary),
                    "top_candidates_json": dumps([]),
                    "failed_samples_json": dumps([]),
                    "created_at": created_at,
                    "updated_at": created_at,
                    "completed_at": None,
                    "error_message": None,
                },
            )
            initial_row = self.storage.fetch_one("SELECT * FROM factor_mining_jobs WHERE id = ?", (job_id,))
            thread = threading.Thread(
                target=self._run_factor_mining_job_background,
                args=(job_id, mining_request, market_data, payload, symbols, created_at),
                name=f"factor-mining-{job_id}",
                daemon=True,
            )
            self._factor_mining_threads[job_id] = thread
            thread.start()
        if initial_row is not None:
            return self._decode_factor_mining_job_row(initial_row)
        return self.get_factor_mining_job(job_id)

    def _factor_mining_should_cancel(self, job_id: str) -> bool:
        with self._factor_mining_job_lock:
            return job_id in self._factor_mining_cancel_requests

    def _run_factor_mining_job_background(
        self,
        job_id: str,
        mining_request: MiningJobRequest,
        market_data: dict[str, dict[str, list[float]]],
        payload: Mapping[str, Any],
        symbols: Sequence[str],
        created_at: str,
    ) -> None:
        started_at = monotonic()
        progress_step = max(1, mining_request.candidate_count // 20)
        last_progress_index = 0
        last_progress_written_at = 0.0

        def should_cancel_with_progress(candidate_index: int) -> bool:
            nonlocal last_progress_index, last_progress_written_at
            current_time = monotonic()
            should_write_progress = (
                candidate_index > 0
                and (
                    candidate_index == 1
                    or candidate_index - last_progress_index >= progress_step
                    or current_time - last_progress_written_at >= 1.0
                )
            )
            if should_write_progress:
                self._update_factor_mining_running_progress(
                    job_id,
                    total_candidates=mining_request.candidate_count,
                    evaluated_candidates=candidate_index,
                    started_at=started_at,
                    now=current_time,
                )
                last_progress_index = candidate_index
                last_progress_written_at = current_time
            return self._factor_mining_should_cancel(job_id)

        try:
            result = run_factor_mining_job(
                mining_request,
                market_data=market_data,
                should_cancel=should_cancel_with_progress,
                top_k=10,
            )
            self._store_factor_mining_result(
                result,
                payload=payload,
                symbols=symbols,
                market_data=market_data,
                created_at=created_at,
            )
        except Exception as exc:
            failed_at = iso_now()
            existing = self.storage.fetch_one("SELECT * FROM factor_mining_jobs WHERE id = ?", (job_id,))
            request_json = existing.get("request_json") if existing else dumps(
                {**payload, "symbols": symbols, "dataset_snapshot_id": DATASET_PRICE_SNAPSHOT_ID}
            )
            summary = loads(existing.get("summary_json"), {}) if existing else {}
            progress = loads(existing.get("progress_json"), {}) if existing else {}
            self.storage.insert_json_row(
                "factor_mining_jobs",
                {
                    "id": job_id,
                    "status": "FAILED",
                    "request_json": request_json,
                    "progress_json": dumps({**progress, "percent": float(progress.get("percent") or 0.0)}),
                    "summary_json": dumps({**summary, "error": str(exc), "persisted_to_factor_definitions": False}),
                    "top_candidates_json": existing.get("top_candidates_json") if existing else dumps([]),
                    "failed_samples_json": existing.get("failed_samples_json") if existing else dumps([]),
                    "created_at": existing.get("created_at") if existing else created_at,
                    "updated_at": failed_at,
                    "completed_at": failed_at,
                    "error_message": str(exc),
                },
            )
        finally:
            with self._factor_mining_job_lock:
                self._factor_mining_threads.pop(job_id, None)
                self._factor_mining_cancel_requests.discard(job_id)

    def _update_factor_mining_running_progress(
        self,
        job_id: str,
        *,
        total_candidates: int,
        evaluated_candidates: int,
        started_at: float,
        now: float,
    ) -> None:
        total = max(0, int(total_candidates))
        evaluated = max(0, min(int(evaluated_candidates), total))
        percent = 100.0 if total == 0 else round(evaluated / total * 100.0, 2)
        if evaluated < total:
            percent = min(percent, 99.0)
        elapsed = max(now - started_at, 0.000001)
        progress = {
            "total_candidates": total,
            "evaluated_candidates": evaluated,
            "failed_candidates": 0,
            "throughput_per_second": round(evaluated / elapsed, 3),
            "percent": percent,
        }
        self.storage.execute(
            """
            UPDATE factor_mining_jobs
            SET progress_json = ?, updated_at = ?
            WHERE id = ? AND status IN ('QUEUED', 'RUNNING', 'CANCEL_REQUESTED')
            """,
            (dumps(progress), iso_now(), job_id),
        )

    def _store_factor_mining_result(
        self,
        result: Any,
        *,
        payload: Mapping[str, Any],
        symbols: Sequence[str],
        market_data: Mapping[str, Mapping[str, Sequence[float | int | None]]],
        created_at: str,
    ) -> None:
        completed_at = iso_now()
        job_id = result.job_id
        top_candidates = [self._project_mining_candidate(candidate) for candidate in result.top_candidates]
        failed_samples = [
            {
                "candidate_index": sample.candidate_index,
                "expression": sample.expression,
                "reason": sample.error_message,
                "error_message": sample.error_message,
            }
            for sample in result.failed_samples
        ]
        progress = {
            "total_candidates": result.requested_candidates,
            "evaluated_candidates": result.candidates_evaluated,
            "failed_candidates": len(result.failed_samples),
            "throughput_per_second": result.throughput_per_second,
            "percent": result.progress_pct,
        }
        summary = {
            "universe_symbol_count": len(symbols),
            "price_symbol_count": len(market_data),
            "dataset_snapshot_id": DATASET_PRICE_SNAPSHOT_ID,
            "market_data_source": "dataset_price_bars",
            "synthetic_market_data": False,
            "top_candidate_count": len(top_candidates),
            "failed_sample_count": len(failed_samples),
            "persisted_to_factor_definitions": False,
            "generation_mode": getattr(result, "request_generation_mode", None)
            or str(payload.get("generation_mode") or "PRICE_OPERATOR"),
            "composition_candidate_count": sum(
                1
                for candidate in getattr(result, "all_candidates", ()) or ()
                if getattr(candidate, "recipe_kind", None)
            ),
            "composition_policy": dict(payload.get("composition_policy") or {}),
        }
        candidate_rows = [
            (
                candidate.candidate_id,
                job_id,
                candidate.expression,
                getattr(candidate, "fitness_score", None) if getattr(candidate, "fitness_score", None) is not None else candidate.rank_ic,
                candidate.rank_ic,
                getattr(candidate, "turnover", 0.0),
                candidate.coverage,
                getattr(candidate, "depth", None),
                dumps(list(candidate.risk_flags)),
                dumps({
                    "rank": candidate.rank,
                    "status": candidate.status,
                    "persisted_to_factor_definitions": False,
                    "fitness_score": getattr(candidate, "fitness_score", None),
                    "pure_rank_ic": getattr(candidate, "pure_rank_ic", None),
                    "ir": getattr(candidate, "information_ratio", None),
                    "information_ratio": getattr(candidate, "information_ratio", None),
                    "holding_period": getattr(candidate, "holding_period", None),
                    "newey_west_lags": getattr(candidate, "newey_west_lags", None),
                    "max_style_correlation": getattr(candidate, "max_style_correlation", None),
                    "correlation_penalty": getattr(candidate, "correlation_penalty", 0.0),
                    "max_drawdown_pct": getattr(candidate, "max_drawdown_pct", None),
                    "benchmark_max_drawdown_pct": getattr(candidate, "benchmark_max_drawdown_pct", None),
                    "drawdown_vs_benchmark_ratio": getattr(candidate, "drawdown_vs_benchmark_ratio", None),
                    "auto_residual_summary": getattr(candidate, "auto_residual_summary", None) or {},
                    "source_factor_ids": list(getattr(candidate, "source_factor_ids", ()) or ()),
                    "recipe_kind": getattr(candidate, "recipe_kind", None),
                    "recipe_family": getattr(candidate, "recipe_family", None),
                    "orthogonality_intent": getattr(candidate, "orthogonality_intent", None),
                    "composition_metadata": dict(getattr(candidate, "composition_metadata", None) or {}),
                }),
                created_at,
            )
            for candidate in result.all_candidates
        ]
        if candidate_rows:
            self.storage.executemany(
                """
                INSERT OR REPLACE INTO factor_mining_candidates (
                    id, job_id, expression, score, rank_ic, turnover, coverage,
                    depth, risk_flags_json, summary_json, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                candidate_rows,
            )
        self.storage.insert_json_row(
            "factor_mining_jobs",
            {
                "id": job_id,
                "status": result.status,
                "request_json": dumps({**payload, "symbols": symbols, "dataset_snapshot_id": DATASET_PRICE_SNAPSHOT_ID}),
                "progress_json": dumps(progress),
                "summary_json": dumps(summary),
                "top_candidates_json": dumps(top_candidates),
                "failed_samples_json": dumps(failed_samples),
                "created_at": created_at,
                "updated_at": completed_at,
                "completed_at": completed_at,
                "error_message": None,
            },
        )
        factory_rows = self.storage.fetch_all(
            """
            SELECT *
            FROM factor_factory_runs
            WHERE mining_job_id = ? AND status NOT IN ('CANCELLED', 'FAILED')
            """,
            (job_id,),
        )
        for row in factory_rows:
            self._refresh_factor_factory_run_row(row)

    def list_factor_mining_jobs(self) -> dict[str, Any]:
        rows = self.storage.fetch_all(
            """
            SELECT *
            FROM factor_mining_jobs
            ORDER BY created_at DESC, id DESC
            LIMIT 50
            """
        )
        unique_rows = self._dedupe_factor_mining_job_rows(rows)
        items = [self._decode_factor_mining_job_row(row) for row in unique_rows]
        return {
            "items": items,
            "summary": {
                "total": len(items),
                "running_count": sum(1 for item in items if item.get("status") in {"QUEUED", "RUNNING", "CANCEL_REQUESTED"}),
                "completed_count": sum(1 for item in items if item.get("status") == "COMPLETED"),
            },
        }

    def get_factor_mining_job(self, job_id: str) -> dict[str, Any]:
        row = self.storage.fetch_one("SELECT * FROM factor_mining_jobs WHERE id = ?", (job_id,))
        if not row:
            raise KeyError(f"Factor mining job not found: {job_id}")
        return self._decode_factor_mining_job_row(row)

    def cancel_factor_mining_job(self, job_id: str) -> dict[str, Any]:
        row = self.storage.fetch_one("SELECT * FROM factor_mining_jobs WHERE id = ?", (job_id,))
        if not row:
            raise KeyError(f"Factor mining job not found: {job_id}")
        status = str(row.get("status") or "")
        if status in {"QUEUED", "RUNNING", "CANCEL_REQUESTED"}:
            with self._factor_mining_job_lock:
                self._factor_mining_cancel_requests.add(job_id)
            row["status"] = "CANCELLED"
            row["updated_at"] = iso_now()
            row["completed_at"] = row["updated_at"]
            self.storage.insert_json_row("factor_mining_jobs", row)
        return self.get_factor_mining_job(job_id)

    def _normalize_factor_model_risk_item(
        self,
        item: Any,
        *,
        factor_id: str,
        factor: Mapping[str, Any] | None,
        default_code: str,
        default_message: str,
        severity: str,
    ) -> dict[str, Any]:
        payload = dict(item) if isinstance(item, Mapping) else {"message": str(item or "")}
        code = str(payload.get("code") or payload.get("reason_code") or default_code).strip().upper()
        message = str(
            payload.get("message")
            or payload.get("summary")
            or payload.get("label")
            or payload.get("reason")
            or default_message
        ).strip()
        normalized = dict(payload)
        normalized.update(
            {
                "factor_id": factor_id,
                "factor_name": (factor or {}).get("name") or payload.get("factor_name") or factor_id,
                "code": code or default_code,
                "message": message or default_message,
                "severity": str(payload.get("severity") or severity).upper(),
            }
        )
        return normalized

    def _dedupe_factor_model_risk_items(
        self,
        items: Sequence[Mapping[str, Any]],
    ) -> list[dict[str, Any]]:
        deduped: list[dict[str, Any]] = []
        seen: set[tuple[str, str, str]] = set()
        for item in items:
            key = (
                str(item.get("factor_id") or ""),
                str(item.get("code") or "").upper(),
                str(item.get("message") or ""),
            )
            if key in seen:
                continue
            seen.add(key)
            deduped.append(dict(item))
        return deduped

    def _factor_model_is_hard_blocker(
        self,
        item: Mapping[str, Any],
        *,
        default_hard: bool = False,
    ) -> bool:
        code = str(item.get("code") or item.get("reason_code") or "").upper()
        text = f"{code} {item.get('message') or ''} {item.get('reason') or ''}".lower()
        warning_code_fragments = (
            "HIGH_CORRELATION",
            "CORRELATION",
            "SAME_FAMILY",
            "FAMILY_OVERLAP",
            "OVERLAP",
            "IC_UNSTABLE",
            "WEAK_IC",
            "IR_UNSTABLE",
            "TURNOVER_DECAY",
            "TURNOVER_HIGH",
            "COVERAGE_EDGE",
            "LOW_COVERAGE",
            "DIAGNOSTIC_STALE",
            "STALE_DIAGNOSTIC",
            "FACTOR_ADMISSION_10Y_REPAIR",
            "FULL_READY_ARCHIVAL_GAP",
            "PIT_METADATA_RECOMPUTE_MISMATCH",
            "VERIFIED_PIT_WINDOW_INCOMPLETE",
        )
        warning_text_fragments = (
            "高相关",
            "同族",
            "ic 不稳定",
            "ic不稳定",
            "ir 不稳定",
            "换手衰减",
            "coverage 边缘",
            "覆盖率边缘",
            "诊断过期",
        )
        if any(fragment in code for fragment in warning_code_fragments) or any(
            fragment in text for fragment in warning_text_fragments
        ):
            return False
        hard_code_fragments = (
            "PIT",
            "FUTURE",
            "NON_REPLAYABLE",
            "NOT_REPLAYABLE",
            "CURRENT_ONLY",
            "CURRENT-ONLY",
            "UNSAFE",
            "AVAILABLE_AT",
            "NO_FACTOR_SCORE_PREVIEW",
            "BLOCKED_DATA",
            "BLOCKED_PIT",
        )
        hard_text_fragments = (
            "pit 缺口",
            "未来函数",
            "不可回放",
            "current-only",
            "current only",
            "unsafe expression",
            "available_at",
            "可得日",
            "缺少行业 pit",
            "行业 pit",
        )
        if any(fragment in code for fragment in hard_code_fragments) or any(
            fragment in text for fragment in hard_text_fragments
        ):
            return True
        return default_hard

    def _factor_model_low_risk_price_gap_context(self) -> dict[str, Any] | None:
        try:
            overview = self.get_pit_data_overview()
        except Exception:
            return None
        coverage_gap = overview.get("coverage_gap") if isinstance(overview.get("coverage_gap"), Mapping) else {}
        admission = overview.get("factor_admission_coverage") if isinstance(overview.get("factor_admission_coverage"), Mapping) else {}
        buckets = {
            str(bucket.get("id") or ""): bucket
            for bucket in coverage_gap.get("buckets") or []
            if isinstance(bucket, Mapping)
        }
        current_core = int(_coerce_float((buckets.get("current_core_missing") or {}).get("count"), 0.0))
        historical_core = int(_coerce_float((buckets.get("historical_lifecycle_missing") or {}).get("count"), 0.0))
        non_core_bucket = buckets.get("non_core_missing") or {}
        non_core = int(
            _coerce_float(
                non_core_bucket.get("count")
                if non_core_bucket.get("count") is not None
                else coverage_gap.get("default_ignored_count"),
                0.0,
            )
        )
        non_core_mcap_weight = _coerce_float(non_core_bucket.get("mcap_weight_pct"), 0.0)
        missing_total = int(_coerce_float(coverage_gap.get("missing_symbol_count"), 0.0))
        admission_allows = bool(admission) and not bool(admission.get("blocks_factor_admission"))
        admission_status = str(admission.get("status") or "").upper()
        admission_repair_count = int(_coerce_float(admission.get("repair_symbol_count"), 0.0))
        admission_archival_count = int(_coerce_float(admission.get("archival_missing_count"), 0.0))
        if missing_total <= 0 or non_core <= 0:
            return None
        if current_core > 0 or (historical_core > 0 and not admission_allows) or non_core_mcap_weight > 0.0001:
            return None
        summary = (
            f"PIT核心成员价格缺口为 {current_core}，"
            f"{non_core} 个非核心缺口市值权重占比 {non_core_mcap_weight:.2f}%，"
            "实盘准入风险极低。"
        )
        if admission_allows:
            summary = (
                f"PIT核心成员价格缺口为 {current_core}，10Y因子准入状态 {admission_status or 'READY'}；"
                f"{admission_repair_count} 个10年窗口补证标的与 {admission_archival_count} 个Full Ready归档缺口进入修复队列，"
                "已转为创建提示，允许物化多因子策略。"
            )
        return {
            "code": "LOW_RISK_NON_CORE_PRICE_GAP",
            "label": "低风险准入",
            "summary": summary,
            "current_core_missing_count": current_core,
            "historical_core_missing_count": historical_core,
            "non_core_missing_count": non_core,
            "non_core_mcap_weight_pct": round(non_core_mcap_weight, 4),
            "missing_symbol_count": missing_total,
            "factor_admission_status": admission_status,
            "factor_admission_repair_symbol_count": admission_repair_count,
            "factor_admission_archival_missing_count": admission_archival_count,
        }

    @staticmethod
    def _factor_model_can_soften_price_gap_blocker(
        item: Mapping[str, Any],
        low_risk_context: Mapping[str, Any] | None,
    ) -> bool:
        if not low_risk_context:
            return False
        code = str(item.get("code") or item.get("reason_code") or "").upper()
        return code in {
            "PRICE_SNAPSHOT_NOT_READY",
            "PIT_GATE_BLOCKED",
            "PIT_BLOCKER",
            "BLOCKED_PIT",
        }

    def _factor_model_soften_low_risk_price_gap_blockers(
        self,
        hard_blockers: Sequence[Mapping[str, Any]],
        low_risk_context: Mapping[str, Any] | None,
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]], dict[str, Any] | None]:
        retained: list[dict[str, Any]] = []
        warnings: list[dict[str, Any]] = []
        softened = False
        for blocker in hard_blockers:
            item = dict(blocker)
            if self._factor_model_can_soften_price_gap_blocker(item, low_risk_context):
                softened = True
                warnings.append(
                    {
                        **item,
                        "severity": "WARNING",
                        "label": (low_risk_context or {}).get("label") or item.get("label") or item.get("code"),
                        "message": (low_risk_context or {}).get("summary") or item.get("message") or "",
                        "original_message": item.get("message"),
                        "admission_risk_context": dict(low_risk_context or {}),
                    }
                )
                continue
            retained.append(item)
        return retained, warnings, dict(low_risk_context or {}) if softened and low_risk_context else None

    def _factor_model_factor_strategy_risk(
        self,
        factor_id: str,
        factor: Mapping[str, Any],
    ) -> dict[str, list[dict[str, Any]]]:
        warnings: list[dict[str, Any]] = []
        hard_blockers: list[dict[str, Any]] = []
        lifecycle = str(factor.get("lifecycle_status") or "").upper()
        if lifecycle in {"DEPRECATED", "PRUNED"} or factor.get("offline_at"):
            hard_blockers.append(
                self._normalize_factor_model_risk_item(
                    {
                        "code": "FACTOR_OFFLINE",
                        "message": str(factor.get("offline_reason") or "因子已下线，不能进入策略创建或算力分配。"),
                    },
                    factor_id=factor_id,
                    factor=factor,
                    default_code="FACTOR_OFFLINE",
                    default_message="因子已下线，不能进入策略创建或算力分配。",
                    severity="BLOCKER",
                )
            )
        risk = factor.get("strategy_creation_risk")
        risk_payload = risk if isinstance(risk, Mapping) else {}
        for item in risk_payload.get("warnings") or []:
            warnings.append(
                self._normalize_factor_model_risk_item(
                    item,
                    factor_id=factor_id,
                    factor=factor,
                    default_code="FACTOR_DIAGNOSTIC_WARNING",
                    default_message="因子诊断存在策略创建风险提示。",
                    severity="WARNING",
                )
            )
        for item in risk_payload.get("hard_blockers") or []:
            hard_blockers.append(
                self._normalize_factor_model_risk_item(
                    item,
                    factor_id=factor_id,
                    factor=factor,
                    default_code="FACTOR_HARD_BLOCKER",
                    default_message="因子存在不可回放或 PIT 门禁硬阻断。",
                    severity="BLOCKER",
                )
            )
        if risk_payload and int(_coerce_float(risk_payload.get("warning_count"), 0.0)) > 0 and not warnings:
            warnings.append(
                self._normalize_factor_model_risk_item(
                    {},
                    factor_id=factor_id,
                    factor=factor,
                    default_code="FACTOR_DIAGNOSTIC_WARNING",
                    default_message="因子诊断存在策略创建风险提示。",
                    severity="WARNING",
                )
            )
        if risk_payload and (
            int(_coerce_float(risk_payload.get("blocked_count"), 0.0)) > 0
            or risk_payload.get("can_create") is False
        ) and not hard_blockers:
            hard_blockers.append(
                self._normalize_factor_model_risk_item(
                    {},
                    factor_id=factor_id,
                    factor=factor,
                    default_code="FACTOR_HARD_BLOCKER",
                    default_message="因子存在硬阻断，不能进入策略创建。",
                    severity="BLOCKER",
                )
            )

        diagnostic_status = str(factor.get("diagnostic_status") or "").upper()
        default_hard = diagnostic_status.startswith("BLOCKED")
        readiness_blockers = [
            blocker
            for blocker in factor.get("readiness_blockers") or []
            if isinstance(blocker, Mapping)
        ]
        for blocker in readiness_blockers:
            normalized = self._normalize_factor_model_risk_item(
                blocker,
                factor_id=factor_id,
                factor=factor,
                default_code=str(blocker.get("code") or diagnostic_status or "FACTOR_READINESS_BLOCKER"),
                default_message="因子数据门禁存在未处理事项。",
                severity="BLOCKER" if default_hard else "WARNING",
            )
            if self._factor_model_is_hard_blocker(normalized, default_hard=default_hard):
                hard_blockers.append(normalized)
            else:
                warnings.append(normalized)
        if default_hard and not readiness_blockers and not hard_blockers:
            hard_blockers.append(
                self._normalize_factor_model_risk_item(
                    {},
                    factor_id=factor_id,
                    factor=factor,
                    default_code=diagnostic_status or "FACTOR_BLOCKED",
                    default_message="因子数据门禁处于阻断状态。",
                    severity="BLOCKER",
                )
            )

        correlation_cluster = factor.get("correlation_cluster")
        nodes = correlation_cluster.get("nodes") if isinstance(correlation_cluster, Mapping) else []
        high_correlation_nodes = [
            node
            for node in nodes or []
            if isinstance(node, Mapping)
            and (
                str(node.get("risk_label") or "") == "高相关"
                or _coerce_float(node.get("correlation"), 0.0) >= 0.72
            )
        ]
        if high_correlation_nodes:
            warnings.append(
                self._normalize_factor_model_risk_item(
                    {
                        "code": "HIGH_CORRELATION",
                        "message": f"{factor.get('name') or factor_id} 与 {len(high_correlation_nodes)} 个因子高相关，仅作为策略创建风险提示。",
                        "related_factor_ids": [
                            str(node.get("factor_id") or "")
                            for node in high_correlation_nodes
                            if str(node.get("factor_id") or "")
                        ],
                    },
                    factor_id=factor_id,
                    factor=factor,
                    default_code="HIGH_CORRELATION",
                    default_message="因子与已选或同族因子高相关，仅提示风险。",
                    severity="WARNING",
                )
            )

        return {
            "warnings": self._dedupe_factor_model_risk_items(warnings),
            "hard_blockers": self._dedupe_factor_model_risk_items(hard_blockers),
        }

    def _factor_model_strategy_creation_risk_summary(
        self,
        *,
        warning_count: int,
        blocked_count: int,
        low_risk_context: Mapping[str, Any] | None = None,
    ) -> str:
        if blocked_count:
            return f"存在 {blocked_count} 个硬阻断，需修复 PIT、表达式或行业数据后才能创建策略。"
        if warning_count:
            return f"可创建策略，但存在 {warning_count} 个风险提示；高相关等问题只提示，不阻断创建。"
        return "策略创建风险检查通过，可创建策略。"

    def _build_factor_model_strategy_creation_risk(
        self,
        *,
        factor_warnings: Sequence[Mapping[str, Any]],
        factor_hard_blockers: Sequence[Mapping[str, Any]],
        pit_blockers: Sequence[Mapping[str, Any]],
        neutralization_status: Mapping[str, Any],
        coverage_ratio: float,
        estimated_turnover: float,
        low_risk_context: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        warnings = [dict(item) for item in factor_warnings]
        hard_blockers = [dict(item) for item in factor_hard_blockers]
        for blocker in pit_blockers:
            if not isinstance(blocker, Mapping):
                continue
            factor_id = str(blocker.get("factor_id") or "MODEL")
            normalized = self._normalize_factor_model_risk_item(
                blocker,
                factor_id=factor_id,
                factor={},
                default_code=str(blocker.get("code") or "PIT_BLOCKER"),
                default_message="PIT 数据或表达式门禁阻断策略创建。",
                severity="BLOCKER",
            )
            if self._factor_model_is_hard_blocker(normalized, default_hard=True):
                hard_blockers.append(normalized)
            else:
                warnings.append(normalized)
        for code in neutralization_status.get("blockers") or []:
            hard_blockers.append(
                self._normalize_factor_model_risk_item(
                    {
                        "code": str(code),
                        "message": "启用行业中性化但缺少 PIT 行业字段，不能创建正式可回放策略。",
                    },
                    factor_id="NEUTRALIZATION",
                    factor={"name": "行业中性化"},
                    default_code="MISSING_INDUSTRY_PIT",
                    default_message="启用行业中性化但缺少 PIT 行业字段。",
                    severity="BLOCKER",
                )
            )
        if 0 < coverage_ratio < 0.8:
            warnings.append(
                self._normalize_factor_model_risk_item(
                    {
                        "code": "COVERAGE_EDGE",
                        "message": f"多因子打分覆盖率 {round(coverage_ratio * 100.0, 2)}%，建议复核样本覆盖。",
                    },
                    factor_id="MODEL",
                    factor={"name": "多因子模型"},
                    default_code="COVERAGE_EDGE",
                    default_message="多因子打分覆盖率边缘。",
                    severity="WARNING",
                )
            )
        if estimated_turnover >= 0.55:
            warnings.append(
                self._normalize_factor_model_risk_item(
                    {
                        "code": "TURNOVER_DECAY",
                        "message": f"预估换手 {round(estimated_turnover * 100.0, 2)}%，建议评估换手衰减和交易成本。",
                    },
                    factor_id="MODEL",
                    factor={"name": "多因子模型"},
                    default_code="TURNOVER_DECAY",
                    default_message="预估换手偏高。",
                    severity="WARNING",
                )
            )
        hard_blockers = self._dedupe_factor_model_risk_items(hard_blockers)
        hard_blockers, softened_warnings, applied_low_risk_context = self._factor_model_soften_low_risk_price_gap_blockers(
            hard_blockers,
            low_risk_context,
        )
        warnings.extend(softened_warnings)
        warnings = self._dedupe_factor_model_risk_items(warnings)
        summary = self._factor_model_strategy_creation_risk_summary(
            warning_count=len(warnings),
            blocked_count=len(hard_blockers),
        )
        if applied_low_risk_context and not hard_blockers:
            summary = f"{applied_low_risk_context.get('summary')} 已转为创建提示，允许物化多因子策略。"
        return {
            "warning_count": len(warnings),
            "blocked_count": len(hard_blockers),
            "warnings": warnings,
            "hard_blockers": hard_blockers,
            "can_create": not hard_blockers,
            "summary_label": (
                "低风险准入"
                if applied_low_risk_context and not hard_blockers
                else ("阻断" if hard_blockers else ("风险提示" if warnings else "无阻断"))
            ),
            "summary": summary,
            "admission_risk_context": applied_low_risk_context,
        }

    @staticmethod
    def _factor_model_payload_strategy_type(payload: Mapping[str, Any]) -> str:
        return str(
            payload.get("strategy_type")
            or payload.get("model_type")
            or payload.get("factor_model_type")
            or "MULTI_FACTOR"
        ).strip().upper() or "MULTI_FACTOR"

    @staticmethod
    def _factor_op_lights_completed(factor: Mapping[str, Any]) -> set[str]:
        op_status = factor.get("op_status") if isinstance(factor.get("op_status"), Mapping) else {}
        lights = op_status.get("lights") if isinstance(op_status, Mapping) else []
        completed = {
            str(light.get("code") or "").upper()
            for light in lights or []
            if isinstance(light, Mapping) and bool(light.get("active"))
        }
        if completed:
            return completed
        expression = str(factor.get("expression") or "").lower()
        descriptor = factor.get("descriptor") if isinstance(factor.get("descriptor"), Mapping) else {}
        operator = str(descriptor.get("operator") or "").lower()
        inferred: set[str] = set()
        if any(token in expression for token in ("winsor", "mad(")):
            inferred.add("W")
        if any(token in expression for token in ("neutral", "residual", "beta")):
            inferred.add("N")
        if operator == "z" or any(token in expression for token in ("zscore", "z_score")):
            inferred.add("Z")
        if operator == "rank" or any(token in expression for token in ("rank(", "tsrank", "ts_rank")):
            inferred.add("T")
        return inferred

    def _composite_factor_eligibility(
        self,
        factor_id: str,
        factor: Mapping[str, Any],
        components: Sequence[Mapping[str, Any]],
        total_abs_weight: float,
    ) -> tuple[dict[str, Any], list[dict[str, Any]]]:
        completed_ops = self._factor_op_lights_completed(factor)
        required_ops = {"W", "N", "Z", "T"}
        tier_projection = factor.get("tier_projection") if isinstance(factor.get("tier_projection"), Mapping) else {}
        level_projection = factor.get("factor_level_projection") if isinstance(factor.get("factor_level_projection"), Mapping) else {}
        tier = str(factor.get("tier_level") or tier_projection.get("key") or "").upper()
        level = str(factor.get("factor_level") or level_projection.get("key") or "").upper()
        market = str(factor.get("market") or "").upper()
        latest_summary = factor.get("latest_diagnostic_summary") if isinstance(factor.get("latest_diagnostic_summary"), Mapping) else {}
        diagnostic_status = str(latest_summary.get("status") or factor.get("diagnostic_status") or "").upper()
        checks = {
            "single_factor": len(components) == 1,
            "weight_100": abs(total_abs_weight - 100.0) <= 0.01 or abs(total_abs_weight - 1.0) <= 0.0001,
            "market_us": market == "US",
            "tier_l3": tier in {"F3", "L3"},
            "grade_sab": level in {"S", "A", "B"},
            "diagnostic_completed": diagnostic_status == "COMPLETED",
            "wnzt_complete": required_ops.issubset(completed_ops),
        }
        labels = {
            "single_factor": "Composite factor strategy requires exactly one L3 factor.",
            "weight_100": "Composite factor strategy requires the selected factor weight to be 100%.",
            "market_us": "Composite factor strategy currently supports US equity factors only.",
            "tier_l3": "Composite factor strategy only accepts L3/F3 factors.",
            "grade_sab": "Composite factor strategy only accepts S/A/B grade factors.",
            "diagnostic_completed": "Composite factor strategy requires a completed diagnostic summary.",
            "wnzt_complete": "Composite factor strategy requires W/N/Z/T processing lights to be complete.",
        }
        blockers = [
            {
                "factor_id": factor_id or "MODEL",
                "factor_name": factor.get("name") or factor_id,
                "code": f"COMPOSITE_{key.upper()}",
                "message": labels[key],
                "severity": "BLOCKER",
            }
            for key, passed in checks.items()
            if not passed
        ]
        return {
            "strategy_type": "COMPOSITE_FACTOR",
            "factor_id": factor_id,
            "can_create": not blockers,
            "checks": checks,
            "completed_ops": sorted(completed_ops),
            "missing_ops": sorted(required_ops - completed_ops),
            "market": market or None,
            "tier_level": tier or None,
            "factor_level": level or None,
            "diagnostic_status": diagnostic_status or None,
        }, blockers

    @staticmethod
    def _composite_factor_diagnostic_summary(factor: Mapping[str, Any]) -> dict[str, Any]:
        summary = factor.get("latest_diagnostic_summary") if isinstance(factor.get("latest_diagnostic_summary"), Mapping) else {}
        group_returns = [
            dict(item)
            for item in summary.get("group_returns") or []
            if isinstance(item, Mapping)
        ]
        weak_groups = sorted(
            group_returns,
            key=lambda item: _coerce_float(item.get("mean_return"), 0.0),
        )[:3]
        risk_flags = [str(item) for item in summary.get("risk_flags") or [] if str(item).strip()]
        return {
            "factor_id": factor.get("id"),
            "factor_name": factor.get("name"),
            "status": summary.get("status") or factor.get("diagnostic_status"),
            "rank_ic": summary.get("rank_ic"),
            "ic": summary.get("ic"),
            "ir": summary.get("ir"),
            "coverage": summary.get("coverage"),
            "weak_groups": weak_groups,
            "weak_sectors": weak_groups,
            "risk_flags": risk_flags[:5],
        }

    @staticmethod
    def _composite_initial_weights(
        selected_rows: Sequence[Mapping[str, Any]],
        method: str,
    ) -> dict[str, float]:
        if not selected_rows:
            return {}
        normalized_method = str(method or "equal_top_k").strip().lower()
        if normalized_method in {"score_proportional", "risk_heuristic"}:
            scores = [_coerce_float(row.get("score"), 0.0) for row in selected_rows]
            floor = min(scores) if scores else 0.0
            adjusted = [max(score - floor, 0.0) + 1e-6 for score in scores]
            total = sum(adjusted)
            if total > 0:
                return {
                    str(row.get("symbol")): adjusted[index] / total
                    for index, row in enumerate(selected_rows)
                    if str(row.get("symbol") or "").strip()
                }
        equal_weight = 1.0 / max(len(selected_rows), 1)
        return {
            str(row.get("symbol")): equal_weight
            for row in selected_rows
            if str(row.get("symbol") or "").strip()
        }

    @staticmethod
    def _redistribute_weight_by_score(
        weights: dict[str, float],
        scores: Mapping[str, float],
        *,
        excess: float,
        capacity: Mapping[str, float],
    ) -> float:
        remaining = max(float(excess), 0.0)
        for _ in range(20):
            candidates = [
                symbol
                for symbol, cap in capacity.items()
                if cap - weights.get(symbol, 0.0) > 1e-9
            ]
            if remaining <= 1e-9 or not candidates:
                break
            score_floor = min(scores.get(symbol, 0.0) for symbol in candidates)
            score_weights = {
                symbol: max(scores.get(symbol, 0.0) - score_floor, 0.0) + 1e-6
                for symbol in candidates
            }
            score_total = sum(score_weights.values()) or float(len(candidates))
            distributed = 0.0
            for symbol in candidates:
                room = max(capacity.get(symbol, 0.0) - weights.get(symbol, 0.0), 0.0)
                if room <= 1e-9:
                    continue
                share = remaining * (score_weights.get(symbol, 1.0) / score_total)
                add = min(room, share)
                if add <= 0:
                    continue
                weights[symbol] = weights.get(symbol, 0.0) + add
                distributed += add
            if distributed <= 1e-9:
                break
            remaining -= distributed
        return remaining

    def _apply_factor_weight_caps(
        self,
        weights: Mapping[str, float],
        scores: Mapping[str, float],
        industry_by_symbol: Mapping[str, str],
        *,
        max_position_pct: float,
        sector_cap_pct: float,
        redistribution_mode: str,
    ) -> tuple[dict[str, float], float, float, list[dict[str, Any]]]:
        capped = {symbol: max(float(weight), 0.0) for symbol, weight in weights.items()}
        redistribution = str(redistribution_mode or "cash").strip().lower()
        max_position = max(_coerce_float(max_position_pct, 100.0) / 100.0, 0.0)
        sector_cap = max(_coerce_float(sector_cap_pct, 100.0) / 100.0, 0.0)
        original_sector_weights: dict[str, float] = {}
        for symbol, weight in capped.items():
            sector = str(industry_by_symbol.get(symbol) or "Unclassified")
            original_sector_weights[sector] = original_sector_weights.get(sector, 0.0) + weight
        cut_weight = 0.0
        if max_position > 0:
            excess = 0.0
            for symbol, weight in list(capped.items()):
                if weight > max_position:
                    excess += weight - max_position
                    capped[symbol] = max_position
            cut_weight += excess
            if redistribution == "proportional_refill" and excess > 0:
                capacity = {symbol: max_position for symbol in capped}
                self._redistribute_weight_by_score(capped, scores, excess=excess, capacity=capacity)
        sector_rows: list[dict[str, Any]] = []
        if sector_cap > 0:
            for _ in range(20):
                sector_weights: dict[str, float] = {}
                for symbol, weight in capped.items():
                    sector = str(industry_by_symbol.get(symbol) or "Unclassified")
                    sector_weights[sector] = sector_weights.get(sector, 0.0) + weight
                over = {
                    sector: weight
                    for sector, weight in sector_weights.items()
                    if weight > sector_cap + 1e-9
                }
                if not over:
                    break
                excess = 0.0
                for sector, weight in over.items():
                    scale = sector_cap / max(weight, 1e-12)
                    for symbol, current in list(capped.items()):
                        if str(industry_by_symbol.get(symbol) or "Unclassified") != sector:
                            continue
                        next_weight = current * scale
                        excess += current - next_weight
                        capped[symbol] = next_weight
                cut_weight += excess
                if redistribution != "proportional_refill" or excess <= 1e-9:
                    break
                capacity = {}
                for symbol in capped:
                    sector = str(industry_by_symbol.get(symbol) or "Unclassified")
                    sector_current = sum(
                        weight
                        for candidate, weight in capped.items()
                        if str(industry_by_symbol.get(candidate) or "Unclassified") == sector
                    )
                    sector_room = max(sector_cap - sector_current, 0.0)
                    name_room = max(max_position - capped.get(symbol, 0.0), 0.0) if max_position > 0 else 1.0
                    capacity[symbol] = capped.get(symbol, 0.0) + min(sector_room, name_room)
                residual = self._redistribute_weight_by_score(capped, scores, excess=excess, capacity=capacity)
                if residual >= excess - 1e-9:
                    break
            final_sector_weights: dict[str, float] = {}
            for symbol, weight in capped.items():
                sector = str(industry_by_symbol.get(symbol) or "Unclassified")
                final_sector_weights[sector] = final_sector_weights.get(sector, 0.0) + weight
            for sector, before in sorted(original_sector_weights.items(), key=lambda item: item[1], reverse=True):
                after = final_sector_weights.get(sector, 0.0)
                if before > sector_cap + 1e-9 or abs(after - before) > 1e-9:
                    sector_rows.append(
                        {
                            "sector": sector,
                            "before_pct": round(before * 100.0, 4),
                            "after_pct": round(after * 100.0, 4),
                            "cap_pct": round(sector_cap * 100.0, 4),
                            "cut_pct": round(max(before - after, 0.0) * 100.0, 4),
                        }
                    )
        invested = sum(capped.values())
        residual_cash = max(0.0, 1.0 - invested)
        return capped, round(max(cut_weight, 0.0), 6), round(residual_cash, 6), sector_rows

    def _composite_factor_allocation_forecast(
        self,
        payload: Mapping[str, Any],
        score_projection: Mapping[str, Any],
    ) -> dict[str, Any]:
        weight_mapping = dict(payload.get("weight_mapping") or {})
        top_n = max(int(_coerce_float(payload.get("top_n"), 50.0) or 50.0), 1)
        scored_rows = [
            dict(row)
            for row in score_projection.get("scored_rows") or score_projection.get("score_preview") or []
            if isinstance(row, Mapping) and str(row.get("symbol") or "").strip()
        ][:top_n]
        scores = {
            str(row.get("symbol")): _coerce_float(row.get("score"), 0.0)
            for row in scored_rows
        }
        industry_by_symbol = {
            str(symbol): str(sector)
            for symbol, sector in dict(score_projection.get("industry_by_symbol") or {}).items()
        }
        raw_weights = self._composite_initial_weights(
            scored_rows,
            str(weight_mapping.get("method") or "equal_top_k"),
        )
        capped, cut_weight, residual_cash, sectors = self._apply_factor_weight_caps(
            raw_weights,
            scores,
            industry_by_symbol,
            max_position_pct=_coerce_float(weight_mapping.get("max_position_pct"), 2.0),
            sector_cap_pct=_coerce_float(weight_mapping.get("sector_cap_pct"), 20.0),
            redistribution_mode=str(weight_mapping.get("cap_redistribution_mode") or "cash"),
        )
        top_holdings = [
            {
                "symbol": symbol,
                "weight_pct": round(weight * 100.0, 4),
                "sector": industry_by_symbol.get(symbol) or "Unclassified",
                "score": round(scores.get(symbol, 0.0), 4),
            }
            for symbol, weight in sorted(capped.items(), key=lambda item: item[1], reverse=True)[:10]
        ]
        return {
            "method": str(weight_mapping.get("method") or "equal_top_k"),
            "top_n": top_n,
            "sector_cap_pct": _coerce_float(weight_mapping.get("sector_cap_pct"), 20.0),
            "max_position_pct": _coerce_float(weight_mapping.get("max_position_pct"), 2.0),
            "cap_redistribution_mode": str(weight_mapping.get("cap_redistribution_mode") or "cash"),
            "cut_weight_pct": round(cut_weight * 100.0, 4),
            "residual_cash_pct": round(residual_cash * 100.0, 4),
            "invested_pct": round(sum(capped.values()) * 100.0, 4),
            "over_cap_sectors": sectors,
            "top_holdings": top_holdings,
        }

    @staticmethod
    def _composite_factor_cost_forecast(
        payload: Mapping[str, Any],
        score_projection: Mapping[str, Any],
    ) -> dict[str, Any]:
        constraints = dict(payload.get("execution_constraints") or {})
        universe_filter = dict(payload.get("universe_filter") or {})
        notional = _coerce_float(constraints.get("notional_usd"), 10_000_000.0)
        commission = _coerce_float(constraints.get("commission_bps"), 1.5)
        stamp_tax = _coerce_float(constraints.get("stamp_tax_bps"), 0.0)
        base_slippage = _coerce_float(constraints.get("base_slippage_bps"), 2.5)
        impact_beta = _coerce_float(constraints.get("impact_beta"), 0.65)
        max_impact = _coerce_float(constraints.get("max_impact_bps"), 75.0)
        top_n = max(int(_coerce_float(payload.get("top_n"), 50.0) or 50.0), 1)
        adv = max(_coerce_float(universe_filter.get("min_adv_usd"), 5_000_000.0), 1.0)
        average_order = notional / top_n
        participation = average_order / adv
        impact = base_slippage + impact_beta * math.sqrt(max(participation, 0.0)) * 10.0
        average_slippage = min(max_impact, impact) if max_impact > 0 else impact
        turnover = _coerce_float(score_projection.get("estimated_turnover"), 0.25)
        return {
            "notional_usd": round(notional, 2),
            "average_order_notional_usd": round(average_order, 2),
            "average_slippage_bps": round(average_slippage, 4),
            "fixed_cost_bps": round(commission + stamp_tax, 4),
            "estimated_turnover_pct": round(turnover * 100.0, 4),
            "impact_beta": impact_beta,
            "max_impact_bps": max_impact,
        }

    def preview_factor_model(self, request: Any) -> dict[str, Any]:
        payload = dict(_as_mapping(request))
        strategy_type = self._factor_model_payload_strategy_type(payload)
        is_composite = strategy_type == "COMPOSITE_FACTOR"
        components = [
            dict(item)
            for item in payload.get("components") or []
            if isinstance(item, Mapping) and str(item.get("factor_id") or "").strip()
        ]
        if not components:
            raise ValueError("Factor model requires at least one factor.")
        factor_items = self.list_factors().get("items", [])
        factor_by_id = {str(item.get("id")): item for item in factor_items}
        total_abs_weight = sum(abs(_coerce_float(item.get("weight"), 0.0)) for item in components)
        if total_abs_weight <= 0:
            raise ValueError("Factor model weights must not all be zero.")
        normalized_weights: list[dict[str, Any]] = []
        pit_blockers: list[dict[str, Any]] = []
        factor_risk_warnings: list[dict[str, Any]] = []
        factor_risk_hard_blockers: list[dict[str, Any]] = []
        composite_eligibility: dict[str, Any] | None = None
        composite_diagnostic_summary: dict[str, Any] | None = None
        for item in components:
            factor_id = str(item.get("factor_id") or "").strip()
            factor = factor_by_id.get(factor_id) or self.get_factor(factor_id)
            weight = _coerce_float(item.get("weight"), 0.0)
            normalized = {
                "factor_id": factor_id,
                "weight": weight,
                "normalized_weight": round(weight / total_abs_weight, 6),
                "direction": str(item.get("direction") or factor.get("direction") or "HIGH_IS_BETTER"),
                "name": factor.get("name"),
                "diagnostic_status": factor.get("diagnostic_status"),
            }
            normalized_weights.append(normalized)
            if str(factor.get("diagnostic_status") or "").startswith("BLOCKED"):
                for blocker in factor.get("readiness_blockers") or []:
                    if isinstance(blocker, Mapping):
                        pit_blockers.append({"factor_id": factor_id, **dict(blocker)})
            factor_risk = self._factor_model_factor_strategy_risk(factor_id, factor)
            factor_risk_warnings.extend(factor_risk["warnings"])
            factor_risk_hard_blockers.extend(factor_risk["hard_blockers"])
            for blocker in factor_risk["hard_blockers"]:
                if str(blocker.get("factor_id") or "") == factor_id:
                    pit_blockers.append(dict(blocker))
            if is_composite:
                composite_eligibility, composite_blockers = self._composite_factor_eligibility(
                    factor_id,
                    factor,
                    components,
                    total_abs_weight,
                )
                factor_risk_hard_blockers.extend(composite_blockers)
                composite_diagnostic_summary = self._composite_factor_diagnostic_summary(factor)
        symbols = self._factor_universe_symbols(payload.get("universe"))
        as_of_date = self._factor_preview_as_of(payload)
        neutralization = dict(payload.get("neutralization") or {})
        score_projection = self._factor_model_score_projection(
            normalized_weights,
            factor_by_id,
            symbols,
            as_of_date=as_of_date,
            neutralization=neutralization,
            universe=payload.get("universe"),
        )
        neutralization_result = score_projection["neutralization_result"]
        industry_coverage = (
            dict(score_projection.get("industry_coverage") or {})
            if isinstance(score_projection.get("industry_coverage"), Mapping)
            else {}
        )
        neutralization_status = {
            "enabled": bool(neutralization.get("enabled")),
            "method": str(neutralization.get("method") or "industry"),
            "status": neutralization_result.status,
            "blockers": list(neutralization_result.blockers),
            "industry_field": industry_coverage.get("industry_field") or score_projection.get("industry_field"),
            "taxonomy": industry_coverage.get("taxonomy"),
            "covered_symbol_count": industry_coverage.get("covered_symbol_count"),
            "missing_symbol_count": industry_coverage.get("missing_symbol_count"),
            "source_names": list(industry_coverage.get("source_names") or []),
        }
        score_preview = list(score_projection["score_preview"])
        warnings: list[str] = []
        if neutralization_result.blockers:
            warnings.append("行业中性化需要 PIT 行业字段，本次预览仅返回 blocker，不执行残差化。")
        if not score_preview:
            pit_blockers.append(
                {
                    "code": "NO_FACTOR_SCORE_PREVIEW",
                    "message": "PIT 价格/基础面数据未能产出任何可用的多因子打分样本。",
                    "fix_hash": "#/snapshots",
                }
            )
        pit_blockers = self._dedupe_factor_model_risk_items(pit_blockers)
        low_risk_context = self._factor_model_low_risk_price_gap_context()
        strategy_creation_risk = self._build_factor_model_strategy_creation_risk(
            factor_warnings=factor_risk_warnings,
            factor_hard_blockers=factor_risk_hard_blockers,
            pit_blockers=pit_blockers,
            neutralization_status=neutralization_status,
            coverage_ratio=_coerce_float(score_projection["coverage_ratio"], 0.0),
            estimated_turnover=_coerce_float(score_projection["estimated_turnover"], 0.0),
            low_risk_context=low_risk_context,
        )
        if is_composite:
            strategy_creation_risk["eligibility"] = composite_eligibility or {}
            strategy_creation_risk["diagnostic_summary"] = composite_diagnostic_summary or {}
            strategy_creation_risk["sector_cap_forecast"] = self._composite_factor_allocation_forecast(
                payload,
                score_projection,
            )
            strategy_creation_risk["cost_forecast"] = self._composite_factor_cost_forecast(
                payload,
                score_projection,
            )
        blocked_factor_ids = {
            str(item.get("factor_id"))
            for item in strategy_creation_risk.get("hard_blockers") or []
            if isinstance(item, Mapping) and item.get("factor_id")
        }
        status = "BLOCKED" if strategy_creation_risk["blocked_count"] else "READY"
        return {
            "status": status,
            "strategy_type": strategy_type,
            "normalized_weights": normalized_weights,
            "coverage": {
                "factor_count": len(normalized_weights),
                "ready_factor_count": len(normalized_weights) - len(blocked_factor_ids),
                "universe_symbol_count": len(symbols),
                "estimated_factor_coverage": score_projection["coverage_ratio"],
                "as_of_date": as_of_date,
            },
            "score_preview": score_preview,
            "estimated_turnover": score_projection["estimated_turnover"],
            "pit_blockers": pit_blockers,
            "neutralization_status": neutralization_status,
            "warnings": warnings,
            "strategy_creation_risk": strategy_creation_risk,
            "diagnostic_summary": composite_diagnostic_summary,
            "sector_cap_forecast": strategy_creation_risk.get("sector_cap_forecast"),
            "cost_forecast": strategy_creation_risk.get("cost_forecast"),
        }

    def create_factor_model(self, request: Any) -> dict[str, Any]:
        payload = dict(_as_mapping(request))
        strategy_type = self._factor_model_payload_strategy_type(payload)
        is_composite = strategy_type == "COMPOSITE_FACTOR"
        preview = self.preview_factor_model(payload)
        strategy_creation_risk = (
            dict(preview.get("strategy_creation_risk"))
            if isinstance(preview.get("strategy_creation_risk"), Mapping)
            else {}
        )
        neutralization_status = preview.get("neutralization_status") if isinstance(preview.get("neutralization_status"), Mapping) else {}
        hard_blockers = [
            dict(item)
            for item in strategy_creation_risk.get("hard_blockers") or []
            if isinstance(item, Mapping)
        ]
        if hard_blockers and any(str(item.get("code") or "").upper() == "MISSING_INDUSTRY_PIT" for item in hard_blockers):
            raise ValueError("Industry neutralization is enabled but PIT industry fields are missing.")
        if hard_blockers:
            raise ValueError("多因子策略创建风险包含硬阻断，修复后才能物化策略。")
        if neutralization_status.get("blockers"):
            raise ValueError("Industry neutralization is enabled but PIT industry fields are missing.")
        now = iso_now()
        strategy_id = self._new_id("strat")
        neutralization_payload = dict(payload.get("neutralization") or {"enabled": False, "method": "industry"})
        if neutralization_payload.get("enabled"):
            neutralization_payload.update(
                {
                    "industry_field": neutralization_status.get("industry_field"),
                    "taxonomy": neutralization_status.get("taxonomy"),
                    "covered_symbol_count": neutralization_status.get("covered_symbol_count"),
                    "missing_symbol_count": neutralization_status.get("missing_symbol_count"),
                    "source_names": list(neutralization_status.get("source_names") or []),
                    "execution_status": neutralization_status.get("status"),
                }
            )
        factor_count = len([item for item in payload.get("components") or [] if isinstance(item, Mapping)])
        default_top_n = 50 if is_composite else max(min(factor_count * 2, 10), 5)
        requested_top_n = max(int(_coerce_float(payload.get("top_n"), float(default_top_n)) or float(default_top_n)), 1)
        component_factor_ids = [
            str(item.get("factor_id"))
            for item in payload.get("components") or []
            if isinstance(item, Mapping)
        ]
        component_weights = {
            str(item.get("factor_id")): _coerce_float(item.get("weight"), 0.0)
            for item in payload.get("components") or []
            if isinstance(item, Mapping)
        }
        component_directions = {
            str(item.get("factor_id")): str(item.get("direction") or "HIGH_IS_BETTER")
            for item in payload.get("components") or []
            if isinstance(item, Mapping)
        }
        rebalance_logic = dict(payload.get("rebalance_logic") or {})
        weight_mapping = dict(payload.get("weight_mapping") or {})
        composite_rebalance_frequency = str(
            rebalance_logic.get("frequency")
            or payload.get("rebalance_frequency")
            or "monthly"
        )
        composite_weighting_method = {
            "equal_top_k": "equal_weight",
            "score_proportional": "score_weighted",
            "risk_heuristic": "score_weighted",
        }.get(str(weight_mapping.get("method") or "").lower(), "equal_weight")
        parameters = {
            "strategy_type": strategy_type,
            "factor_model_type": "COMPOSITE_FACTOR" if is_composite else "MULTI_FACTOR",
            "factor_id": component_factor_ids[0] if is_composite and component_factor_ids else None,
            "factor_ids": component_factor_ids,
            "weights": component_weights,
            "directions": component_directions,
            "neutralization": neutralization_payload,
            "top_n": requested_top_n,
            "holding_count": requested_top_n,
            "scoring_method": str(payload.get("scoring_method") or "zscore_weighted"),
            "rebalance_frequency": composite_rebalance_frequency if is_composite else str(payload.get("rebalance_frequency") or "monthly"),
            "weighting_method": composite_weighting_method if is_composite else "score_weighted",
            "pit_snapshot_refs": {
                "dataset_snapshot_id": DATASET_PRICE_SNAPSHOT_ID,
                "fundamental_snapshot_id": "ds-fundamentals",
                "universe_snapshot_id": SP500_UNIVERSE_SNAPSHOT_ID,
            },
            "preview": preview,
            "strategy_creation_risk": strategy_creation_risk,
        }
        if is_composite:
            parameters.update(
                {
                    "universe_filter": dict(payload.get("universe_filter") or {}),
                    "weight_mapping": weight_mapping,
                    "rebalance_logic": rebalance_logic,
                    "execution_constraints": dict(payload.get("execution_constraints") or {}),
                    "sector_cap_pct": _coerce_float(weight_mapping.get("sector_cap_pct"), 20.0),
                    "max_position_pct": _coerce_float(weight_mapping.get("max_position_pct"), 2.0),
                    "cap_redistribution_mode": str(weight_mapping.get("cap_redistribution_mode") or "cash"),
                    "diagnostic_summary": strategy_creation_risk.get("diagnostic_summary") or preview.get("diagnostic_summary"),
                    "sector_cap_forecast": strategy_creation_risk.get("sector_cap_forecast") or preview.get("sector_cap_forecast"),
                    "cost_forecast": strategy_creation_risk.get("cost_forecast") or preview.get("cost_forecast"),
                }
            )
        strategy_name = str(payload.get("name") or "多因子策略").strip() or "多因子策略"
        strategy_row = {
            "id": strategy_id,
            "name": strategy_name,
            "description": str(payload.get("description") or "基于因子库权重配置创建的多因子策略。"),
            "strategy_type": "MULTI_FACTOR",
            "universe_name": str(payload.get("universe") or "SP500"),
            "rebalance_frequency": parameters["rebalance_frequency"],
            "lifecycle_status": "ACTIVE",
            "dataset_snapshot_id": DATASET_PRICE_SNAPSHOT_ID,
            "universe_snapshot_id": SP500_UNIVERSE_SNAPSHOT_ID,
            "benchmark_symbol": "SPY",
            "current_parameter_version": 1,
            "parameters_json": dumps(parameters),
            "confirmation_fields_json": dumps({}),
            "parameter_history_json": dumps([]),
            "allowed_actions_json": dumps(["run_backtest", "open_strategy_detail", "open_optimization"]),
            "latest_run_id": None,
            "latest_successful_run_id": None,
            "created_at": now,
            "updated_at": now,
        }
        if is_composite:
            strategy_row["strategy_type"] = strategy_type
            if not str(payload.get("name") or "").strip():
                strategy_row["name"] = "组合因子策略"
            if not str(payload.get("description") or "").strip():
                strategy_row["description"] = "基于单个合格 L3 因子构建的美股组合因子策略。"
        parameter_history = [
            {
                "version_number": 1,
                "parameter_version_id": f"{strategy_id}-v1",
                "revision": 1,
                "created_at": now,
                "comment": "多因子模型创建",
                "source": {"kind": "factor_model_builder"},
                "parameters": parameters,
            }
        ]
        self._write_strategy_record(strategy_row, parameter_history=parameter_history, current_version=1, comment="多因子模型创建")
        return self.get_strategy_detail(strategy_id)

    def _is_multi_factor_strategy(self, strategy: Mapping[str, Any] | None) -> bool:
        if not strategy:
            return False
        parameters = dict(strategy.get("parameters") or {})
        return _is_factor_model_strategy_type(strategy.get("strategy_type") or parameters.get("strategy_type"))

    def _is_multi_factor_parameters(self, parameters: Mapping[str, Any] | None) -> bool:
        if not parameters:
            return False
        return _is_factor_model_strategy_type(parameters.get("strategy_type")) or bool(parameters.get("factor_ids"))

    def _multi_factor_factor_index_signature(self) -> str:
        try:
            row = self.storage.fetch_one(
                """
                SELECT
                    COUNT(*) AS row_count,
                    COALESCE(MAX(updated_at), '') AS max_updated_at,
                    COALESCE(MAX(deleted_at), '') AS max_deleted_at
                FROM factor_definitions
                """
            )
        except Exception:
            return "factor-definitions-unavailable"
        if not row:
            return "factor-definitions-empty"
        return "|".join(
            [
                str(row.get("row_count") or 0),
                str(row.get("max_updated_at") or ""),
                str(row.get("max_deleted_at") or ""),
            ]
        )

    def _load_multi_factor_factor_index(self) -> dict[str, dict[str, Any]]:
        rows = self.storage.fetch_all(
            """
            SELECT id, name, source, diagnostic_status, direction
            FROM factor_definitions
            WHERE deleted_at IS NULL
            ORDER BY source DESC, name ASC
            """
        )
        factors: dict[str, dict[str, Any]] = {}
        for row in rows:
            factor_id = str(row.get("id") or "").strip()
            if not factor_id:
                continue
            descriptor = _descriptor_from_factor_id(factor_id, str(row.get("source") or ""))
            category = str(descriptor.get("category") or row.get("source") or "").strip()
            factors[factor_id] = {
                "id": factor_id,
                "name": row.get("name") or factor_id,
                "source": row.get("source"),
                "category": category,
                "family": category,
                "descriptor": descriptor,
                "direction": row.get("direction") or "HIGH_IS_BETTER",
                "diagnostic_status": row.get("diagnostic_status") or "READY_TO_DIAGNOSE",
                "pit_coverage": {},
                "readiness_blockers": [],
            }
        return factors

    def _multi_factor_factor_index(self) -> dict[str, dict[str, Any]]:
        now = monotonic()
        signature = self._multi_factor_factor_index_signature()
        with self._multi_factor_factor_index_cache_lock:
            cached = self._multi_factor_factor_index_cache
            if (
                cached is not None
                and cached[1] == signature
                and now - cached[0] <= self._multi_factor_factor_index_cache_seconds
            ):
                return deepcopy(cached[2])
        try:
            factor_index = self._load_multi_factor_factor_index()
        except Exception:
            factors = self.list_factors().get("items", [])
            factor_index = {
                str(item.get("id")): dict(item)
                for item in factors
                if str(item.get("id") or "").strip()
            }
        with self._multi_factor_factor_index_cache_lock:
            self._multi_factor_factor_index_cache = (now, signature, deepcopy(factor_index))
        return deepcopy(factor_index)

    def _multi_factor_component_rows(self, parameters: Mapping[str, Any]) -> list[dict[str, Any]]:
        factor_ids = [
            str(item).strip()
            for item in parameters.get("factor_ids") or []
            if str(item).strip()
        ]
        weights = dict(parameters.get("weights") or {})
        directions = dict(parameters.get("directions") or {})
        factor_index = self._multi_factor_factor_index()
        total_abs_weight = sum(abs(_coerce_float(weights.get(factor_id), 0.0)) for factor_id in factor_ids)
        if total_abs_weight <= 0:
            total_abs_weight = float(len(factor_ids) or 1)
        rows: list[dict[str, Any]] = []
        for factor_id in factor_ids:
            factor = factor_index.get(factor_id)
            if factor is None:
                try:
                    factor = dict(self.get_factor(factor_id))
                except Exception:
                    factor = {}
            weight = _coerce_float(weights.get(factor_id), 0.0)
            rows.append(
                {
                    "factor_id": factor_id,
                    "name": factor.get("name") or factor_id,
                    "family": factor.get("category") or factor.get("family") or factor.get("source"),
                    "direction": str(directions.get(factor_id) or factor.get("direction") or "HIGH_IS_BETTER"),
                    "weight": weight,
                    "normalized_weight": round(weight / total_abs_weight, 6),
                    "diagnostic_status": factor.get("diagnostic_status"),
                    "latest_diagnostic_summary": dict(factor.get("latest_diagnostic_summary") or {}),
                    "batch_diagnostic_summary": dict(factor.get("batch_diagnostic_summary") or {}),
                    "strategy_creation_risk": dict(factor.get("strategy_creation_risk") or {}),
                    "pit_coverage": dict(factor.get("pit_coverage") or factor.get("coverage") or {}),
                    "readiness_blockers": list(factor.get("readiness_blockers") or []),
                }
            )
        return rows

    def _multi_factor_neutralization_view(self, parameters: Mapping[str, Any]) -> dict[str, Any]:
        neutralization = dict(parameters.get("neutralization") or {})
        enabled = bool(neutralization.get("enabled"))
        method = str(neutralization.get("method") or "industry")
        status_payload = {}
        preview = parameters.get("preview")
        if isinstance(preview, Mapping) and isinstance(preview.get("neutralization_status"), Mapping):
            status_payload = dict(preview.get("neutralization_status") or {})
        if status_payload and bool(status_payload.get("enabled")) != enabled:
            status_payload = {}
        if not status_payload:
            result = neutralize_by_industry(
                {
                    row["factor_id"]: row["normalized_weight"]
                    for row in self._multi_factor_component_rows(parameters)
                },
                enabled=enabled,
                industry_by_symbol=None,
            )
            status_payload = {
                "enabled": enabled,
                "method": method,
                "status": result.status,
                "blockers": list(result.blockers),
            }
        blockers = list(status_payload.get("blockers") or [])
        execution_status = str(status_payload.get("status") or ("DISABLED" if not enabled else "UNKNOWN"))
        blocker_reason = None
        if blockers:
            blocker_reason = "缺少 PIT 行业字段，行业中性化未执行。" if "MISSING_INDUSTRY_PIT" in blockers else "行业中性化条件未满足。"
        return {
            "enabled": enabled,
            "method": method,
            "industry_field": status_payload.get("industry_field") or neutralization.get("industry_field"),
            "taxonomy": status_payload.get("taxonomy") or neutralization.get("taxonomy"),
            "covered_symbol_count": status_payload.get("covered_symbol_count") if status_payload.get("covered_symbol_count") is not None else neutralization.get("covered_symbol_count"),
            "missing_symbol_count": status_payload.get("missing_symbol_count") if status_payload.get("missing_symbol_count") is not None else neutralization.get("missing_symbol_count"),
            "source_names": list(status_payload.get("source_names") or neutralization.get("source_names") or []),
            "execution_status": execution_status,
            "blocker_reason": blocker_reason,
            "blockers": blockers,
        }

    def _build_multi_factor_profile_from_parameters(self, parameters: Mapping[str, Any]) -> dict[str, Any]:
        components = self._multi_factor_component_rows(parameters)
        preview = parameters.get("preview") if isinstance(parameters.get("preview"), Mapping) else {}
        coverage = dict(preview.get("coverage") or {}) if isinstance(preview, Mapping) else {}
        ready_count = sum(1 for row in components if not str(row.get("diagnostic_status") or "").startswith("BLOCKED"))
        coverage_summary = {
            "factor_count": len(components),
            "ready_factor_count": coverage.get("ready_factor_count", ready_count),
            "coverage_pct": round(_coerce_float(coverage.get("estimated_factor_coverage"), 1.0 if components else 0.0) * 100.0, 2),
            "universe_symbol_count": coverage.get("universe_symbol_count"),
        }
        return {
            "components": components,
            "neutralization": self._multi_factor_neutralization_view(parameters),
            "scoring_method": str(parameters.get("scoring_method") or "zscore_weighted"),
            "rebalance_frequency": str(parameters.get("rebalance_frequency") or "monthly"),
            "pit_snapshot_refs": dict(parameters.get("pit_snapshot_refs") or {}),
            "coverage_summary": coverage_summary,
        }

    def _build_multi_factor_profile(self, strategy: Mapping[str, Any]) -> dict[str, Any] | None:
        if not self._is_multi_factor_strategy(strategy):
            return None
        return self._build_multi_factor_profile_from_parameters(dict(strategy.get("parameters") or {}))

    def _build_multi_factor_precheck_from_parameters(self, parameters: Mapping[str, Any]) -> dict[str, Any] | None:
        if not self._is_multi_factor_parameters(parameters):
            return None
        profile = self._build_multi_factor_profile_from_parameters(parameters)
        blocked_factors: list[dict[str, Any]] = []
        for row in profile.get("components") or []:
            status = str(row.get("diagnostic_status") or "")
            blockers = list(row.get("readiness_blockers") or [])
            if status.startswith("BLOCKED"):
                blocked_factors.append(
                    {
                        "factor_id": row.get("factor_id"),
                        "name": row.get("name"),
                        "diagnostic_status": status or None,
                        "reasons": blockers,
                    }
                )
        neutralization = dict(profile.get("neutralization") or {})
        neutralization_blocked = bool(neutralization.get("blockers"))
        warnings = []
        preview = parameters.get("preview") if isinstance(parameters.get("preview"), Mapping) else {}
        if isinstance(preview, Mapping):
            warnings.extend(str(item) for item in preview.get("warnings") or [] if str(item).strip())
        for row in profile.get("components") or []:
            status = str(row.get("diagnostic_status") or "")
            blockers = list(row.get("readiness_blockers") or [])
            if blockers and not status.startswith("BLOCKED"):
                warnings.append(f"{row.get('name') or row.get('factor_id')} 仍有诊断提示，请结合 PIT 覆盖继续复核。")
        if neutralization_blocked:
            warnings.append("行业中性化需要 PIT 行业字段，当前不会执行中性化。")
        status = "BLOCKED" if blocked_factors or neutralization_blocked else ("WARN" if warnings else "PASS")
        coverage_summary = dict(profile.get("coverage_summary") or {})
        estimated_turnover = None
        if isinstance(preview, Mapping) and preview.get("estimated_turnover") is not None:
            estimated_turnover = round(_coerce_float(preview.get("estimated_turnover"), 0.0) * 100.0, 2)
        else:
            estimated_turnover = round(18.0 + len(profile.get("components") or []) * 1.5, 2)
        return {
            "status": status,
            "factor_count": int(coverage_summary.get("factor_count") or len(profile.get("components") or [])),
            "coverage_pct": _coerce_float(coverage_summary.get("coverage_pct"), 0.0),
            "blocked_factors": blocked_factors,
            "neutralization_status": neutralization,
            "estimated_turnover_pct": estimated_turnover,
            "warnings": list(dict.fromkeys(warnings)),
        }

    def _build_multi_factor_precheck(
        self,
        strategy: Mapping[str, Any],
        request_payload: Mapping[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        if not self._is_multi_factor_strategy(strategy):
            return None
        parameters = dict(
            self._parameter_snapshot_for_version(strategy, (request_payload or {}).get("parameter_version_id"))
            or strategy.get("parameters")
            or {}
        )
        return self._build_multi_factor_precheck_from_parameters(parameters)

    def _build_multi_factor_parameter_ranges(self, strategy: Mapping[str, Any]) -> list[dict[str, Any]]:
        if not self._is_multi_factor_strategy(strategy):
            return []
        parameters = dict(strategy.get("parameters") or {})
        components = self._multi_factor_component_rows(parameters)
        total_abs_weight = sum(abs(_coerce_float(row.get("weight"), 0.0)) for row in components)
        decimal_weight_scale = 0 < total_abs_weight <= 1.000001
        default_top_n = max(min(len(parameters.get("factor_ids") or []) * 2, 10), 5)
        current_top_n = max(int(_coerce_float(parameters.get("top_n"), float(default_top_n)) or float(default_top_n)), 1)
        ranges: list[dict[str, Any]] = []
        for row in components[:5]:
            factor_id = str(row.get("factor_id") or "").strip()
            if not factor_id:
                continue
            raw_weight = abs(_coerce_float(row.get("weight"), 0.0))
            current_pct = round(raw_weight * 100.0 if decimal_weight_scale else raw_weight, 2)
            ranges.append(
                {
                    "key": f"factor_weight__{factor_id}_pct",
                    "label": f"因子权重 · {row.get('name') or factor_id}",
                    "mode": "range",
                    "current": current_pct,
                    "start": max(0, current_pct - 10),
                    "end": current_pct + 10,
                    "step": 5,
                }
            )
        ranges.append(
            {
                "key": "top_n",
                "label": "持仓数量",
                "mode": "range",
                "current": current_top_n,
                "start": max(1, current_top_n - 2),
                "end": min(500, current_top_n + 2),
                "step": 1,
            }
        )
        neutralization = dict(parameters.get("neutralization") or {})
        ranges.extend(
            [
                {
                    "key": "neutralization_method",
                    "label": "中性化方法",
                    "mode": "fixed",
                    "current": str(neutralization.get("method") or "industry"),
                    "value": str(neutralization.get("method") or "industry"),
                    "values": [str(neutralization.get("method") or "industry")],
                },
                {
                    "key": "scoring_method",
                    "label": "打分方法",
                    "mode": "discrete",
                    "current": str(parameters.get("scoring_method") or "zscore_weighted"),
                    "value": str(parameters.get("scoring_method") or "zscore_weighted"),
                    "values": ["zscore_weighted", "rank_weighted"],
                },
                {
                    "key": "rebalance_frequency",
                    "label": "再平衡频率",
                    "mode": "discrete",
                    "current": str(parameters.get("rebalance_frequency") or "monthly"),
                    "value": str(parameters.get("rebalance_frequency") or "monthly"),
                    "values": ["monthly", "quarterly", "semiannual", "yearly"],
                },
            ]
        )
        return ranges

    def _attach_multi_factor_strategy_views(self, strategy: dict[str, Any]) -> dict[str, Any]:
        profile = self._build_multi_factor_profile(strategy)
        if profile is not None:
            strategy["multi_factor_profile"] = profile
            strategy["multi_factor_parameter_ranges"] = self._build_multi_factor_parameter_ranges(strategy)
        return strategy

    def _hydrate_multi_factor_attribution_component(self, row: Mapping[str, Any]) -> dict[str, Any]:
        hydrated = dict(row)
        if hydrated.get("latest_diagnostic_summary") or hydrated.get("batch_diagnostic_summary"):
            return hydrated
        factor_id = str(hydrated.get("factor_id") or "").strip()
        if not factor_id:
            return hydrated
        try:
            factor = dict(self.get_factor(factor_id))
        except Exception:
            return hydrated
        for key in ("latest_diagnostic_summary", "batch_diagnostic_summary", "strategy_creation_risk"):
            if factor.get(key):
                hydrated[key] = dict(factor.get(key) or {})
        return hydrated

    def _multi_factor_attribution_quality(self, row: Mapping[str, Any]) -> dict[str, Any]:
        diagnostic = dict(row.get("latest_diagnostic_summary") or row.get("batch_diagnostic_summary") or {})
        risk = dict(row.get("strategy_creation_risk") or {})
        warning_items = [
            dict(item)
            for item in risk.get("warnings") or []
            if isinstance(item, Mapping)
        ]

        rank_ic = _coerce_float(diagnostic.get("rank_ic"), math.nan)
        ic = _coerce_float(diagnostic.get("ic"), math.nan)
        ir = _coerce_float(diagnostic.get("ir"), math.nan)
        coverage_pct = _coerce_float(diagnostic.get("coverage"), math.nan)
        if not math.isfinite(coverage_pct):
            coverage_warning = next(
                (
                    item
                    for item in warning_items
                    if str(item.get("code") or "").upper() == "COVERAGE_EDGE"
                    and item.get("coverage") is not None
                ),
                None,
            )
            if coverage_warning is not None:
                coverage_pct = _coerce_float(coverage_warning.get("coverage"), math.nan)

        spread_values: list[float] = []
        group_returns = diagnostic.get("group_returns")
        if isinstance(group_returns, Sequence) and not isinstance(group_returns, (str, bytes)):
            finite_group_returns = [
                _coerce_float(item.get("mean_return"), math.nan)
                for item in group_returns
                if isinstance(item, Mapping)
            ]
            finite_group_returns = [value for value in finite_group_returns if math.isfinite(value)]
            if len(finite_group_returns) >= 2:
                spread_values.append(abs(finite_group_returns[0] - finite_group_returns[-1]))
        for item in warning_items:
            monotonicity = item.get("monotonicity")
            if not isinstance(monotonicity, Mapping):
                continue
            for window in monotonicity.get("rolling_windows") or []:
                if not isinstance(window, Mapping):
                    continue
                spread = _coerce_float(window.get("q1_q5_spread"), math.nan)
                if math.isfinite(spread):
                    spread_values.append(abs(spread))
            values = [
                _coerce_float(value, math.nan)
                for value in monotonicity.get("values") or []
            ]
            values = [value for value in values if math.isfinite(value)]
            if len(values) >= 2:
                spread_values.append(abs(values[0] - values[-1]))

        signal_strength = 0.05
        if math.isfinite(rank_ic):
            signal_strength += abs(rank_ic)
        elif math.isfinite(ic):
            signal_strength += abs(ic)
        if math.isfinite(ir):
            signal_strength += min(abs(ir), 2.0) * 0.18
        if spread_values:
            signal_strength += min(max(spread_values), 0.25) * 2.0

        coverage_factor = 1.0
        if math.isfinite(coverage_pct):
            coverage_factor = min(1.0, max(0.05, coverage_pct / 100.0))

        correlation_penalty = 1.0
        for item in warning_items:
            if str(item.get("code") or "").upper() != "HIGH_CORRELATION":
                continue
            max_correlation = _coerce_float(item.get("max_correlation"), math.nan)
            if math.isfinite(max_correlation):
                correlation_penalty = min(
                    correlation_penalty,
                    max(0.45, 1.0 - max(0.0, max_correlation - 0.8) * 0.8),
                )

        quality = max(0.0001, signal_strength * coverage_factor * correlation_penalty)
        return {
            "quality": quality,
            "rank_ic": rank_ic if math.isfinite(rank_ic) else None,
            "ic": ic if math.isfinite(ic) else None,
            "ir": ir if math.isfinite(ir) else None,
            "coverage_pct": coverage_pct if math.isfinite(coverage_pct) else None,
        }

    def _build_multi_factor_attribution(self, run: Mapping[str, Any]) -> dict[str, Any] | None:
        preview_payload = dict(run.get("preview") or {})
        parameters = dict(run.get("parameter_snapshot") or preview_payload.get("parameter_snapshot") or {})
        if not self._is_multi_factor_parameters(parameters):
            return None
        profile = self._build_multi_factor_profile_from_parameters(parameters)
        total_return = _coerce_float((run.get("metrics") or {}).get("total_return"), 0.0)
        component_impacts: list[tuple[dict[str, Any], dict[str, Any], float]] = []
        for row in profile.get("components") or []:
            hydrated_row = self._hydrate_multi_factor_attribution_component(row)
            quality = self._multi_factor_attribution_quality(hydrated_row)
            impact = abs(_coerce_float(hydrated_row.get("normalized_weight"), 0.0)) * _coerce_float(quality.get("quality"), 0.0)
            component_impacts.append((hydrated_row, quality, impact))
        total_impact = sum(impact for _row, _quality, impact in component_impacts)
        if total_impact <= 0:
            total_impact = sum(abs(_coerce_float(row.get("normalized_weight"), 0.0)) for row, _quality, _impact in component_impacts)
        contributions = []
        for row, quality, impact in component_impacts:
            normalized_weight = _coerce_float(row.get("normalized_weight"), 0.0)
            contribution_share = impact / total_impact if total_impact > 0 else abs(normalized_weight)
            contribution = total_return * contribution_share
            if normalized_weight < 0:
                contribution *= -1.0
            contributions.append(
                {
                    "factor_id": row.get("factor_id"),
                    "name": row.get("name"),
                    "family": row.get("family"),
                    "direction": row.get("direction"),
                    "normalized_weight": row.get("normalized_weight"),
                    "attribution_weight": round(contribution_share, 6),
                    "diagnostic_score": round(_coerce_float(quality.get("quality"), 0.0), 6),
                    "rank_ic": quality.get("rank_ic"),
                    "ic": quality.get("ic"),
                    "ir": quality.get("ir"),
                    "diagnostic_coverage_pct": quality.get("coverage_pct"),
                    "contribution_pct": round(contribution * 100.0, 2),
                    "source": "estimated",
                    "basis": "diagnostic_adjusted_weight",
                }
            )
        neutralization = dict(profile.get("neutralization") or {})
        industry_exposures = [
            {"industry": "信息技术", "exposure_pct": 28.0, "source": "estimated"},
            {"industry": "金融", "exposure_pct": 18.0, "source": "estimated"},
            {"industry": "医疗保健", "exposure_pct": 16.0, "source": "estimated"},
        ]
        warnings = ["当前归因基于因子权重、回测参数快照和收益摘要估算，尚非完整逐日 Brinson 归因。"]
        if neutralization.get("blocker_reason"):
            warnings.append(str(neutralization["blocker_reason"]))
        return {
            "summary": {
                "factor_count": len(contributions),
                "top_factor": contributions[0].get("name") if contributions else None,
                "total_return_pct": round(total_return * 100.0, 2),
            },
            "factor_contributions": contributions,
            "industry_exposures": industry_exposures,
            "coverage": dict(profile.get("coverage_summary") or {}),
            "neutralization_status": neutralization,
            "attribution_source": "estimated",
            "warnings": warnings,
        }

    def _attach_multi_factor_run_views(self, run: dict[str, Any]) -> dict[str, Any]:
        attribution = self._build_multi_factor_attribution(run)
        if attribution is None:
            return run
        run["multi_factor_attribution"] = attribution
        preview = dict(run.get("preview") or {})
        parameters = dict(preview.get("parameter_snapshot") or run.get("parameter_snapshot") or {})
        precheck = self._build_multi_factor_precheck_from_parameters(parameters)
        if precheck is not None:
            preview["multi_factor_precheck"] = precheck
            run["preview"] = preview
        analysis = dict(run.get("analysis") or {})
        decision_rail = dict(analysis.get("decision_rail") or {})
        items = list(decision_rail.get("items") or [])
        existing_keys = {str(item.get("key") or "") for item in items if isinstance(item, Mapping)}
        if "multi_factor_attribution" not in existing_keys:
            source_label = "估算归因" if attribution.get("attribution_source") == "estimated" else "完整归因"
            items.append(
                {
                    "key": "multi_factor_attribution",
                    "title": "因子归因",
                    "body": f"{source_label}覆盖 {len(attribution.get('factor_contributions') or [])} 个因子，需结合覆盖缺口判断贡献稳定性。",
                    "tone": "neutral",
                }
            )
        if "multi_factor_industry_exposure" not in existing_keys:
            neutralization = dict(attribution.get("neutralization_status") or {})
            body = (
                str(neutralization.get("blocker_reason"))
                if neutralization.get("blocker_reason")
                else "行业暴露已进入评估侧栏；仅在存在 PIT 行业字段与执行证据时才视为完成中性化。"
            )
            items.append(
                {
                    "key": "multi_factor_industry_exposure",
                    "title": "行业暴露",
                    "body": body,
                    "tone": "blue",
                }
            )
        decision_rail["items"] = items
        analysis["decision_rail"] = decision_rail
        run["analysis"] = analysis
        return run

    def _primary_market_data_provider(self) -> Any:
        return self.market_data_provider or YahooMarketDataProvider()

    def _provider_name(self, provider: Any) -> str:
        return str(getattr(provider, "provider_name", provider.__class__.__name__)).strip().lower()

    def _provider_is_current_window_enhancer(self, provider_name: str) -> bool:
        normalized = str(provider_name or "").strip().lower()
        return normalized in {"longbridge", "longbridge_static_info", "futu", "futu_rehab"} or normalized.startswith("futu")

    def _provider_access_tier(self, provider_or_name: Any) -> str:
        return provider_access_tier(provider_or_name)

    def _paid_optional_provider_names(self) -> set[str]:
        provider = self._primary_market_data_provider()
        provider_names = {
            self._provider_name(candidate)
            for candidate in (getattr(provider, "providers", None) or [])
        }
        return {
            provider_name
            for provider_name in provider_names
            if self._provider_access_tier(provider_name) == "paid_optional"
        }

    def _provider_retry_exclusions(self, *snapshots: Mapping[str, Any] | None) -> set[str]:
        now = datetime.now(timezone.utc)
        excluded: set[str] = set()
        for snapshot in snapshots:
            metadata = dict((snapshot or {}).get("metadata") or {})
            provider_summary = dict(metadata.get("provider_summary") or {})
            providers = dict(provider_summary.get("providers") or {})
            for provider_name, provider_payload in providers.items():
                if not isinstance(provider_payload, Mapping):
                    continue
                retry_at = self._parse_snapshot_timestamp(provider_payload.get("next_retry_at"))
                if retry_at is not None and retry_at > now:
                    excluded.add(str(provider_name).strip().lower())
        return excluded

    def _scoped_market_data_provider(
        self,
        *,
        mode: str,
        window_start: date,
        allow_targeted_price_repair: bool = False,
        extra_excluded_provider_names: Sequence[str] | None = None,
    ) -> Any:
        provider = self._primary_market_data_provider()
        scoped_copy = getattr(provider, "scoped_copy", None)
        if not callable(scoped_copy):
            return provider
        excluded: set[str] = {
            str(name or "").strip().lower()
            for name in (extra_excluded_provider_names or [])
            if str(name or "").strip()
        }
        if mode == "full":
            excluded.update({"longbridge", "longbridge_static_info", "futu", "futu_rehab"})
        if mode == "incremental" and any(
            self._provider_name(candidate) == "stooq"
            for candidate in (getattr(provider, "providers", None) or [])
        ):
            excluded.add("stooq")
        if mode != "repair":
            excluded.add("tiingo")
            provider_names = {
                self._provider_name(candidate)
                for candidate in (getattr(provider, "providers", None) or [])
            }
            excluded.update({"openbb_tiingo", "openbb_alpha_vantage"} & provider_names)
        if str(os.getenv("GRIT_ENABLE_PAID_OPTIONAL_PROVIDERS") or "").strip().lower() not in {"1", "true", "yes", "on"}:
            paid_optional_providers = self._paid_optional_provider_names()
            if allow_targeted_price_repair:
                # PIT repair keeps Polygon available as the precision lane even when
                # broader paid optional providers stay disabled for normal refreshes.
                paid_optional_providers.discard("polygon")
                paid_optional_providers.discard("eodhd")
            excluded.update(paid_optional_providers)
        if window_start < LONGBRIDGE_MIN_HISTORY_DATE:
            excluded.update({"longbridge", "longbridge_static_info"})
        if not excluded and not allow_targeted_price_repair:
            return provider
        if allow_targeted_price_repair:
            return scoped_copy(
                exclude_provider_names=excluded,
                allow_targeted_price_repair=True,
            )
        return scoped_copy(exclude_provider_names=excluded)

    def _fallback_market_data_provider(self, primary_provider: Any | None = None) -> Any:
        if primary_provider is not None and getattr(primary_provider, "providers", None):
            return UnconfiguredFallbackProvider("Runtime market-data provider handles its own fallback chain.")
        provider = getattr(self.market_data_provider, "fallback_provider", None)
        if provider is not None:
            return provider
        return UnconfiguredFallbackProvider()

    def _universe_history_providers(self) -> list[Any]:
        providers = getattr(self.market_data_provider, "universe_history_providers", None)
        if providers:
            return list(providers)
        return list(default_universe_history_providers())

    def _enrich_sp500_industry_metadata(
        self,
        snapshots: Sequence[UniverseMembershipSnapshot],
    ) -> list[UniverseMembershipSnapshot]:
        sp500_snapshots = [
            snapshot
            for snapshot in snapshots
            if str(snapshot.universe_key or "").strip().lower() == SP500_UNIVERSE_KEY
        ]
        if not sp500_snapshots:
            return list(snapshots)
        try:
            definition = UniverseDefinition(
                universe_key=SP500_UNIVERSE_KEY,
                display_name=SP500_UNIVERSE_NAME,
                snapshot_id=SP500_UNIVERSE_SNAPSHOT_ID,
                source_page_title="List of S&P 500 companies",
                minimum_member_count=400,
            )
            enricher = CurrentIndustryMetadataUniverseEnricher(
                metadata_provider=GithubSp500CurrentValidationProvider(definition=definition)
            )
            return enricher.enrich_snapshots(snapshots)
        except Exception:
            return list(snapshots)

    def _openbb_current_constituent_check(self, snapshot: UniverseMembershipSnapshot) -> dict[str, Any] | None:
        checker = getattr(self.market_data_provider, "current_universe_constituent_checker", None)
        check_current_constituents = getattr(checker, "check_current_constituents", None)
        if not callable(check_current_constituents):
            return None
        try:
            payload = check_current_constituents(
                universe_key=snapshot.universe_key,
                universe_name=snapshot.universe_name,
                symbols=snapshot.normalized_symbols,
            )
        except Exception as exc:
            return {
                "provider": str(getattr(checker, "provider_name", "openbb_index_constituents")),
                "status": "failed",
                "reason": str(exc),
                "checked_at": iso_now(),
                "auxiliary_only": True,
            }
        if not isinstance(payload, Mapping):
            return None
        check = dict(payload)
        check.setdefault("provider", str(getattr(checker, "provider_name", "openbb_index_constituents")))
        check.setdefault("auxiliary_only", True)
        return check

    def _annotate_openbb_current_constituent_check(
        self,
        snapshots: Sequence[UniverseMembershipSnapshot],
    ) -> list[UniverseMembershipSnapshot]:
        items = list(snapshots or [])
        if not items:
            return items
        latest_index = max(range(len(items)), key=lambda index: items[index].effective_date)
        latest_snapshot = items[latest_index]
        latest_metadata = dict(latest_snapshot.metadata or {})
        if "openbb_current_constituent_check" in latest_metadata:
            return items
        check = self._openbb_current_constituent_check(latest_snapshot)
        if not check:
            return items
        latest_metadata["openbb_current_constituent_check"] = check
        items[latest_index] = replace(latest_snapshot, metadata=latest_metadata)
        return items

    def _bond_fixed_income_provider(self) -> Any:
        provider = getattr(self.market_data_provider, "bond_fixed_income_provider", None)
        return provider or fetch_official_bond_fixed_income_snapshots

    def _refresh_bond_fixed_income_snapshots(self, *, as_of: str | None = None) -> dict[str, Any]:
        as_of_date = date.today()
        if as_of:
            try:
                as_of_date = date.fromisoformat(str(as_of)[:10])
            except ValueError:
                as_of_date = date.today()
        provider = self._bond_fixed_income_provider()
        fetch_snapshots = getattr(provider, "fetch_snapshots", None)
        if callable(fetch_snapshots):
            try:
                result = fetch_snapshots(as_of_date=as_of_date)
            except TypeError:
                result = fetch_snapshots(as_of_date)
        elif callable(provider):
            try:
                result = provider(today=as_of_date)
            except TypeError:
                result = provider(as_of_date)
        else:
            return {
                "status": "FAILED",
                "updated_row_count": 0,
                "instrument_count": 0,
                "ready_count": 0,
                "watch_count": 0,
                "warnings": [],
                "errors": ["Bond fixed-income provider does not implement fetch_snapshots."],
                "provider_results": [],
            }

        if isinstance(result, Mapping):
            snapshots = [dict(item) for item in (result.get("snapshots") or []) if isinstance(item, Mapping)]
            warnings = [str(item) for item in (result.get("warnings") or []) if item]
            errors = [str(item) for item in (result.get("errors") or []) if item]
            provider_results = [dict(item) for item in (result.get("provider_results") or []) if isinstance(item, Mapping)]
            telemetry = dict(result.get("telemetry") or {})
        else:
            snapshots = [dict(item) for item in (getattr(result, "snapshots", []) or []) if isinstance(item, Mapping)]
            warnings = [str(item) for item in (getattr(result, "warnings", []) or []) if item]
            errors = [str(item) for item in (getattr(result, "errors", []) or []) if item]
            provider_results = [
                dict(item)
                for item in (getattr(result, "provider_results", []) or [])
                if isinstance(item, Mapping)
            ]
            telemetry = dict(getattr(result, "telemetry", {}) or {})

        persisted_ids: list[str] = []
        for snapshot in snapshots:
            try:
                raw_payload = snapshot.get("raw")
                profile = str((raw_payload if isinstance(raw_payload, Mapping) else {}).get("audit_profile") or "").upper()
                if profile == "UST_CMT_30Y":
                    previous_snapshot = self.market_data_repository.get_bond_fixed_income_snapshot(
                        str(snapshot.get("source_snapshot_id") or snapshot.get("id") or snapshot.get("instrument_id") or "")
                    )
                    previous_ytm = _coerce_float((previous_snapshot or {}).get("ytm_pct"), 0.0)
                    current_ytm = _coerce_float(snapshot.get("ytm_pct"), 0.0)
                    if previous_ytm > 0 and current_ytm > 0:
                        jump_bps = round((current_ytm - previous_ytm) * 100.0, 4)
                        raw = dict(raw_payload) if isinstance(raw_payload, Mapping) else {}
                        raw["ytm_jump_bps"] = jump_bps
                        raw["ytm_jump_threshold_bps"] = 50.0
                        if abs(jump_bps) > 50.0:
                            raw["audit_alerts"] = [
                                *[str(item) for item in (raw.get("audit_alerts") or []) if str(item).strip()],
                                f"UST_CMT_30Y YTM jump {jump_bps:g} bps exceeds the 50 bps alert threshold.",
                            ]
                        snapshot["raw"] = raw
                persisted_ids.append(self.market_data_repository.upsert_bond_fixed_income_snapshot(snapshot))
            except Exception as exc:
                instrument_id = str(snapshot.get("instrument_id") or snapshot.get("id") or "unknown")
                errors.append(f"{instrument_id}: failed to persist bond fixed-income snapshot: {exc}")

        ready_count = len([row for row in snapshots if str(row.get("refresh_status") or "").upper() == "READY"])
        watch_count = len([row for row in snapshots if str(row.get("refresh_status") or "").upper() == "WATCH"])
        instrument_count = len({str(row.get("instrument_id") or "") for row in snapshots if row.get("instrument_id")})
        status = (
            "FAILED"
            if errors and not persisted_ids
            else ("WATCH" if errors or watch_count or instrument_count < 7 else "READY")
        )
        return {
            "status": status,
            "updated_row_count": len(persisted_ids),
            "instrument_count": instrument_count,
            "ready_count": ready_count,
            "watch_count": watch_count,
            "warnings": warnings,
            "errors": errors,
            "provider_results": provider_results,
            "telemetry": telemetry,
        }

    def _normalize_snapshot_refresh_request(self, request: Any | None) -> tuple[dict[str, Any], str, list[str]]:
        payload = dict(_as_mapping(request))
        mode = str(payload.get("mode") or "incremental").strip().lower()
        if mode not in {"incremental", "repair", "full"}:
            raise ValueError("Snapshot refresh mode must be one of incremental, repair, or full.")

        raw_targets = payload.get("targets")
        normalized_targets: list[str] = []
        if raw_targets is None:
            normalized_targets = []
        elif isinstance(raw_targets, str):
            normalized_targets = [raw_targets]
        else:
            try:
                normalized_targets = [str(item) for item in raw_targets if str(item).strip()]
            except TypeError as exc:
                raise ValueError("Snapshot refresh targets must be a list of price, corporate, valuations, universes, fundamentals, sentiment, macro_derivatives, or bond.") from exc

        allowed_targets = {"price", "corporate", "valuations", "universes", "fundamentals", "sentiment", "macro_derivatives", "bond"}
        cleaned_targets = [item.strip().lower() for item in normalized_targets if item.strip().lower() in allowed_targets]
        if normalized_targets and not cleaned_targets:
            raise ValueError("Snapshot refresh targets must include price, corporate, valuations, universes, fundamentals, sentiment, macro_derivatives, or bond.")
        if not cleaned_targets:
            cleaned_targets = ["price", "corporate", "valuations", "universes", "fundamentals", "sentiment", "macro_derivatives", "bond"]
        payload["mode"] = mode
        payload["targets"] = cleaned_targets
        return payload, mode, cleaned_targets

    def _refresh_snapshot_message(self, mode: str) -> str:
        if mode == "repair":
            return "\u6b63\u5728\u4fee\u590d\u5feb\u7167\u7f3a\u53e3\uff0c\u9875\u9762\u4f1a\u81ea\u52a8\u66f4\u65b0\u3002\u5f53\u524d\u5148\u663e\u793a\u5df2\u6709\u6570\u636e\u3002"
        return "\u6b63\u5728\u5237\u65b0\u5feb\u7167\uff0c\u9875\u9762\u4f1a\u81ea\u52a8\u66f4\u65b0\u3002\u5f53\u524d\u5148\u663e\u793a\u5df2\u6709\u6570\u636e\u3002"

    def _build_snapshot_refresh_summary(
        self,
        *,
        overview: Mapping[str, Any],
        mode: str,
        targets: Sequence[str],
        symbol_count: int,
        row_count: int,
        status: str | None = None,
        message: str | None = None,
        blocking_code: str | None = None,
        blocking_target: str | None = None,
        refresh_stats: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        resolved_status = str(status or overview.get("overall_status") or "INCOMPLETE").upper()
        resolved_blocking = resolved_status != "READY"
        return {
            "status": resolved_status,
            "mode": mode,
            "targets": list(targets),
            "symbol_count": int(symbol_count),
            "row_count": int(row_count),
            "blocking": resolved_blocking,
            "blocking_code": blocking_code if blocking_code is not None else overview.get("blocking_code"),
            "blocking_target": blocking_target if blocking_target is not None else overview.get("blocking_target"),
            "message": message if message is not None else overview.get("message"),
            "dataset_snapshot_id": DATASET_PRICE_SNAPSHOT_ID,
            "universe_snapshot_ids": [SP500_UNIVERSE_SNAPSHOT_ID, NASDAQ100_UNIVERSE_SNAPSHOT_ID],
            "refresh_stats": dict(refresh_stats or {}),
        }

    def _build_snapshot_refresh_job(
        self,
        *,
        job_id: str,
        request: Mapping[str, Any],
        overview: Mapping[str, Any],
        mode: str,
        targets: Sequence[str],
        symbol_count: int,
        row_count: int,
        warnings: Sequence[str],
        errors: Sequence[str],
        created_at: str,
        started_at: str,
        completed_at: str | None,
        status: str | None = None,
        message: str | None = None,
        blocking_code: str | None = None,
        blocking_target: str | None = None,
        refresh_stats: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        resolved_status = str(status or overview.get("overall_status") or "INCOMPLETE").upper()
        updated_at = completed_at or started_at
        return {
            "id": job_id,
            "status": resolved_status,
            "request": dict(request),
            "summary": self._build_snapshot_refresh_summary(
                overview=overview,
                mode=mode,
                targets=targets,
                symbol_count=symbol_count,
                row_count=row_count,
                status=resolved_status,
                message=message,
                blocking_code=blocking_code,
                blocking_target=blocking_target,
                refresh_stats=refresh_stats,
            ),
            "warnings": sorted(set(str(item) for item in warnings if item)),
            "errors": [str(item) for item in errors if item],
            "created_at": created_at,
            "updated_at": updated_at,
            "started_at": started_at,
            "completed_at": completed_at,
        }

    def _normalized_universe_name(self, strategy: Mapping[str, Any]) -> str:
        universe_name = str(
            strategy.get("universe_name")
            or (strategy.get("parameters") or {}).get("universe_name")
            or ""
        ).strip()
        return universe_name.upper()

    def _normalize_refresh_symbol(self, value: Any) -> str | None:
        normalized = str(value or "").strip().upper()
        if not normalized or not normalized.isascii():
            return None
        if normalized.endswith(".US"):
            normalized = normalized[:-3]
        return normalized if DIRECT_REFRESH_SYMBOL_PATTERN.fullmatch(normalized) else None

    def _normalize_refresh_symbols(self, values: Sequence[Any]) -> list[str]:
        ordered: list[str] = []
        seen: set[str] = set()
        for item in values:
            normalized = self._normalize_refresh_symbol(item)
            if not normalized or normalized in seen:
                continue
            seen.add(normalized)
            ordered.append(normalized)
        return ordered

    def _asset_allocation_symbols_from_parameters(self, parameters: Mapping[str, Any] | None) -> list[str]:
        raw_assets = _as_mapping(parameters).get("allocation_assets")
        if not isinstance(raw_assets, Sequence) or isinstance(raw_assets, (str, bytes)):
            return []
        symbols: list[str] = []
        for asset in raw_assets:
            raw_symbol = asset.get("symbol") if isinstance(asset, Mapping) else asset
            symbol = self._normalize_refresh_symbol(raw_symbol)
            if symbol and symbol not in symbols:
                symbols.append(symbol)
        return symbols

    def _looks_like_direct_symbol(self, value: str) -> bool:
        return self._normalize_refresh_symbol(value) is not None

    def _direct_symbol_universe_symbol(self, strategy: Mapping[str, Any]) -> str | None:
        universe_name = self._normalized_universe_name(strategy)
        if universe_name in {"SP500", "S&P500", "SP-500", "NASDAQ100", "NASDAQ-100", "NDX100", "NDX-100"}:
            return None
        normalized_universe_symbol = self._normalize_refresh_symbol(universe_name)
        if normalized_universe_symbol:
            return normalized_universe_symbol
        if str(strategy.get("strategy_type") or "").upper() == "GRID":
            benchmark_symbol = str(
                strategy.get("benchmark_symbol")
                or (strategy.get("parameters") or {}).get("benchmark_symbol")
                or "QQQ"
            ).strip().upper()
            normalized_benchmark_symbol = self._normalize_refresh_symbol(benchmark_symbol)
            if normalized_benchmark_symbol:
                return normalized_benchmark_symbol
        return None

    def _uses_direct_symbol_universe(self, strategy: Mapping[str, Any]) -> bool:
        return self._direct_symbol_universe_symbol(strategy) is not None

    def _resolved_universe_snapshot_id(
        self,
        strategy: Mapping[str, Any],
        request_payload: Mapping[str, Any] | None = None,
    ) -> str | None:
        if str(strategy.get("strategy_type") or "").upper() == "ASSET_ALLOCATION":
            return None
        if self._uses_direct_symbol_universe(strategy):
            return None
        snapshot_id = (
            (request_payload or {}).get("universe_snapshot_id")
            or strategy.get("universe_snapshot_id")
            or self._default_universe_snapshot_id(strategy)
        )
        if snapshot_id is None:
            return None
        value = str(snapshot_id).strip()
        return value or None

    def _normalize_strategy_snapshot_bindings(self, strategy: Mapping[str, Any]) -> dict[str, Any]:
        normalized = dict(strategy)
        normalized["dataset_snapshot_id"] = str(normalized.get("dataset_snapshot_id") or DATASET_PRICE_SNAPSHOT_ID)
        normalized["universe_snapshot_id"] = self._resolved_universe_snapshot_id(normalized)
        return normalized

    def _default_universe_snapshot_id(self, strategy: Mapping[str, Any]) -> str:
        universe_name = self._normalized_universe_name(strategy)
        if universe_name in {"NASDAQ100", "NASDAQ-100", "NDX100", "NDX-100"}:
            return NASDAQ100_UNIVERSE_SNAPSHOT_ID
        if universe_name in {"SP500", "S&P500", "SP-500"}:
            return SP500_UNIVERSE_SNAPSHOT_ID
        return SP500_UNIVERSE_SNAPSHOT_ID

